(window.GIM_TP=window.GIM_TP||{})["Horayot.0"]={"from":0,"a":[[["מתני׳ \u0001הורו\u0002 בית דין לעבור על אחת מכל מצות האמורות בתורה והלך היחיד ועשה שוגג על פיהם בין שעשו ועשה עמהן בין שעשו ועשה אחריהן בין שלא עשו ועשה פטור מפני שתלה בב\"ד","הורו ב\"ד וידע אחד מהן שטעו או תלמיד והוא ראוי להוראה והלך ועשה על פיהן בין שעשו ועשה עמהן בין שעשו ועשה אחריהן בין שלא עשו ועשה הרי זה חייב מפני שלא תלה בב\"ד זה הכלל התולה בעצמו חייב והתולה בב\"ד פטור:","\u0001גמ׳\u0002 אמר שמואל לעולם אין ב\"ד חייבין עד שיאמרו להם מותרין אתם רב דימי מנהרדעא אמר עד שיאמרו להם מותרין אתם לעשות מ\"ט לפי שלא נגמרה הוראה","אמר אביי אף אנן נמי תנינא חזר לעירו שנה ולימד כדרך שלימד פטור הורה לעשות חייב","א\"ר אבא אף אנן נמי תנינא הורו לה ב\"ד להנשא והלכה וקלקלה חייבת בקרבן שלא התירו לה אלא להנשא","אמר רבינא אף אנן נמי תנינא הורו ב\"ד לעבור על אחת מכל מצות האמורות בתורה תו לא מידי","איכא דאמרי אמר שמואל אין ב\"ד חייבין עד שיאמרו להם מותרים אתם לעשות רב דימי מנהרדעא אמר אפילו מותרים אתם נגמרה הוראה אמר אביי והא לא תנן הכי חזר לעירו ושנה או לימד כדרך שלימד פטור הורה לעשות חייב","אמר רבי אבא והא לא תנן הכי הורו לה ב\"ד להנשא והלכה וקלקלה חייבת בקרבן שלא התירו לה אלא להנשא","אמר רבינא והא לא תנן הכי הורו ב\"ד לעבור על אחת מכל מצות האמורות בתורה תו לא מידי:","והלך היחיד ועשה שוגג על פיהם: וניתני ועשה על פיהם שוגג למה לי אמר רבא שוגג לאתויי הורו ב\"ד שחלב מותר ונתחלף לו חלב בשומן ואכלו פטור על פיהם על פיהם ממש","ואיכא דאמרי אמר רבא שוגג על פיהם הוא דפטור אבל נתחלף לו חלב בשומן ואכלו חייב","מילתא דפשיטא ליה לרבא קמיבעיא ליה לרמי בר חמא דבעי רמי בר חמא הורו ב\"ד שחלב מותר ונתחלף לו בשומן ואכלו מהו","אמר רבא תא שמע הלך יחיד ועשה שוגג על פיהם כו' שוגג על פיהם למה לי לאו לאתויי הורו ב\"ד שחלב מותר ונתחלף לו חלב בשומן ואכלו פטור דלמא שוגג על פיהם הוא דפטור אבל נתחלף לו חלב בשומן ואכלו חייב","איכא דאמרי אמר רבא ת\"ש הלך יחיד ועשה שוגג על פיהם מאי לאו שוגג על פיהם הוא דפטור אבל נתחלף לו חלב בשומן ואכלו חייב דלמא או שוגג או על פיהם","בפלוגתא הורו ב\"ד שחלב מותר ונתחלף לו חלב בשומן ואכלו רב אמר פטור ור' יוחנן אמר חייב מיתיבי (ויקרא ד, כז) מעם הארץ בעשותה פרט למומר","רבי שמעון בן יוסי אומר משום ר\"ש אינו צריך הרי הוא אומר (ויקרא ד, כב) אשר לא תעשינה בשגגה ואשם או הודע השב מידיעתו מביא קרבן על שגגתו לא שב מידיעתו אינו מביא קרבן על שגגתו","ואם איתא הא לא שב מידיעתו הוא","אמר ר\"פ קסבר ר' יוחנן כיון דכי מתידע להו לבי דינא הדרי בהו והוא נמי הדר ביה שב מידיעתו קרינן ביה וחייב","אמר רבא מודה רב שאינו משלים לרוב צבור מ\"ט אמר קרא בשגגה עד שיהו כולן בשגגה אחת:","בין שעשו ועשה עמהן כו': למה ליה למיתנא כל הני בשלמא רישא לא זו אף זו קתני אלא סיפא דלחיובא איפכא מיבעי ליה"],[[0,"מתני' הורו בית דין כו'","כגון שהורו שחלב או דם מותר:"],[0,"והלך היחיד ועשה שוגג על פיהם","מפרש בגמרא:"],[0,"בין שעשו","ב\"ד ועשה היחיד עמהם כגון שאכל דם או חלב עמהן:"],[0,"בין שעשו ועשה אחריהן","בזה אחר זה:"],[0,"בין שלא עשו","ב\"ד:"],[0,"ועשה","היחיד על פיהן:"],[0,"פטור","מלהביא כשבה ושעירה הואיל ותלה בב\"ד ועשה על פיהם:"],[1,"הורו ב\"ד וידע אחד מהם","מב\"ד שטעו:"],[1,"או תלמיד ראוי להוראה והלך","אותו אחד או אותו תלמיד ועשה על פיהם שטעה במצוה לשמוע דברי חכמים כדמפרש בגמרא:"],[1,"הרי זה חייב","מפני שלא תלה ממש בב\"ד שהרי יודע שטעו ואמרינן בגמ' העושה מפי עצמו חייב בהוראת ב\"ד פטור:"],[2,"גמ' לעולם אין ב\"ד חייבין","כי עשו הקהל או רובו על פיהם כלומר בין למ\"ד ב\"ד מביאין פר בין למ\"ד צבור מביאין פר ולא ב\"ד לעולם לא הוי גמר הוראה דלחייב קרבן ולגבי יחיד דלהוי תולה בב\"ד:"],[2,"עד שאמרו","ב\"ד לצבור מותרין אתם:"],[2,"רב דימי אמר","לעולם לא נגמרה הוראה לחייבן קרבן עד שיאמרו מותרין אתם לעשות:"],[3,"אף אנן נמי תנינא","בפרק אלו הן הנחנקין:"],[3,"חזר","זקן ממרא לעירו וכו' הורה לעשות דמשמע דקאמר מותרין אתם לעשות דנגמרה הוראתו חייב:"],[4,"הורו לה ב\"ד להנשא","על פי עד אחד דאי בשני עדים לא צריך ב\"ד:"],[4,"והלכה וקלקלה","בזנות ואחר כך בא בעלה:"],[4,"חייבת בקרבן","לפי שלא היתה תולה בב\"ד מדקתני הורו לה ב\"ד להנשא ולא קתני התירוה ב\"ד ש\"מ דלא נגמרה הוראת' עד שיאמרו מותרין אתם לעשות:"],[5,"הורו ב\"ד לעבור","דמשמע הורו ב\"ד לעשות דאינה גמורה הוראתם עד שיאמרו מותרין אתם לעשות:"],[6,"והא לא תנן הכי","כולהו מקשו לרב דימי:"],[9,"אמר רבא","תרתי קתני דמשמע הכי והלך היחיד ועשה או שוגג או על פיהם שוגג כגון שהורו בית דין שחלב מותר ונתחלף לו חלב בשומן ואכלו דפטור אע\"ג דלא הוי על פיהם ממש ושלא במתכוין קאכיל ליה אפילו הכי הואיל ואילו מתידע ליה דחלב הוא לא הוה הדר ביה שהרי הורו ב\"ד שחלב מותר הלכך תולה בב\"ד קרינן ביה ופטור:"],[9,"על פיהם ממש","כגון שהורו ב\"ד שחלב מותר והלך ועשה על פיהם לאשמועי' דשוגג על פיהם פטור:"],[10,"ואית דאמרי","חדא קתני להכי איצטריך למיתני שוגג על פיהם דמשמע דבשוגג ממש על פיהם הוא דפטור דהיינו על פיהן ממש דידע דחלב הוא ופטור משום דתלה בב\"ד ממש:"],[10,"אבל שוגג שלא על פיהן","כגון שהורו ב\"ד שחלב מותר ונתחלף לו חלב בשומן ואכלו חייב שלא תלה עצמו בב\"ד:"],[14,"רב אמר פטור","דתולה בב\"ד הוי ויחיד שעשה בהוראת ב\"ד פטור:"],[14,"ור' יוחנן אמר חייב","הואיל ולא הוי על פיהם ממש כתולה בעצמו הוא וחייב:"],[14,"מעם הארץ בעשותה","ולא כל עם הארץ:"],[14,"פרט למומר","דאינו מביא קרבן על שגגתו דאין מקבלין מידו:"],[15,"ר\"ש בן יוסי אומר אינו צריך הרי הוא אומר אשר לא תעשינה וכו'","ומומר לא שב מידיעתו הוא לפיכך אינו מביא קרבן על שגגתו ואמר לקמן בפ\"ב מומר שאכל חלב והביא קרבן על הדם איכא בינייהו והכא נמי כי הורו ב\"ד שחלב מותר ונתחלף לו חלב בשומן לא שב מידיעתו הוא ולפיכך אינו חייב דהא הורו ב\"ד שחלב מותר וקשיא לר' יוחנן דאמר חייב דתולה בעצמו הוא:"],[17,"אמר רב פפא קסבר ר' יוחנן כיון דאילו הוה ידיע לב\"ד דטעו הוו הדרי בהו והוא נמי הוי הדר ביה הלכך שב מידיעתו קרינן ביה","וחייב קרבן שהרי לא תלה כ\"כ בב\"ד שלא עשה על פיהם ממש ואמטול הכי קאמר רבי יוחנן דחייב קרבן אבל היכא דעשה על פיהם ממש אע\"ג דאילו הוי ידיע לב\"ד הוו הדרי בהו והוא נמי הוה הדר ביה והוי שב מידיעתו אפ\"ה פטור מפני שתלה ממש בדעת ב\"ד:"],[18,"אמר רבא","אע\"ג דאמר רב כי נתחלף לו חלב בשומן דהוי יחיד שעשה בהוראת ב\"ד ופטור מודה רב שאין אותו יחיד משלים לרוב צבור כגון שאמרו ב\"ד שחלב מותר והלכו חצי צבור ועשו על פיהם ואכלו חלב ממש והלך זה ואכל ונתחלף לו חלב בשומן:"],[18,"שאינו משלים לרוב צבור","ואין מביאין פר דבעינן שיהיו כולן ממש שוגגין בשגגה אחת ע\"פ ב\"ד:"],[19,"למה לי למתני כולהו","במתני' ועשה עמהם ועשה אחריהם שלא עשו ועשה:"],[19,"בשלמא רישא לא זו אף זו קתני","דהכי משמע לא מיבעיא זו דעשה עמהם דהוי ודאי תולה בב\"ד דפטור אלא אף זו נמי דעשה אחריהם הוי תולה בב\"ד ופטור ולא זו בלבד דעשה אחריהם דפטור אלא אף זו דלא עשו ב\"ד ועשה אפי' הכי תולה בב\"ד הוי ופטור:"],[19,"אלא סיפא איפכא מיבעיא ליה למיתנא","דהכי איבעיא ליה למיתנא הורו ב\"ד וידע א' מהן שטעו או תלמיד וראוי להוראה והלך ועשה על פיהם בין שלא עשו ועשה ובין שעשה אחריהם ובין שעשה עמהם דלא תלה בב\"ד דהוי משמע לא זו בלבד דלא עשו ועשה דלא הוי תולה בב\"ד דחייב אלא אף זו דעשה אחריהן לא תלה בב\"ד וחייב ולא זו בלבד דעשה אחריהן חייב אלא אף זו דעשה עמהן דס\"ד אמינא הואיל ועשה עמהם תולה בבית דין קרינא ביה ולהוי פטור אפילו הכי אמרי' הואיל וידע שטעו לא תלה בבית דין וחייב:"]],[[0,"","הורו ב\"ד. הם סנהדרי גדולה כדדרשינן בת\"כ עדת ישראל עדה המיוחדת בישראל זו סנהדרי גדולה:"],[0,"","בין שעשו ועשה עמהן. צ\"ע אם ב\"ד עצמן חייבין להביא כשבה או שעירה דנהי דפר אין מביאין אא\"כ רוב צבור עשו על פיהן מ\"מ קרבן יחיד לייתו או שמא פטורים לגמרי:"],[4,"","הורו לה ב\"ד להנשא. האי ב\"ד אינו סנהדרין גדולה שהרי ב\"ד יכולין להתירה לינשא. ומ\"מ הני נמי אית להו האי דינא שאם עשתה כמו שהורו היתה פטורה כיון שתולה בב\"ד:"],[6,"","אמר אביי והא אנן לא תנן הכי. הא דלא פריך ללישנא קמא לשמואל כמו דפריך הכא לרב דימי דללישנא קמא מצינן למימר דרב דימי אתא לפרושי דברי שמואל:"],[8,"","הכא מסקינן לענין קרבן [עד] שיאמרו מותרין לעשות. וה\"ה בעלמא גבי הוראה דאין לתלמיד לסמוך על דברי רבו עד דא\"ל הכי. והא דתניא פ' יש נוחלין (ב\"ב קל:) אין למידין הלכה על פי מעשה. ה\"פ התם אם יאמר לך אדם ראיתי מעשה שאירע בכה\"ג שהורו כן אין לסמוך על דבריו דשמא לא עיין היטב ושמא אותו מעשה היה קצת משונה. עד שיאמר הלכה למעשה פי' עד שיביא לו מתוך ההלכה דאיתא לאותו דבר מה שאומר כי התלמוד ודברי האמוראין עיקר כדאיתא בירושלמי ריש פיאה אין למידין לא מהלכות ולא מהגדות ולא מן התוספתא אלא מפי התלמוד:"],[10,"","ואיכא דאמרי חדא קתני. ואין להקשות דלא ליתני כי אם על פיהם וממילא משמע דוקא על פיהם. שמא ה\"א ה\"ה נתחלף לו להכי תנא שוגג למימר באיזה שוגג דוקא על פיהם:"],[18,"","עד שיהיו כולן בשגגה אחת. צ\"ע אם רוב צבור עשו בזה הענין שנתחלף להם והוי כולן בשגגה אחת אי מיחייב בית דין:"]]],[["זו ואין צריך לומר זו קתני:","וידע אחד מהן שטעו או תלמיד וראוי להוראה: תרתי למה לי אמר רבא איצטריך סלקא דעתך אמינא הני מילי גמיר וסביר אבל גמיר ולא סביר לא","אמר ליה אביי להוראה גמיר וסביר משמע אמר ליה אנא הכי קאמינא אי מההיא הוה אמינא ה\"מ גמיר וסביר אבל גמיר ולא סביר לא תנא ראוי להוראה ממשנה יתירה אפי' גמיר ולא סביר סביר ולא גמיר:","ראוי להוראה וכו': כגון מאן אמר רבא כגון שמעון בן עזאי ושמעון בן זומא א\"ל אביי כי האי גוונא מזיד הוא","ולטעמיך הא דתניא (ויקרא ד, כז) בעשותה אחת יחיד העושה מפי עצמו חייב בהוראת ב\"ד פטור כיצד הורו ב\"ד שחלב מותר ונודע לאחד מהן שטעו או תלמיד יושב לפניהן וראוי להוראה כגון שמעון בן עזאי יכול יהא פטור ת\"ל בעשותה אחת יחיד העושה על פי עצמו חייב בהוראת ב\"ד פטור","אלא היכי משכחת לה כגון דידע דאסור וקא טעי במצוה לשמוע דברי חכמי' לדידי נמי דטעו במצוה לשמוע דברי חכמי':","זה הכלל התולה בעצמו חייב: לאיתויי מאי לאיתויי מבעט בהוראה","תולה בב\"ד לאיתויי הורו ב\"ד וידעו שטעו וחזרו בהן הא בהדיא קתני לה תני והדר מפרש","אמר רב יהודה אמר שמואל זו דברי ר' יהודה אבל חכמים אומרים יחיד שעשה בהוראת ב\"ד חייב מאי ר' יהודה דתניא אם נפש אחת תחטא בשגגה בעשותה הרי אלו ג' מעוטין העושה מפי עצמו חייב בהוראת ב\"ד פטור","מאי רבנן דתניא עדיין אני אומר מיעוט קהל שחטאו חייבין שאין ב\"ד מביאין על ידיהן פר רוב קהל שחטאו יהו פטורין שהרי בית דין מביאין על ידיהם פר ת\"ל מעם הארץ אפי' רובה ואפילו כולה","במאי אילימא בשגגת מעשה [ב\"ד שלא בהוראה] בית דין מאי עבידתייהו שלא בהוראת בית דין ב\"ד מי מייתו שלא בהוראה אלא בהוראה והא כי כתיב מעם הארץ בשגגת מעשה הוא דכתיב","אלא לאו הכי קאמר מיעוט קהל שחטאו בשגגת מעשה חייבין שאין ב\"ד מביאין על ידיהן פר בהוראה הא הן חייבין","יכול רוב צבור שעשו בשגגת מעשה יהו פטורין שהרי ב\"ד מביאין עליהם פר [בהוראה] ת\"ל מעם הארץ אפילו רובו","אמר ר\"פ ממאי דלמא לא הן ולא ב\"ד","אי הכי מאי איריא דקמהדר על רובא לחיובא לאו מכלל דמיעוט בהוראה קיימא ליה דמיחייבו בהוראה ונהדר ברישא על מיעוט' דמיחייב בשגגת מעשה ולבסוף ניהדר על רובא לחיובא בשגגת מעשה","אלא לאו מדלא מהדר על מיעוט דמיחייבין בשגגת מעשה ובסוף מהדר על רובא לחיובא בשגגת מעשה ש\"מ מיעוט בהוראה חייבין הן כשבה ושעירה ושלא בהוראה בשגגת מעשה חייבין","מכדי תרוייהו סתמי תנן ממאי דקמייתא ר' יהודה ובתרייתא רבנן אימא איפכא מאן שמעת ליה דדריש מיעוטי כי האי גוונא רבי יהודה היא דתניא רבי יהודה אומר"],[[0,"הא לא קשיא דסיפא זו ואין צריך לומר זו קתני","דהכי משמע לא מיבעיא זו דעשה עמהם לא תלה בב\"ד ואין צריך לומר זו דעשה אחריהם דודאי לא תלה בב\"ד וחייב קרבן וכל שכן אין צריך לומר היכא דלא עשו ועשה דחייב:"],[1,"גמיר","למד הדבר:"],[1,"וסביר","מבין דבר מתוך דבר:"],[2,"תנא משנה יתירה","להכי איצטריך משנה יתירה שלא לצורך לאשמועי' אפילו גמיר ולא סביר ולעולם תלמיד ראוי להוראה גמיר וסביר הוא:"],[3,"כגון שמעון בן עזאי ושמעון בן זומא","שהיו יושבין לפני חכמים והיו ראויין להוראה כדאמרינן בפרק קמא דסנהדרין (ד' יז:) דנין לפני חכמים שמעון בן עזאי ושמעון בן זומא:"],[3,"אמר ליה אביי","שמעון בן עזאי ושמעון בן זומא כי האי גוונא דידעי שטעו ואפ\"ה עשו אמאי חייבין קרבן והא מזידין נינהו ומזיד לאו בר קרבן הוא:"],[5,"וקא טעה במצוה לשמוע דברי חכמים","אפי' למיעבד איסורא:"],[5,"לדידי נמי","דאמרי כגון שמעון בן עזאי ושמעון בן זומא כגון דקא טעו במצוה לשמוע דברי חכמים:"],[6,"לאיתויי מבעט בהוראה","שאם היה רגיל להיות מבעט בהוראה ואחר כך הורו שחלב מותר והלך זה המבעט ועשה על פיהם ואכל חלב דחייב דהואיל והוא רגיל להיות מבעט השתא נמי מבעט וכשהוא אוכל חלב מפי עצמו הוא עושה ואינו תולה בב\"ד הלכך חייב קרבן:"],[7,"תולה בב\"ד פטור לאיתויי הורו ב\"ד וטעו וידעו שטעו וחזרו בהן","בין שהביאו כפרתן [ובין שלא הביאו] והלך היחיד ועשה על פיהם פטור דתולה בב\"ד הוא וברשות ב\"ד הוא עושה:"],[7,"הא בהדיא קתני לה","במתני' (לקמן הוריות דף ג:) דר' שמעון פוטר:"],[7,"הא לא קשיא","דתני כללא זה הכלל והדר מפרש במתניתין:"],[8,"אם נפש אחת תחטא בשגגה בעשותה","דמשמע נפש תחטא אחת תחטא בעשות' תחטא הרי אלו שלשה מיעוטי דמשמע בעשותה מפי עצמו חייב למעוטי תולה בבית דין דפטור והני שלשה מיעוטי מפרש במסכת שבת בפרק המצניע (שבת דף צג.) לר' יהודה חד למעוטי זה עוקר וזה מניח וחד למעוטי זה יכול וזה יכול וחד למעוטי יחיד שעשה בהוראת בית דין דפטור:"],[9,"מביאין על ידיהן","מביאין עליהן:"],[10,"במאי","חטאו:"],[10,"אילימא בשגגת מעשה שלא בהוראת בית דין","דלא הורו בית דין כלל וכגון שנתחלף חלב בשומן שלא בהוראתם דהכי הוי משמע מיעוט קהל שחטאו בשגגת מעשה גרידתא שלא בהוראה חייבין אבל רוב קהל שחטאו בשגגת מעשה שלא בהוראה יכול יהו פטורין שהרי ב\"ד מביאין פר עליהם ת\"ל מעם הארץ דמשמע דאפילו רובן חייבין בקרבן בשגגת מעשה דמייתו כל חד וחד כשבה או שעירה:"],[10,"","ומי מצית למימר הכי שהרי ב\"ד מביאין עליהם פר כי חטאו רוב קהל בשגגת מעשה שלא בהוראה וכי ב\"ד מייתו קרבן שלא בהוראה והא לא הורו כלל:"],[10,"אלא בהוראה","דהכי הוי משמע מיעוט קהל שחטאו בהוראה כגון שהורו ב\"ד ועשו על פיהם חייבין כשבה או שעירה שהרי אין ב\"ד מביאין פר עליהם רוב צבור שעשו בהוראה יכול יהו פטורין ת\"ל מעם הארץ דאפילו רובן חייבין:"],[10,"ומי מצית אמרת הכי","שצבור מביאין קרבן והא כי כתיב מעם הארץ בשגגת מעשה גרידתא הוא דכתיב ומהכא לא נפקא דליחייבו רוב קהל בהוראה כלל:"],[11,"אלא לאו הכי קאמר מיעוט קהל שחטאו בשגגת מעשה","גרידתא חייבין כשבה או שעירה:"],[11,"שאין ב\"ד מביאין עליהם פר בהוראה","כי הורו ב\"ד ועשו מיעוט קהל שחטאו (בשגגת מעשה) על פיהם:"],[11,"הא הן חייבין","בהוראה כשבה או שעירה דיחיד שעשה בהוראת ב\"ד [חייב] וכי היכי דחייבין בהוראה ה\"נ חייבין בשגגת מעשה גרידתא:"],[11,"אבל רוב קהל שחטאו בשגגת מעשה גרידתא יכול יהו פטורין שהרי ב\"ד מביאין עליהם פר בהוראה","והן פטורין כדאמר לקמן ר\"מ אומר שבעה שבטים שחטאו ב\"ד מביאין עליהם פר בהוראה והן פטורין וכי היכי דבהוראה פטורין לפטרו נמי בשגגת מעשה גרידתא:"],[12,"ת\"ל מעם הארץ דאפי' רובו","חייבין בשגגת מעשה גרידתא דמייתו כל חד וחד כשבה או שעירה דהאי דכתיב מעם הארץ בשגגת מעשה הוא דכתיב אלמא שמעינן מהא מתני' יחיד שעשה בהוראת ב\"ד חייב. ועדיין אני אומר רישא דמתני' הכי איתא בת\"כ בעשותה יכול יחיד שעשה חייב שנים שעשו פטורין ת\"ל מעם הארץ אפילו מרובין ועדיין אני אומר מיעוט קהל שחטאו חייבין שאין ב\"ד מביאין פר על ידיהם וכו':"],[13,"אמר רב פפא ממאי דלמא לא הן ולא ב\"ד","וה\"ק מיעוט קהל שחטאו בשגגת מעשה חייבין שאין ב\"ד מביאין פר עליהם בהוראה והן המועט נמי פטורין דיחיד שעשה בהוראת ב\"ד פטור:"],[14,"אי הכי כו'","א\"כ כדקאמרת לא הן ולא ב\"ד לא מחייבי בהוראה כלל א\"כ מיעוט קהל בשגגת מעשה גרידתא נמי ליפטרו כי היכי דמיפטרו בהוראה דאי הכי כדקאמרת לא הן ולא ב\"ד מאי איריא דקא מהדר על רובא לחיובא בשגגת מעשה דקתני אבל רוב קהל שחטאו בשגגת מעשה גרידתא יכול יהו פטורין שהרי ב\"ד מביאין עליהם פר בהוראה והן פטורין ת\"ל מעם הארץ ואפי' רובו דחייב בשגגת מעשה:"],[14,"לאו מכלל דמיעוט","קהל בהוראה פשיטא ליה לתנא דמיחייבי בהוראה כדאמר הא הן חייבין דיחיד שעשה בהוראת ב\"ד חייב וכי היכי דמיחייבי בהוראה (שם) הכי נמי מיחייבי בשגגת מעשה גרידתא ואמטול הכי קא מהדר לעיל על רובא לחיוב אלא לדידך דאמרת לא הן ולא ב\"ד דאכתי לא נפקא לך דמיחייבי מיעוטא בשגגת מעשה גרידתא אי הכי נהדר ברישא על מיעוטא דליחייבו בשגגת מעשה גרידתא ולבסוף נהדר על רובא לחיובא בשגגת מעשה גרידתא:"],[15,"אלא","מדקא מהדר על רובא ושביק מיעוטא:"],[15,"שמע מינה","דמיעוט בהוראה פשיטא ליה לתנא דחייבין כשבה או שעירה דהכי קאמר שאין בית דין מביאין עליהם פר בהוראה הא הן חייבין דיחיד שעשה בהוראת בית דין חייב וכי היכי דחייבין בהוראה (הם) הכי נמי שלא בהוראה בשגגת מעשה חייבין וכיון דקיימא ליה לתנא דמיעוט בשגגת מעשה גרידתא חייבין הלכך קא מהדר על רובא לחיובא ולעולם שמעינן מהא מתניתין דיחיד שעשה בהוראת בית דין חייב שמע מינה:"]],[[2,"","תנא. משנה יתירה דאפי' גמיר ולא סביר. תימה דלא ליתני במתני' כ\"א תלמיד שאינו ראוי להוראה וכ\"ת דא\"כ הוה משמע דלא גמיר ולא סביר דהא מרישא ידעינן דקתני ועשה יחיד על פיהם דפטור. וי\"ל דקמ\"ל דאפי' גמיר וסביר הוה שוגג דטעה במצוה לשמוע דברי חכמים וחייב דלא תימא מזיד הוה:"],[4,"","וליטעמיך הא תניא בעשותה כו'. ברייתא היא בת\"כ וגרסי' בה כגון שמעון בן עזאי ולהכי אלימא טפי לאקשויי מינה ממתני' דדוחק לומר דשמעון בן עזאי היה טועה במצוה לשמוע דברי חכמים. ולפי זה לא גרסי' ודידי נמי כו' דהא בברייתא נמי קתני הראוי להוראה וגם בספר מדויק הבא מארץ ישראל ליתא:"],[7,"","תנא כלל והדר מפרש. דהך דרישא אתי כרבי שמעון דפטר אם חזרו בהן:"],[8,"","הרי אלו מעוטין. בירושלמי פריך בכל מקום הוי מיעוט אחר מיעוט לרבות והכא למעט ומשני היינו דוקא במקום שהן זוגות כמו ספ\"ק דסנהדרין (טו.) י' כהנים כתובין בפרשה דראשון ממעט ושני לרבות ושלישי למעט ורביעי לרבות וכן לעולם ובירושלמי (פ\"ד) דמגילה פריך מעתה לא יצטרך שום כהן. ומשני דבחנם לא הזכיר כהן. ורשב\"א פי' בנדה דהיכא דמיעוט אתי למעוטי דבר אחד כמו גבי כהנים כהן ולא ישראל התם אתי לרבויי. אבל היכא דכל חדא אתא למילתא לחוד כדהכא וגבי זאת היא העולה התם אתי למעוטי:"],[9,"מעם הארץ אפילו מקצתו","לא גרסינן מעם דהא לעיל יליף מיניה פרט למומר ול\"ג נמי אפילו מקצתו דבלאו הכי יחיד ואפילו הרבה משמע דמביאין מדמהדר ארובא. וה\"ג בת\"כ עם הארץ אפילו רובו ואפילו כולו:"],[15,"","ש\"מ מיעוט בהוראה חייבין. תימה מהיכי תיתי דאפילו אי מברייתא משמע הכי מ\"מ אסמכתא מקרא לא חזינן שיהיו חייבין במקום הוראה ועוד היכא משמע ליה מהך ברייתא דאי משום דלא מהדר ברישא ממיעוטא הא לא איצטריך דהא מיחיד ילפינן כי היכי דהוא חייב הכי נמי מיעוט קהל. וכן משמע בתורת כהנים דשנים ושלשה יש להן דין יחיד ונראה כגירסת ספרים דגרסי מאי אריא מיעוט מרובא כלומר מאי שנא מיעוט מרובא ומאי פשיטא מיעוט מרובא למאי דקאמר לא הן ולא בית דין אי לדבריך אלא מדאיצטריך למילף רובא שמע מינה דמיעוט פשיטא ליה משום דמייתי נמי בהוראה כשבה או שעירה:"]]],[["(ויקרא ו, ב) זאת תורת העולה היא הרי אלו שלשה מיעוטין","ואיבעית אימא עדיין אני אומר לא מצית מוקמת לה כר' יהודה דקתני רוב קהל שחטאו ב\"ד מביאין על ידיהן פר ואי רבי יהודה האמר צבור הוא דמייתי ב\"ד לא דתנן רבי יהודה אומר שבעה שבטים שחטאו מביאין ז' פרים","ורב נחמן אמר שמואל זו דברי ר\"מ אבל חכמי' אומרי' יחיד שעשה בהוראת ב\"ד חייב מאי ר\"מ ומאי רבנן דתניא הורו ועשו רבי מאיר פוטר וחכמים מחייבין","מאן עשו אילימא ב\"ד מ\"ט דרבנן דמחייבי והתניא יכול הורו ב\"ד ועשו ב\"ד יכול יהו חייבין ת\"ל הקהל ועשו מעשה תלוי בקהל והוראה תלויה בב\"ד","אלא הורו ב\"ד ועשו רוב קהל מאי טעמא דר' מאיר דפוטר אלא לאו הורו ב\"ד ועשו מיעוט קהל ובהא קמיפלגי מר סבר יחיד שעשה בהוראת בית דין פטור ומר סבר יחיד שעשה בהוראת ב\"ד חייב","אמר רב פפא דכולי עלמא יחיד שעשה בהוראת ב\"ד פטור אלא ב\"ד משלים לרוב צבור קמיפלגי","מ\"ס ב\"ד משלים לרוב צבור ומ\"ס אין ב\"ד משלים לרוב צבור","ואיבעית אימא הורו ב\"ד ועשו רובו של קהל ומאן חכמים רבי שמעון היא דאמר צבור מייתי וב\"ד מייתי","ואיבעית אימא שבט שעשה בהוראת בית דינו ומאן חכמי' רבי יהודה היא דתניא שבט שעשה בהוראת בית דינו אותו השבט חייב","ואב\"א כגון שחטאו ששה והן רובו של קהל או שבעה אע\"פ שאינן רובו של קהל ומתניתין מני ר' שמעון בן אלעזר היא","דתניא רבי שמעון בן אלעזר אומר משמו חטאו ששה והן רובו של קהל או שבעה אע\"פ שאינן רובו של קהל חייבין","אמר רב אסי ובהוראה הלך אחר רוב יושבי ארץ ישראל שנאמר (מלכים א ח, סה) ויעש שלמה בעת ההיא את החג וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים לפני ה' אלהינו שבעת ימים ושבעת ימים ארבעה עשר יום מכדי כתיב וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים למה לי שמע מינה הני הוא דאיקרי קהל אבל הנך לא איקרי קהל","פשיטא מרובין ונתמעטו היינו פלוגתא דרבי שמעון ורבנן","מועטין ונתרבו מאי מי פליגי רבי שמעון ורבנן ר\"ש דאזיל בתר ידיעה מחייב ורבנן דאזלי בתר חטאת פטרי [או לא] מאי","ותיסברא אימור דשמעת ליה לר\"ש דאזיל אף בתר ידיעה [היכי דהוי ידיעה וחטאה בחיוב] ידיעה דלא חטאה מי שמעת ליה","דא\"כ לייתי כי השתא אלא ר\"ש חטאה וידיעה בעי","איבעיא להו הורו ב\"ד חלב מותר ועשו מיעוט הקהל וחזרו ב\"ד בהן והורו ועשו מיעוט אחר מהו כיון דשתי ידיעות נינהו לא מצטרף או דלמא כיון דאידי ואידי חלב הוא מצטרף","ואם תמצא לומר כיון דאידי ואידי חלב הוא מצטרף מיעוט בחלב שעל גבי הקבה ומיעוט בחלב שעל גבי דקין מהו הכא ודאי כיון דבתרי קראי קאתי לא מצטרף או דלמא כיון דאידי ואידי חלב הוא מצטרף","ואת\"ל שם חלב הוא ומצטרף מיעוט בחלב ומיעוט בדם מהו הכא ודאי (כיון) דתרי איסורי נינהו [וכיון דאין איסורן שוה] לא מצטרף או דלמא כיון (דאיסורן שוה) דקרבנן שוה מצטרף","ואת\"ל כיון (דאיסורן שוה) דקרבנן שוה מצטרף מיעוט בחלב ומיעוט בעבודת כוכבים מהו הכא ודאי אין איסורן שוה ואין קרבנן שוה או דלמא כיון דאידי ואידי כרת הוא מצטרף תיקו","איבעיא להו הורו ב\"ד שחלב מותר ועשו מיעוט הקהל ומת אותו ב\"ד ועמד ב\"ד אחר וחזרו והורו ועשו מיעוט אחר","אליב' דמ\"ד ב\"ד מייתי לא תיבעי לך דהא ליתנהו אלא כי תיבעי לך אליבא דמ\"ד צבור מייתי מאי צבור הא קאי"],[[0,"זאת תורת העולה היא העולה","זאת היא העולה הרי אלו שלשה מיעוטי חד פרט לנשחטה בלילה וחד פרט לנשפך דמה וחד פרט ליציאת דמה חוץ לקלעים שאם עלתה על גבי המזבח תרד דלא הויא עולה חשובה והכי נמי מפרש במסכת נדה בפרק יוצא דופן (נדה דף מ.):"],[1,"ז' שבטים","דהוו רוב שבטים מביאים שבעה פרים דקסבר ר' יהודה דשבט א' איקרי קהל והן מביאין ולא ב\"ד:"],[3,"הוראה תלויה בב\"ד","דכתיב ונעלם דבר דהיינו שהורו לעבור מעיני הקהל דהיינו ב\"ד:"],[5,"ב\"ד משלים לרוב צבור","דעשו עם מעט צבור והשלימו לרוב צבור:"],[7,"[צבור מייתי]","ור' מאיר פוטר צבור דהא קא מייתי ב\"ד כדאמרי' לקמן רבי מאיר אומר שבעה שבטים שחטאו בית דין מביאין עליהם פר והן פטורין ואי קשיא הא אמרי' בכל התורה אין מיעוט אחר מיעוט אלא לרבות והיכי אמרי' אלו ג' מיעוטין דממעטינן אותם בירושלמי מפרש ה\"מ היכא דליכא אלא ב' מעוטין אבל הכא דאיכא ג' מיעוטין בזה אחר זה בחד קרא כולהו אתו למעט וכן בל\"ב מדות מצאתי:"],[8,"אותו השבט חייב","להביא פר דקסבר שבט אחד אקרי קהל:"],[10,"רבי שמעון בן אלעזר אומר משמו","של ר' מאיר והא מתניתא מפרש לקמן:"],[11,"אמר רב אסי ובהוראה","דקיי\"ל כי הורו ב\"ד ועשו רוב קהל על פיהם שמביאים פר:"],[11,"הלך אחר רוב יושבי' בארץ ישראל","דאותם שבחוצה לארץ אינן מן המנין ולא אותן דמנחל מצרים ולחוץ דחוצה לארץ היא:"],[12,"פשיטא מרובין ונתמעטו","כגון שהורו ב\"ד ועשו רוב קהל על פיהם דנתחייבו להביא פר ולא הספיקו להביא פר עד שנתמעטו שמתו מקצתן היינו פלוגתא דר' שמעון ורבנן. דתנן (לקמן הוריות י.) חטא כהן משוח ונשיא עד שלא נתמנו דהיו חייבים להביא כשבה או שעירה ולא הספיקו להביא עד שנתמנו הרי הן כהדיוטות ונחייבם להביא כשבה או שעירה כבתחלה הכא נמי חייבין פר כבתחלה רבי שמעון אומר וכו' הכא נמי אם נודע להם עד שלא נתמעטו חייבין להביא פר אבל אם נודע להן משנתמעטו פטורין:"],[13,"מועטין ונתרבו מאי","כגון שהורו בית דין ועשו מיעוט קהל על פיהם דיחיד שעשה בהוראת בית דין פטור ומתו מקצתן של רוב קהל ונתרבו אלו ולאחר שנתרבו נודע להם שחטאו דהני מועטין ונתרבו לא דמי ממש לחטאו עד שלא נתמנו דמועטין כי חטאו בהוראה לאו בני קרבן נינהו דיחיד שעשה בהוראת בית דין פטור אבל כי חטאו כהן משיח ונשיא עד שלא נתמנו נעשו בני קרבן ומחייבי לאתויי כשבה או שעירה אבל מרובין ונתמעטו דמי ממש לחטאו עד שלא נתמנו דהא מרובין כי חטאו בני קרבן נינהו ואמטול הכי קאמר במרובין ונתמעטו דהוי פלוגתא דר\"ש ורבנן אבל במועטין ונתרבו איבעיא לן אי דמי לפלוגתא דר' שמעון ורבנן אי לא מי אמרי' ר\"ש דבתר ידיעה אזיל דאמר אם נודע להם עד שלא נתמנו חייבין כבתחלה הכא נמי מחייב דכי אתיידע להו בחיובא אתיידע להו דכי נתרבו אתיידע להו ומביאין פר ורבנן דבתר חטאה אזלי דאמרי הרי אלו כהדיוטות הואיל וחטאו כי לא נתמנו הכא נמי אזלי בתר חטאה וכי חטאו אכתי מועטין היו ופטורין דיחיד שעשה בהוראת בית דין פטור:"],[14,"ותסברא אימור דשמעת ליה לר\"ש דאזיל אף בתר ידיעה","דאמר אם נודע להם עד שלא נתמנו חייבין היכא דהוי ידיעה וחטאה בחיוב:"],[15,"כי השתא","דלהוי כי חטאו משנתמנו דלייתי פר ואמאי קתני משנתמנו פטורין אלא מדקתני פטור ש\"מ דר\"ש חטאה וידיעה בעי בחיובא ומועטין ונתרבו לדברי הכל פטורין דכי חטאו בפטור חטאו דיחיד שעשה בהוראת בית דין פטור:"],[16,"או דלמא","כיון דחלב שם אחד הוא דבין חלב המכסה את הקרב ובין חלב המכסה את הדקין שם אחד הוא שחלב סתם איקרו:"],[18,"כיון דתרי איסורי נינהו","דחלב אינו שוה בכל דחלב חיה מותר:"],[18,"או דלמא","כיון דאילו צבור אכלי האי חלב והאי דם שלא בהוראה בשגגת מעשה מייתו כל חד וחד אי בעו כשבה מייתו אי בעו שעירה מייתו דמצי אשוויי קרבנם השתא נמי כי עשו בהוראה מצטרפי:"],[19,"ומיעוט בתרא בעבודת כוכבים","קרבנם שעירה ולא כשבה:"]],[[1,"","אית ספרים דגרסי דתנן ר' יהודה אומר י\"ב שבטים שחטאו מביאין י\"ב פרים וכן נראה דהכי תנן ברישא דמתני' ובתר הכי תני ו' שבטים כו' ולא שביק רישא דמתניתין למנקט סיפא:"],[4,"","ר\"מ סבר יחיד שעשה בהוראת ב\"ד פטור. תימה מאי דוחקי' לכך דלמא ר\"מ ס\"ל דדוקא יחיד שעשה חייב אבל שנים ושלשה שעשו פטורים ולית ליה ברייתא דועדיין אני אומר כו' דבלא\"ה לית ליה דברייתא אית לה יחיד שעשה בהוראת ב\"ד חייב ור\"מ אית ליה דפטור ומיהו כיון דלא מצינו תנא דמחלק בין א' לשנים דחיק למימר הכי:"],[11,"","קהל גדול מלבוא חמת. אע\"ג דד\"ת מדברי קבלה לא ילפינן הא הוי גילוי מילתא בעלמא:"],[13,"","מועטין ונתרבו מאי. פרש\"י (בעלמא) [בעיין] דהני לאו בני קרבן כמו משיח ונשיא אבל מרובין ונתמעטו כבר הוו בני קרבן. ולא נהירא דאפי' מרובין ונתמעטו כי נתמעטו לאו בני קרבן נינהו אם לא דבתר חטאה אזלינן אבל התם תרוייהו בני קרבן נינהו אלא מש\"ה מבעיא ליה במועטין ונתרבו דאיכא למימר דאפי' ר\"ש מודה דפטור כדפי' ואזיל:"],[17,"","הורו ב\"ד שחלב המכסה את הקרב כו'. תימה דאמרי' לקמן (הוריות ד.) אין ב\"ד חייבין עד שיורו בדבר שאין הצדוקין מודין ובשלמא חלב שעל הדקין דאתי מריבוי' (חולין מט) ניחא דאין הצדוקין מודין בו אלא חלב המכסה את הקרב וכן דם מאי איכא למימר מיהו לפי התוספ' דמכילתין ניחא דתנא לקיים מצות חייבין כיצד יש חלב ודם בתורה אבל אין חייבין אלא על הקרב לשלמים. ואע\"ג דדם חיה נאסר. שמא הצדוקים אומרים דגם הוא קרב:"],[18,"","וחזרו והורו שדם מותר. הא דקתני כה\"ג דמשמע דוקא משום שידעו בינתים שטעו בחלב דהא אפי' לא ידעו נמי מצי למבעי כדקאמר משום דשני מינים הם דם שוה בכל ולא חלב אלא נקטי' אגב אחריני. והא דלא פשיט מההוא דלעיל עד שיהיו כולן בשגגה אחת. דהכא כיון דתליא בב\"ד הוי שגגה אחת:"],[19,"","והורו שעבודת כוכבים מותרת. צ\"ע מה יביאו כיון שאין קרבנותיהן שוין אם יביאו קרבן עבודת כוכבים וגם דחלב או לא וגם צ\"ע אי דוקא מיבעיא דמעיקרא הוי מיעוט וכן בסוף אבל אי הוי רובו בסוף לא איצטרכי למיעוטא שיתכפר בפר לההוא מיעוטא. א\"ד ל\"ש אבל הא ודאי אי הוי מתחלה רובא ולבסוף מיעוטא אין מיעוט מצטרף לרובא כיון שכבר נתחייבו רובא בקרבן:"],[21,"","אלא כי תיבעי לך כו'. צ\"ע אי הוי מצי למבעיא נמי למ\"ד ב\"ד מייתי אם מתו מיעוט צבור הראשונים ולא נודע כי אם אל אלו החיים מי אמרי' ב\"ד [חייבי'] דמ\"מ הם הורו שלא כדת או לא והא דנקיט מת ב\"ד ולא נקיט הורו ב\"ד אחר דלא אפשר כי אם בסנהדרי גדולה:"]]],[["או דלמא [ידיעה] דההוא ב\"ד דהורו בעינן תיקו","אמר רבי יונתן מאה שישבו להורות אין חייבין עד שיורו כולן שנאמר (ויקרא ד, יג) ואם כל עדת ישראל ישגו עד שישגו כולן [עד שתפשוט הוראה בכל עדת ישראל] אמר רב הונא בריה דרב הושעיא הכי נמי מסתברא דבכל התורה כולה קיי\"ל רובו ככולו והכא כתי' כל העדה הואיל וכך אפילו הן מאה","[תנן] הורו ב\"ד וידע אחד מהן שטעו או תלמיד וראוי להוראה והלך ועשה על פיהם בין שעשו ועשה עמהן ובין שעשו ועשה אחריהן ובין שלא עשו ועשה ה\"ז חייב מפני שלא תלה בב\"ד","האי הוא דחייב הא אחר פטור ואמאי הא לא נגמרה הוראה הכא במאי עסקינן כגון שהרכין ההוא אחד מהן בראשו","ת\"ש הורו ב\"ד וידע אחד מהן שטעו ואמר להן טועין אתם הרי אלו פטורים טעמא דאמר להן טועין אתם דפטורים הא שתיק מישתק חייבין וגמר לה הוראה ואמאי והא לא הורו כולן אמרי ה\"נ כגון שהרכין בראשו","מתיב רב משרשיא סמכו רבותינו על דברי רשב\"ג ועל דברי ר\"א בר' צדוק שהיו אומרים אין גוזרין גזירה על הצבור אלא א\"כ רוב הצבור יכולין לעמוד בה","ואמר רב אדא בר אבא מאי קרא (מלאכי ג, ט) במארה אתם נארים ואותי אתם קובעים הגוי כולו והא הכא דכתי' הגוי כולו ורובא ככולא דמי תיובתא דר' (יוחנן) [יונתן] תיובתא","ואלא מאי כל עדת דקאמר רחמנא ה\"ק אי איכא כולם הויא הוראה ואי לא לא הויא הוראה","אמר רבי יהושע י' שיושבין בדין קולר תלוי בצואר כולן פשיטא הא קמ\"ל דאפילו תלמיד בפני רבו","רב הונא כי הוה נפיק לבי דינא מייתי עשרה תנאי דבי רב לקמיה כי היכי דנימטיין שיבא מכשורא רב אשי כי הוו מייתי טרפתא לקמיה מייתי עשרה טבחי ממתא מחסיא ומותיב קמיה אמר כי היכא דנימטיין שיבא מכשורא:","\u0001מתני׳\u0002 הורו ב\"ד וידעו שטעו וחזרו בהן בין שהביאו כפרתן ובין שלא הביאו כפרתן והלך ועשה על פיהן ר' שמעון פוטר ור' אלעזר אומר ספק איזהו ספק ישב לו בתוך ביתו חייב הלך לו למדינת הים פטור","אמר רבי עקיבא מודה אני בזה שהוא קרוב לפטור מן החובה אמר לו בן עזאי מאי שנא זה מן היושב בביתו שהיושב בביתו אפשר היה לו שישמע וזה לא היה לו אפשר שישמע","הורו ב\"ד לעקור את כל הגוף אמרו אין נדה בתורה אין שבת בתורה אין עבודת כוכבים בתורה הרי אלו פטורין הורו לבטל מקצת ולקיים מקצת הרי אלו חייבין","כיצד אמרו יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור","יש שבת בתורה אבל המוציא מרה\"י לרה\"ר פטור","יש עבודת כוכבי' בתור' אבל המשתחוה פטור הרי אלו חייבין שנא' (ויקרא ד, יג) ונעלם דבר דבר ולא כל הגוף:","\u0001גמ׳\u0002 אמר רב יהודה אמר רב מ\"ט דר\"ש הואיל וברשות ב\"ד הוא עושה איכא דאמרי אמר רב יהודה אמר רב אומר היה ר\"ש כל הוראה שיצאה ברוב צבור יחיד העושה אותה פטור לפי שלא ניתנה הוראה אלא להבחין בין שוגג למזיד","מיתיבי פר העלם דבר של צבור ושעירי עבודת כוכבים בתחלה גובין עליהן דברי ר\"ש ר' יהודה אומר מתרומת הלשכה הן באין אמאי כיון דגבי להו הוי ליה הודע","איבעית אימא כגון שגבו סתם","ואב\"א כגון דלא הוה ליה במתא","ואיבעית אימא רב כאידך תנא סבר דתניא איפכא בתחילה גובין להן דברי רבי יהודה ר\"ש אומר מתרומת הלשכה הן באין","תני ר\"מ מחייב ור\"ש פוטר ר\"א אומר ספק משום סומכוס אמרו תלוי אמר ר' יוחנן אשם תלוי איכא בינייהו","א\"ר זירא משל דר\"א למה הדבר דומה לאדם שאכל ספק חלב ספק שומן ונודע לו שמביא אשם"],[[0,"או לא בעינן ההוא בית דין דהורו להם מעיקרא דתהוי להו ידיעה","כלומר לא בעינן דתהוי להו ידיעה לב\"ד קמא ומצטרפי:"],[1,"עד שתפשוט הוראה בכל עדת ישראל","דהיינו אותן שישבו להורות:"],[3,"כגון שהרכין ההוא אחד מהם","או תלמיד בראשו דנראה כהודה לדבריהם ונגמרה הוראה:"],[6,"במארה אתם נארים וגו'","כגון שהגוי כולו דיכולין לקבלה: הכי משמע אי איכא גוי כולו וקא עבר עליה האי גברא אותי אתם קובעים והכי כתוב בספרים במס' עבודת כוכבים בפ' אין מעמידין:"],[7,"אי איתא לכולהו","סנהדרין של שבעים וא':"],[7,"הויא הוראה","אע\"פ שלא הורו כל אותן שישבו להורות:"],[9,"שיבא","אופתא:"],[10,"מתני' הורו ב\"ד","ועשו רוב צבור על פיהם:"],[10,"וידעו שטעו וחזרו","מהוראתן:"],[10,"בין שהביאו כפרתן ובין שלא הביאו כפרתן","ולאחר שידעו שטעו הלך היחיד ועשה על פיהם דזה אין מצטרף עם רוב הצבור לפי שלאחר שנודע להם עשה זה:"],[10,"ר' שמעון פוטר","לפי שברשות ב\"ד הוא עושה שזה עדיין לא היה יודע שידעו שטעו וחזרו בהן והוי תולה בב\"ד הלכך פטור:"],[10,"ר' אלעזר אומר ספק","כלומר ספק אי כתולה בב\"ד אי כתולה בעצמו דמי ומביאין אשם תלוי:"],[10,"ואיזה הוא הספק","כלומר אמאי הוא חייב אשם תלוי:"],[10,"ישב לו בביתו חייב","אשם תלוי:"],[11,"שהוא קרוב לפטור","דהוי ודאי תולה בב\"ד שלא ידע חזרתן הואיל והלך לו למדינת הים:"],[11,"אמר לו בן עזאי מאי שנא זה","שהלך למדינת הים מן היושב בביתו:"],[11,"אמר לו ר' עקיבא","לפי שהיושב בביתו אפשר שישמע שב\"ד חזרו בהן והוי קרוב לתולה בעצמו ולפיכך חייב להביא אשם תלוי וזה שהלך למדינת הים לא היה יכול לשמוע והוי תולה בבית דין ממש הלכך פטור:"],[16,"גמ' כל הוראה שיצאה ברוב צבור","אע\"פ שב\"ד חזרו בהן יחיד העושה אותה פטור:"],[16,"","לפי שלא ניתנה הוראה אלא להבחין בין שוגג למזיד. להודיע שהעושה על פיהם שוגג הוא ולא מזיד הוא וזה על פי הוראה הוא עושה לפיכך שוגג הוא ויחיד שעשה בהוראת בית דין פטור [פ\"א] לא ניתנה הוראה לפטור יחיד התולה בה אלא להכיר לבין עושה בשגגת עצמו לעושה מזיד וברשות בית דין וזה הרי אומר לנו שלא ידע שחזרו ומזיד עשה על פיהם ולא על שגגת עצמו ויחיד שעשה בהוראת ב\"ד פטור:"],[17,"מיתיבי פר העלם דבר של צבור","כגון שהורו ב\"ד בעבודת כוכבים ועשו צבור על פיהם וידעו שטעו וחזרו בהם וצריכין מעות כדי ליקח פר ושעירי עבודת כוכבים של צבור:"],[17,"בתחלה גובין להם","שגזברין גובין מכל אחד מישראל מעות לקנות מהם פר ושעירי עבודת כוכבים לצורך קרבן דברי ר\"ש:"],[17,"ואמאי","קאמר רבי שמעון דפטור דברשות ב\"ד הוא עושה הא כיון דאגבי להו מעות לצורך פר העלם דבר של צבור הוה מתיידע ליה שהבית דין טעו וחזרו מהוראתן ואמאי הוי תולה בב\"ד:"],[18,"איבעית אימא שגבו ממנו סתם","שלא הודיעוהו לצורך מה הן גובין:"],[19,"ואיבעית אימא דלא הוי במתא","כי גבו להו ולאחר גבייה הוא דעשה על פיהם:"],[20,"ר\"ש אומר מתרומת הלשכה הם באים","דלא הוי מפרסמא הלכך כי עשה על פיהם הוי תולה בבית דין הלכך פטר ר' שמעון ותנא דמתניתין הכי סבירא ליה אליבא דרבי שמעון דמתרומת הלשכה הן באין:"],[21,"תניא ר\"מ מחייב","דתולה בעצמו הוי:"],[21,"ורבי שמעון פוטר","דתולה בב\"ד הוי:"],[21,"רבי אלעזר אומר ספק","מביא אשם תלוי:"],[21,"איכא בינייהו","בין ר' אלעזר לסומכוס לסומכוס אינו מביא אשם תלוי דהכי קאמר סומכוס מעשה שלו תלוי הוא וליכא למימר שמא תולה בעצמו הוה דלא הוי בר חיוב מעליא דהיכא דהוי לפניו חתיכה אחת ספק של חלב ספק של שומן ואכלו בדין הוא דמביא אשם תלוי משום דאיכא למימר שמא חלב ממש אכל דהוי בר חיוב מעליא אבל הכא ליכא למימר שמא תולה בעצמו ממש הוא שהרי על פי הוראה הוא עושה הלכך מעשה שלו תלוי הוא דצד חיוב שלו תלוי הוא דלא הוי צד חיוב מעליא הלכך אינו מביא אשם תלוי:"],[22,"לאדם שאכל ספק חלב ספק שומן","והרי סבור ששומן הוא ונודע לו שספק הוא שמביא אשם תלוי משום דשמא חלב ממש אכל הכי נמי איכא למימר שמא תולה בעצמו ממש הוא:"]],[[16,"","כל הוראה שיצתה ברוב צבור. למעוטי דאם חטאו חצי צבור ועשה גם הוא חייבין:"],[17,"","שעירי עבודת כוכבים. משום הכי נקיט לשון רבים דאיכא טובא שעירים שעירי ראש חודש ושעירי רגלים שהן מרובים. ואיידי דקאמר התם שעירים נקיט נמי הכא אע\"ג דאינו [אלא] אחד כמו פר העלם:"],[22,"","משל דרבי אליעזר כו'. תימה דהתם בספק אכל ספק לו ולכולי עלמא אבל הכא לו אין ספק. וכן בסומכוס. מיהו יש לומר דבהא תרוייהו שוין דספק הוי:"]]],[["ולא מבעיא למ\"ד צבור מייתי דמפרסמא מלתא אלא אפילו למ\"ד ב\"ד מביאין דלא מפרסמא מלתא אי הוה שאיל הוו אמרין ליה","אמר ר' יוסי בר אבין ואיתימא רבי יוסי בר זבידא משל דסומכוס למה הדבר דומה לאדם שהביא כפרתו בין השמשות ספק מבעו\"י נתכפר לו ספק משחשכה נתכפר לו שאין מביא אשם תלוי","ולא מבעיא למ\"ד ב\"ד מביאין דלא אפרסמא מלתא אלא אפילו למ\"ד צבור מביאין דמפרסמא מלתא והוו אמרינן ליה דהכא בספק מבעוד יום ספק משחשכה אי שאיל לא אשכח אינש דמשייליה:","אמר לו בן עזאי מאי שנא מן היושב כו': שפיר קאמר ליה ר\"ע לבן עזאי","אמר רבא החזיק בדרך איכא בינייהו לבן עזאי חייב דהא בביתיה איתיה לר\"ע פטור דהא החזיק בדרך:","הורו לו ב\"ד לעקור את כל הגוף: ת\"ר (ויקרא ד, יג) ונעלם דבר ולא שיעקר המצוה כולה כיצד אמרו אין נדה בתורה אין שבת בתורה אין עבודת כוכבים בתורה יכול יהו חייבין ת\"ל ונעלם דבר ולא שתתעלם מצוה כולה הרי אלו פטורין","אבל אמרו יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור יש שבת בתורה אבל המוציא מרשות היחיד לרשות הרבים פטור יש עבודת כוכבים בתורה אבל המשתחוה פטור יכול יהו פטורין תלמוד לומר ונעלם דבר ולא כל הגוף","אמר מר יכול יהו פטורין ואי בקיום מקצת וביטול מקצת פטורין ובעקירת כל הגוף פטורין במאי חייבין תנא הכי קא קשיא ליה אימא דבר כולה מילתא משמע ת\"ל ונעלם דבר","מאי משמע אמר עולא קרי ביה ונעלם מדבר","חזקיה אמר אמר קרא (ויקרא ד, יג) ועשו אחת מכל מצות מכל מצות ולא כל מצות מצות תרתי משמע אמר ר\"נ בר יצחק מצות כתי'","רב אשי אמר יליף דבר דבר מזקן ממרא דכתיב ביה בזקן ממרא (דברים יז, ח) כי יפלא ממך דבר לא תסור מן הדבר אשר יגידו לך ימין ושמאל מה ממרא מן הדבר ולא כל דבר אף בהוראה דבר ולא כל הגוף","אמר רב יהודה אמר שמואל אין ב\"ד חייבין עד שיורו בדבר שאין הצדוקין מודין בו אבל בדבר שהצדוקין מודין בו פטורין מאי טעמא זיל קרי בי רב הוא","תנן יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור ואמאי שומרת יום כנגד יום הא כתי' וספרה לה מלמד שסופרת אחד לאחד","דאמרי העראה שריא גמר ביאה הוא דאסירא הא נמי כתיב את מקורה הערה","דאמרי כדרכה אסירא שלא כדרכה שריא הא כתיב משכבי אשה","דאמרי כדרכה אסור אפי' העראה בשלא כדרכה גמר ביאה הוא דאסור אבל העראה שריא אי הכי אפי' נדה נמי","אלא לעולם כדרכה ודאמרי העראה באשה דוה הוא דכתיבא ואיבעית אימא דאמרי זבה לא הויא אלא ביממי דכתיב כל ימי זובה","תנן יש שבת בתורה אבל המוציא מרשות לרשות פטור ואמאי הוצאה הא כתיבא לא תוציאו משא מבתיכם","[דאמרי הוצאה הוא דאסור הכנסה מותר ואיבעית אימא] דאמרי הוצאה והכנסה הוא דאסירא מושיט וזורק שרי","תנן יש עבודת כוכבים בתורה אבל המשתחוה פטור ואמאי המשתחוה הא כתיבא דכתיב לא תשתחוה לאל אחר","דאמרי כי אסירא השתחויה כדרכה אבל שלא כדרכה שריא ואיב\"א דאמרי השתחויה גופה כדרכה הוא דאסיר דאית בה פשוט ידים ורגלים הא השתחויה דלית בה פשוט ידים ורגלים שריא"],[[0,"ולא מיבעיא למ\"ד צבור מביאין","דכי הביאו כפרתן דמי דהא מפרסמא מלתא ולא הוי האי יחיד תולה בב\"ד אלא אפילו למ\"ד דכי הורו ב\"ד ועשו קהל על פיהם דב\"ד מביאין עליהם פר והם פטורין דאיכא למימר לא מפרסמא מילתא כל כך והאי יחיד תולה בבית דין הוא אפ\"ה לאו תולה בב\"ד הוא שהרי היה בידו לישאל מפני מה ב\"ד מביאין פר ואי שאיל אומרים לו דטעו וחזרו הלכך תולה בעצמו קרינא ביה ואית ביה צד חיוב מעליא הלכך מביא אשם תלוי:"],[1,"ספק מבעוד יום נתכפר לו","והיא כפרה מעליא:"],[1,"ספק משחשכה נתכפר לו","ולא הוי כפרה מעליא דביום צוותו כתיב דקיימא לן דפטור דאין צריך להביא קרבן אחר ואע\"פ שהוא קרב אחר תמיד של בין הערבים אין בו שום פסול דהכי אמר בפ' תמיד נשחט (פסחים ד' נט.) דאתי עשה דפסח ועשה דאכילת קדשים ודחי עשה דהשלמה ואיכא נמי שינויי אחריני טובא והא הכא (מפני) דבין השמשות לית ביה צד חיוב מעליא דליכא למימר שמא משחשכה נתכפר לו שהרי בין השמשות כהרף עין ואין אדם בעולם יכול לעמוד עליו אם מן היום או מן הלילה ופטור ה\"נ ליכא למימר שמא ממש תולה בעצמו שהרי כבר הורו ב\"ד:"],[2,"ולא מיבעיא למ\"ד ב\"ד מביאין","ולא צבור דלא מפרסמא מלתא היא והאי יחיד תולה בב\"ד הוא ופטור:"],[2,"אלא אפילו למ\"ד צבור מביאין","ואיכא למימר מפרסמא מלתא היא והאי יחיד לאו תולה בב\"ד ותולה בעצמו הוא אפ\"ה אמר תולה בב\"ד הוא דכי עשה על פיהן עשה:"],[2,"לא משכח איניש דלשייליה","ולא סליק אדעתיה למישאל למה הביאו צבור פר הלכך ליכא צד חיוב מעליא דהא צד פטור שייך ביה טפי דתולה בב\"ד הוא הלכך אינו מביא אשם תלוי:"],[4,"החזיק בדרך","לילך למדינת הים ועדיין ישנו בעיר:"],[4,"איכא בינייהו","לר\"ע פטור דהא החזיק בדרך דכיון דטרוד הוא לא היה אפשר לו שישמע דחזרו בהן הלכך תולה בב\"ד הוא ופטור לגמרי:"],[7,"תנא הכי קשיא ליה דבר כולה מלתא משמע","דהורו לעקור כל הגוף דהא לא כתיב מדבר ואימא איפכא דהורו לבטל במקצת ולקיים במקצת יכול יהו פטורין וכי הורו לעקור כל הגוף יהו חייבין:"],[7,"ת\"ל ונעלם דבר","בא ללמד דבטול מקצת וקיום מקצת חייב:"],[8,"מאי משמע","כלומר היכי משמע האי ונעלם דהוי קיום מקצת ובטול מקצת:"],[8,"אמר עולא קרי ביה ונעלם מדבר","דהאי מ\"ם דנעלם שדיא אדבר דמ\"ם נדרשת לפניו ולאחריו וקרי ביה ונעלם מדבר דמשמע מדבר ולא כל דבר:"],[9,"חזקיה אמר","מסיפא דקרא נפקא מכל מצות דמשמע מכל מצות של שבת דהוי בטול מקצת וקיום מקצת או מכל מצות של עבודת כוכבים דהוי ביטול מקצת וקיום מקצת או מכל מצות נדה דהוי ביטול מקצת וקיום מקצת ולא כל מצות השבת דהוי עוקר כל הגוף ולא כל מצות דנדה ודעבודת כוכבים דעוקר כל הגוף:"],[9,"מצות תרתי משמע","כלומר מצות טובא משמע כגון נדה שבת ועבודת כוכבים דהכי משמע ועשה אחת מכל מצות ה' דעבד חד מהני או שבת או עבודת כוכבים או נדה ולעולם בעוקר כל הגוף קא מיירי:"],[9,"אמר ר\"נ בר יצחק מצות כתיב","בחד וי\"ו דחדא מצוה משמע דהכי משמע ועשה אחת מכל מצות דשבת או אחת מכל מצות דעבודת כוכבים או אחת מכל מצות דנדה דהוי מקיים מקצת דשבת ומבטל מקצת והוא הדין לעבודת כוכבים והוא הדין לנדה והוא הדין לשאר מצות דקיום מקצת ובטול מקצת חייב ועוקר כל הגוף פטור:"],[10,"מה זקן ממרא מן הדבר ולא כל דבר","דהא כתי' מן הדבר ותנן באלו הן הנחנקין (סנהדרין דף פח:) האומר אין תפלין לעבור על דברי תורה פטור חמש טוטפות להוסיף על דברי סופרים חייב דהיינו מן הדבר ולא כל דבר:"],[11,"אין ב\"ד חייבין","דלא הוי הוראה מעליא עד שיורו להתיר בדבר שאין הצדוקין מודין שיהא אסור שהורו להיתר בדבר איסור שאין כתוב בתורה בהדיא:"],[11,"זיל קרי בי רב הוא","דכיון דאפשר לו ללמוד ולידע לא הוי שוגג מעליא וקרוב למזיד הוי:"],[12,"אחד לאחד","היינו יום כנגד יום:"],[14,"דאמרי כדרכה אסירא","גמר ביאה ושלא כדרכה שריא:"],[14,"והא","שלא כדרכה נמי כתיב משכבי אשה שני משכבות אחד כדרכה ואחד שלא כדרכה:"],[15,"דאמרי כדרכה אסירא אפי' העראה","דהאי דכתיב את מקורה הערה בכדרכה:"],[15,"אי הכי","מאי איריא דקתני שהורו בשומרת יום כנגד יום אפילו נדה נמי כי האי גוונא קיום מקצת וביטול מקצת הוא והוי בדבר שאין הצדוקין מודין בו:"],[16,"אלא לעולם בכדרכה","דאמרי בשומרת יום העראה שריא אפילו בכדרכה וגמר ביאה הוא דאסיר ודקאמרת הא העראה כתיב דאמרי העראה באשה נדה הוא דכתי' ולא בשומרת יום הלכך לא מתוקמא בנדה אלא בשומרת יום והוי בדבר שאין הצדוקין מודין בה:"],[16,"ואי בעית אימא","דקאמרת שומרת יום הא כתיבא הא לא קשיא דכי קתני כגון דאמרי זבה לא הוה אלא [היכא דחזיא] ביממא כדכתי' כל ימי זובה אבל היכא דחזיא בליליא טהורה והוא הדין לשומרת יום דאמרי דהוא היכא דקחזיא ביממא דהיינו בימי זיבה הלכך לא מתוקמא בנדה אלא בשומרת יום ובזבה והויא הוראה בדבר שאין הצדוקין מודין:"],[18,"מושיט וזורק","לא כתיבי בהדיא:"],[20,"השתחואה שלא כדרכה","כגון משתחוה לפעור או למרקוליס:"],[20,"השתחואה","בפשוט ידים ורגלי' כדכתי' (בראשית י״ט:א׳) וישתחו אפים ארצה:"]],[[1,"","שהביא כפרתו בין השמשות. משמע אבל קודם לכן נתכפר אע\"ג דקרב אחר תמיד בין הערבים וקשה דבתוספתא משמע דפסולין וכן משמע בפסחים דרמי התם כתיב לא ילין עד בוקר הא כל הלילה ילין וכתיב השלמים עליה השלם כו' ולא משני הא לכתחלה הא דיעבד אלמא דפסולין. ושמא הכא נמי איירי במחוסר כפורים בערב פסח כדאמרינן התם אין מתעכב אחר התמיד בין הערבים אלא קטרת ונרות ומחוסר כפורים בערב פסח:"],[8,"","קרי ביה ונעלם מדבר. דמ\"ם מונעלם קאי להכא ולהכא ואמר בירושלמי דאיכא דאמר גורעין ודורשין מתחלת פרשה לסופה וא\"ד אף באמצע פרשה ויצקת עליה שמן הצקת שמן המנחה ללמד כל המנחות ליציקה הקשה ריב\"ק בר' מאיר מאי שנא דהכא דרשינן ונעלם מדבר וגבי עדות יקום דבר לכ\"ע דרשינן דבר ולא חצי דבר. וי\"ל דודאי דבר כולה דבר משמע והכא מעניינו דקרא מכדי כתיב אחת מכל מצות ה' דמשמע מצוה שלימה למאי הלכתא כתב דבר אלא ע\"כ למדרש ונעלם מדבר אפי' דבר אחד מן המצות וכן בכל דוכתי גורעין ומוסיפין ודורשין משום דוחקא דקרא דאיהו דחיק ומוקים אנפשיה. כי ההוא דהזהב דה\"ל למכתב וחמישיתו יוסף עליו כי היכי דכתיב גבי מעשר. ובפ' יש נוחלין ה\"ל למכתב אשתו תירש את הנחלה וכי כתב קרא צריך ליישב המקרא על ידי גרעון ותוספת. תימה מנ\"ל דאתי קרא לחייב רק קיום מקצת וביטול מקצת דלמא קרא אתא אפילו לחייב בכך וכל שכן בביטול כל הגוף כדאמר בפ' הנחנקין גבי עבודת כוכבי' דכתי' מן הדרך אפי' מקצת דרך וחייב בקיום מקצת ובין על כל הגוף אבל בשאר מצות אינו חייב אלא בביטול כל הגוף. וי\"ל דהתם כתיב ללכת בה ותניא בספרי ולא העושה במקצת ומשייר מקצת מיעוט בהדי קיום מקצת להכי בעבודת כוכבים דגלי קרא חייב אפילו במקצת הגוף. וגם בביטול כל הגוף חייב דלא גרע משאר מצות ואי לאו מיעוט דשאר מצות והוי כתיב סתמא היה חייב נמי בשאר מצות בכל ענין והכי נמי הכא ולהכי כתיב הכא דבר למעוטי כל הגוף. וליכא למימר אפכא דדבר כולו דבר משמע דתניא בת\"כ כתיב הכא מכל מצות ה' וכתי' במשיח מכל מצות ה' ואי לא דמיחייב אלא בעוקר כל הגוף לא משכחת במצות האמורות אלא בתו מאנוסתו ואם חמותו ואם חמיו דבר שאין הצדוקין מודין בו. הועתק מפי' רבינו שמחה זצ\"ל:"],[10,"","רב אשי אמר יליף דבר דבר מזקן ממרא. והתם יליף בתוספתא בין דם לדם ולא כל דבר והני דהכא לא שמיע להו ברייתא דילן מטעמא אחרינא:"],[11,"","בדבר שאין הצדוקין מודין בו. והא דאצטריך למעוטי כוליה דבר ולא נפיק משום דצדוקין מודין בו. כמו בתו מאנוסתו דלית להו ג\"ש או אם חמיו ואם חמותו ומתני' דנקט נדה ושבת ועבודת כוכבים לא משום דאהנהו דוקא קאי אלא רק לפרש קיום מקצת נקטינהו:"],[12,"","יש נדה אבל הבא על שומרת יום כו'. בנדה גופה הוי מצי לאשכוחי טובא כגון בדם אדום בדם שחור וטובא דחשיב בת\"כ אלא דאתא לאשמועינן אפילו בשומרת יום ובנדה מקרי קיום מקצת וביטול מקצת ובגמרא דפריך אי הכי אפילו נדה נמי ה\"פ אפילו נדה בכה\"ג אי הוה בדבר שאין הצדוקין מודין בו הוי קיום מקצת:"],[12,"","הכתיב וספרה לה ל\"ג דהא בשמעתא בתרייתא דנדה מפיק לה ממשכב נדתה יהיה לה:"],[14,"","שלא כדרכה נמי הכתיב כו'. משמע דצדוקין מודין בו ובפ' אחד דיני ממונות גבי טעה בנואף ונואפת משמע דאין צדוקין מודין בו התם בהעראה שלא כדרכה:"],[16,"","הכתיב כל ימי זובה. ה\"מ לאתויי קרא קמא דכתיב זוב דמה ימים רבים:"],[18,"","דאמרי הוצאה אסירא והכנסה שריא. ותנא הוצאה הכנסה קרי לה כדאמרינן במס' שבת (ב:) ובמסכת שבועות (ה.):"],[18,"","איכא דאמרי הוצאה והכנסה (שריא) [הוא דאסירא] אע\"ג דהכנסה לא כתיבא סברא היא מה לי אפוקי מה לי עיולי (שבת צו:):"]]],[["בעי רב יוסף אין חרישה בשבת מהו מי אמרי' כיון דקא מודו בכולהו מלתא כביטול מקצת וקיום מקצת דמי או דלמא כיון דקא עקריין ליה לחרישה כל עיקר כעקירת גוף דמי","ת\"ש יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור ואמאי הא עקריין לשומרת יום כנגד יום כל עיקר","אמר לך רב יוסף שומרת יום דקאמרין כדשנין","ת\"ש יש שבת בתורה אבל המוציא מרה\"י לרה\"ר פטור ואמאי הא עקריין להוצאה כל עיקר","התם נמי כדשנין","ת\"ש יש עבודת כוכבים בתורה אבל המשתחוה פטור ואמאי והא עקריין להשתחויה כל עיקר","אמרי השתחויה נמי כדשנין","בעי ר' זירא אין שבת בשביעית מהו במאי טעו בהדין קרא (שמות לד, כא) בחריש ובקציר תשבות בזמן דאיכא חרישה איכא שבת ובזמן דליכא חרישה ליכא שבת","מי אמרינן כיון דמקיימין לה בשאר שני שבוע כביטול מקצת וקיום מקצת דמי או דלמא כיון דקא עקריין ליה בשביעית כעקירת הגוף דמי","אמר רבינא ת\"ש נביא שנתנבא לעקור דבר מדברי תורה חייב לביטול מקצת ולקיום מקצת רבי שמעון אומר פטור ובעבודת כוכבים אפילו אמר היום עובדה ולמחר בטלה חייב שמע מינה אין שבת בשביעית כביטול מקצת וקיום מקצת דמי שמע מינה:","\u0001מתני׳\u0002 הורו ב\"ד וידע אחד מהן שטעו ואמר להן טועין אתם או שלא היה מופלא של ב\"ד שם או שהיה אחד מהן גר או ממזר או נתין או זקן שלא ראוי לבנים ה\"ז פטור","שנאמ' כאן עדה ונאמר להלן עדה מה עדה האמורה להלן כולן ראוין להוראה אף עדה האמורה כאן עד שיהיו כולן ראוין להוראה:","\u0001גמ׳\u0002 או שלא היה מופלא של ב\"ד שם מנלן אמר רב ששת וכן תנא דבי רבי ישמעאל מפני מה אמרו הורו בדבר שהצדוקין מודין בו פטורין מפני שהיה להם ללמוד ולא למדו לא היה מופלא של ב\"ד שם נמי פטורין מפני שהיה להם ללמוד ולא למדו:","נאמר שם עדה ונאמר כאן עדה עד שיהו כולן ראוין להוראה: והתם מנלן דאמר רב חסדא אמר קרא (במדבר יא, טז) והתיצבו שם עמך עמך בדומין לך","ואימא עמך לשכינה אלא אמר ר\"נ בר יצחק אמר קרא ונשאו אתך אתך בדומין לך:","\u0001מתני׳\u0002 הורו ב\"ד שוגגין ועשו כל הקהל שוגגין מביאין פר מזידין ועשו שוגגין מביאין כשבה ושעירה שוגגין ועשו מזידין הרי אלו פטורין:","\u0001גמ׳\u0002 שוגגין ועשו מזידין הרי אלו פטורין הא שוגג דומיא דמזיד חייב והיכי דמי שהורו בית דין שחלב מותר ונתחלף לו בשומן ואכלו","לימא תפשוט הא דבעי רמי בר חמא אמר לך משום דתנא רישא מזידין ועשו שוגגין תנא סיפא שוגגין ועשו מזידין:","\u0001מתני׳\u0002 הורו ב\"ד ועשו כל הקהל או רובן על פיהן מביאין פר ובעבודת כוכבים מביאין פר ושעיר דברי ר\"מ ר' יהודה אומר י\"ב שבטים מביאין י\"ב פרים ובעבודת כוכבים מביאין י\"ב פרים ושנים עשר שעירים"],[[0,"בעי רב יוסף אין חרישה בשבת מהו","הכא לא מבעיא ליה לרב יוסף בדבר שאין הצדוקין מודין כלל אלא בבטול מקצת וקיום מקצת קא מבעיא ליה:"],[0,"מי אמרינן כיון דקא מודו","ב\"ד בכולהו שאר מלאכות דשבת דאסירי כבטול מקצת וקיום מקצת דמי וחייבין:"],[2,"(וכלהו) כדשנין","לעיל דלא הוי עקירת כל הגוף דשומרת יום:"],[4,"(וכולה) כדשנין","דמושיט וזורק שרי דלא הוי עקירת כל הגוף:"],[6,"(וכולה) כדשנין","דהשתחואה שלא כדרכה שריא:"],[7,"בחריש ובקציר תשבות","דמשמע בזמן דאיכא חרישה דהיינו בשאר שני שבוע תשבות איכא שבת:"],[7,"בזמן דליכא חרישה","דהיינו בשביעית ליכא שבת:"],[9,"נביא שהתנבא","כגון שתחלתו נביא של אמת ולבסוף נביא השקר שהתנבא לעקור דבר מדברי תורה חייב ודברי הכל בחנק:"],[9,"לקיום מקצת ולבטל מקצת","דשאר מצות ר\"ש פוטר וה\"ה לרבנן:"],[9,"ובעבודת כוכבים אפי' אמר לך היום עובדה ולמחר בטלה","דהיינו קיום מקצת ובטול מקצת דעבודת כוכבים חייב דרחמנא אמר להדיחך מן הדרך אפי' מקצת דרך ובעבודת כוכבי' הוא דכתיב וכי קתני חייב כגון לרבנן בסקילה ולר\"ש בחנק והכי מתרץ ליה רב חסדא בפ' אלו הן הנחנקין (סנהדרין דף צ.) והיום עובדה ולמחר בטלה כאין שבת בשביעית דמי וקרי להו ביטול מקצת וקיום מקצת ש\"מ:"],[10,"מתני' ואמר להם טועים אתם","לא הוי הוראה מעליא ופטור דבעינן עד שיורו כולן כדאמר לעיל:"],[10,"או שלא היה מופלא של ב\"ד שם","אע\"ג דלא הוה מסנהדרין עצמן דאילו הוי מסנהדרין עצמן אפי' (אם) קטן שבכולן לא היה שם לא הויא הוראה מעליא כדאמר לקמן מאם כל עדת איתא לכולה סנהדרי הויא הוראה ואי לא לא ואיכא למימר נצטרך אחד מהן לצאת לדרך ומינו אחר במקומו א\"נ זקן (או) שאין לו בנים היה לכך נתמנה אחר בסנהדרין:"],[10,"או זקן שאין ראוי לבנים","וקשיא לי מפני מה אין ראוי להוראה:"],[11,"ונאמר להלן עדה","ושפטו העדה והצילו העדה (במדבר ל״ה:כ״ה) דהיינו סנהדרין כדתנן בפ\"ק דסנהדרין (ד ב):"],[11,"נאמר כאן עדה","דכתיב (ויקרא ד׳:י״ג) אם כל עדת ישראל ישגו: (ושפטו את העדה) מה להלן ראויין להוראה כו':"],[13,"גמ' והתם מנ\"ל","דכולהו דהויין ראויין להוראה:"],[13,"אמר רב חסדא","גמר ממשה דמשה אוקי סנהדרין דהוו כולן ראויין להוראה דכתי' והתיצבו שם עמך עמך בדומין לך דליהוי (הם) כולן ראויין להוראה ה\"נ בעינן דסנהדרי דעלמא ליהוו ראויין להוראה והואיל ומצינו דעדה האמורה כאן כולן ראויין להוראה שמעינן מינה נמי דהיינו סנהדרי גדולה דתניא בת\"כ עדת ישראל עדה המיוחדת לכל ישראל ואיזו זו סנהדרי גדולה:"],[14,"ואימא עמך משום שכינה","דלגופיה הוא דאתא כלומר שיהו עומדין עמך ולא יכנסו לפני ולפנים במקום שכינה דסלקא דעתא אמינא והואיל דכתב אספה לי דיכנסו במקום שכינה קמ\"ל [ל\"א] עמך משום שכינה כלומ' ברור צדיקים גמורים שאני רוצה להשרות שכינה עליהם:"],[14,"אתך בדומין לך","שיהיו ראויין להוראה:"],[15,"מתני' הורו ב\"ד שוגגין ועשו הקהל שוגגין","על פיהם ב\"ד מביאין פר רבי מאיר כדאית ליה ור' יהודה כדאית ליה ור\"ש כדאית ליה דהוי הוראה מעליא:"],[15,"הורו ב\"ד מזידין ועשו הקהל שוגגין","לא הוי הוראה מעליא דאם כל עדת ישראל ישגו כתיב דבעינן שוגגין בב\"ד והכא הוה ליה שגגת מעשה בלא הוראה ומביאין כל אחד מן הקהל כשבה או שעירה דכיחיד דמו:"],[15,"הורו ב\"ד שוגגין ועשו הקהל מזידים פטורים","דמזיד לאו בר קרבן הוא:"],[16,"גמ' טעמא דשוגגין ועשו מזידים דפטורין","דמזיד לאו בר קרבן הוא לא צבור ולא יחיד הא שוגג דומיא דמזיד דלא הוי ממש תולה בב\"ד הוי שוגג תולה בעצמו וחייב בשגגת מעשה קרינא ביה:"],[16,"כגון שהורו ב\"ד שחלב מותר","שעל הקרב ולא שעל הכליות דלא הוי עוקר כל הגוף:"],[16,"ונתחלף חלב בשומן ואכלו","דחייב דתולה בעצמו הוא והאי דקרי ליה דומיא דמזיד משום דכי היכי דמזיד לאו תולה בב\"ד הוא האי שוגג נמי לאו תולה בב\"ד הוא ותפשוט האי דבעי רמי בר חמא (לעיל הוריות דף ב):"],[17,"אמר לך","רמי בר חמא האי דקתני שוגגין ועשו מזידים לאו למידק מינה קא אתי אלא איידי דתנא מזידין ועשו שוגגין תנא נמי שוגגין ועשו מזידים וכדי נסבה ולא דייקי' מינה כלום ובעיא דידי' מהא ליכא למשמע מינה:"],[18,"מתני' הורו ב\"ד ועשו כל הקהל או רובן על פיהן מביאין פר","(כגון) ב\"ד ולא צבור:"],[18,"בעבודת כוכבים ב\"ד מביאין פר ושעי' דברי ר\"מ","דבעבוד' כוכבים בהוראה פר ושעיר מייתי דכתי' בפ' שלח לך אנשים וכי תשגו ולא תעשו את כל המצות האלה דהיינו בעבודת כוכבים כדאמר לקמן בפרק הורה כהן משיח איזו היא מצוה ששקולה כנגד כל המצות הוי אומר זה עבוד' כוכבי' וכתיב (במדבר טו) ועשו כל העדה פר בן בקר אחד לעולה לריח ניחוח לה' ומנחתו ונסכו כמשפט ושעיר עזים אחד לחטאת:"],[18,"רבי יהודה אומר י\"ב שבטים מביאין י\"ב פרים","דכל שבט ושבט אקרי קהל וקסבר צבור מביאין פר ולא בית דין:"]],[[0,"","בעי רב יוסף אין חרישה כו'. רישא דאבות מלאכות דפ' כלל גדול נקט אבל חרישה צדוקין מודין בה ולרב יוסף נמי בעי דבר שאין מודין בו כדלקמן אמר לך רב יוסף כו' משמע דסבר כשמואל:"],[7,"","ש\"מ אין שבת בשביעית כו'. משמע דאין צדוקין מודין בהאי דרשא אע\"ג דלעיל דרשי ליה יהיה לה לשומרת (יבם) [יום]:"],[10,"","או שלא היה מופלא שבב\"ד שם. פרש\"י ולא היה במנין דא\"כ אפי' קטן שבהם נמי כדאמרי' לעיל שיהיו כולן בהוראה. וקשה דהא אתותב לעיל (נ\"ל דצריכין לומר דלפני התו' לא היה כתוב לעיל הא דמסיק ואלא מאי כל עדת דקאמר רחמנא כו' עי' לקמן ברש\"י דף (ה') [הוריות ז'] ע\"א) ובת\"כ מוסיף נמי אם אמר א' איני יודע דכמאן דליתי' דמיא:"],[10,"","אחד מהן גר או ממזר. בירושלמי שעברו ומנוהו. דמי שאין ראוי להוראה נעשה כאבן:"]]],[["רבי שמעון אומר י\"ג פרים ובעבודת כוכבים שלשה עשר פרים וי\"ג שעירים פר ושעיר לכל שבט ושבט פר ושעיר לב\"ד","הורו ב\"ד ועשו ז' שבטים או רובן על פיהן מביאין פר ובעבודת כוכבים מביאין פר ושעיר דברי ר\"מ רבי יהודה אומר ז' שבטים שחטאו מביאין ז' פרים ושאר שבטים שלא חטאו מביאין על ידיהן פר שאף אלו שלא חטאו מביאין ע\"י חוטאין ר\"ש אומר ח' פרים ובעבודת כוכבים ח' פרים וח' שעירים פר ושעיר לכל שבט ושבט פר ושעיר לב\"ד","הורו ב\"ד של אחד מן השבטים ועשה אותו השבט על פיהן אותו שבט הוא חייב ושאר כל השבטים פטורין דברי רבי יהודה וחכמים אומרים אין חייבין אלא על הוריות בית דין הגדול בלבד שנאמר (ויקרא ד, יג) ואם כל עדת ישראל ישגו ולא עדת אותו שבט:","\u0001גמ׳\u0002 ת\"ר ידעו שהורו וטעו מה הורו יכול יהו חייבין ת\"ל (ויקרא ד, יד) ונודעה החטאת ולא שיודעו החוטאין","אשר חטאו חטאו שני שבטים מביאין שני פרים חטאו שלשה מביאין שלשה או אינו אומר אלא חטאו שני יחידים מביאין שני פרים חטאו ג' מביאין ג' ת\"ל הקהל הקהל חייב וכל קהל וקהל חייב כיצד חטאו שני שבטים מביאין שני פרים חטאו ז' מביאין ז' ושאר שבטים שלא חטאו מביאין על ידיהן פר פר שאפילו אלו שלא חטאו מביאין ע\"י החוטאין לכך נאמר קהל לחייב על כל קהל וקהל דברי רבי יהודה","ר\"ש אומר ז' שבטים שחטאו מביאין ז' פרים ובית דין מביאין על ידיהן פר שנאמר למטה קהל ונאמר למעלה קהל מה קהל האמור למעלה ב\"ד עם הקהל אף קהל האמור למטה ב\"ד עם הקהל","רבי מאיר אומר ז' שבטים שחטאו ב\"ד מביאין על ידיהם פר והן פטורין נאמר קהל למטה ונאמר קהל למעלה מה קהל האמור למעלה ב\"ד ולא צבור אף קהל האמור למטה ב\"ד ולא צבור","רבי שמעון בן אלעזר אומר משמו חטאו ששה שבטים והם רובו של קהל או ז' אע\"פ שאינו רובו של קהל מביאין פר","אמר מר ונודעה החטאת ולא שיודעו החוטאין מאן תנא אמר רב יהודה אמר רב ואיתימא רבא דלא כרבי אליעזר דתנן","אמר ר' אליעזר מה נפשך אם חלב אכל חייב נותר אכל חייב","רב אשי אמר אפילו תימא רבי אליעזר שאני הכא דכתיב אשר חטאו עליה התם נמי הכתי' אשר חטא בה ההוא מיבעי ליה פרט למתעסק","מ\"ט דר' יהודה קסבר ארבעה קהלי כתיבי קהל הקהל קהל הקהל","חד לחייב על כל קהל וקהל וחד להוראה תלויה בב\"ד ומעשה תלוי בקהל וחד לגרירה וחד לשבט שעשה בהוראת ב\"ד","ור\"ש תלתא קהלי כתיבי הקהל קהל הקהל מעיני הקהל אורחיה דקרא הוא כדאמרי אינשי מעיני דפלניא","חד לחייב על כל קהל וקהל ותרי אחריני נאמר למטה קהל ונאמר למעלה קהל מה להלן ב\"ד עם הקהל אף כאן ב\"ד עם הקהל","ור\"מ קהל הקהל לא דריש הלכך תרי קהלי כתיבי מיבעי ליה לנאמר למטה קהל ונאמר למעלה קהל מה להלן ב\"ד ולא צבור אף כאן ב\"ד ולא צבור","ורשב\"א מ\"ט כתי' והיה אם מעיני העדה אלמא מיעוטא דכתיב מעיני וכתי' כי לכל העם בשגגה למימרא דרובא אין מיעוטא לא","הא כיצד עשו ו' והן רובו של קהל או ז' אע\"פ שאינן רובו של קהל חייבין"],[[0,"רבי שמעון אומר שלש עשרה פרים","פר לכל שבט ושבט ופר לבית דין וטעמייהו דכולהו מפרש בגמרא:"],[1,"הורו בית דין ועשו שבעה שבטים או רובו","של כל שבט ושבט דשבעה שבטים וכגון דהוי רובן של ישראל מביאין פר וכו' דברי רבי מאיר [דס\"ל] ב\"ד מביאין פר ולא צבור:"],[1,"רבי יהודה אומר ז' שבטים שחטאו מביאין ז' פרים ושאר שבטים שלא חטאו מביאין פר פר על ידיהם","כלומר פר לכל שבט ושבט ואמר בגמרא דז' דקאמר ר' יהודה לאו דוקא דהוא הדין לשבט אחד שחטא על הוראת בית דין הגדול שהשאר שבטים שלא חטאו מביאין על ידיהן פר פר ואיידי דקאמר ר\"מ ז' דאיהו בעי רובא ממש קא\"ר יהודה נמי:"],[2,"וחכמים אומרים אין חייבים פר אלא על הוראת ב\"ד הגדול","אבל שבט אחד בהוראת בית דינו כשגגת מעשה דמי ומביאין כל אחד כשבה או שעירה:"],[2,"עדת ישראל","היינו סנהדרין כלומר סנהדרין של ישראל דהיינו ב\"ד הגדול:"],[3,"גמ' ידעו שהורו וטעו מה שהורו","כלומר הורו ב\"ד שחלב מותר בבטול מקצת ועשו קהל על פיהן ואכלו שוגגין חלב ודם דהוי חד בשגגת מעשה בלבד וחד בהוראה ואח\"כ ידעו שהורו שלא כראוי אלא שטעו במה שהורו דאינם יודעים אם על החלב הורו או על הדם יכול יהו חייבין פר דליהוי הוראה מעליא:"],[3,"ת\"ל ונודעה החטאת","אשר חטאו עליה והקריבו כלומר דצריך שיודע החטאת שיהיו יודעין על מה הורו אם על החלב או על הדם:"],[3,"ולא שידעו החוטאין","דלא סגי בידיעה דחוטאין דאע\"ג דעשו בהוראה דממה נפשך חד מנייהו בהורא' הוה דהא אכלי לתרווייהו חלב ודם אפ\"ה פטורין דצריך שיברר להם אותו חטא שעשו בהוראה:"],[4,"חטאו שני שבטים מביאין ב' פרים","והוא הדין דכי חטא שבט אחד שמביא פר אחד והא קמ\"ל דשני שבטים לא סגי להו בפר אחד:"],[4,"לחייב על כל קהל וקהל","דשבט אחד איקרי קהל כדמפרש טעמא לקמן:"],[5,"מה הקהל האמור למעלה ב\"ד עם הקהל","דתרוייהו כתיב למעלה ב\"ד עם קהל דכתיב ונעלם דבר מעיני הקהל דהאי מעיני היינו ב\"ד:"],[5,"אף קהל האמור למטה","והקריבו הקהל ב\"ד עם הקהל:"],[6,"","הכי דריש ר\"מ מה קהל האמור למעלה ונעלם דבר מעיני הקהל בית דין ולא קהל כלומר דהוראה תלויה היא בב\"ד ולא בקהל דהא לא כתיב ונעלם מקהל אלא מעיני הקהל דמשמע מב\"ד של קהל ולא מקהל אף קהל האמור למטה והקריבו הקהל בית דין ולא צבור:"],[9,"מה נפשך","דתנן במסכת כריתות בפ' ספק אכל חלב (כריתות דף יט.) חלב ונותר לפניו ואכל את אחד מהם ואינו יודע איזה מהן אכל רבי אליעזר מחייב חטאת ורבי יהושע פוטר ותניא אמר רבי אליעזר מה נפשך אם חלב אכל חייב אם נותר אכל חייב אמר לו רבי יהושע הרי הוא אומר אשר חטא בה עד שיודע לו במאי חטא הכא נמי סבירא ליה לר' אליעזר מה נפשך אם חלב אכלו בהוראה מביאין פר ואם דם אכלו בהוראה מביאין פר וחייבין ממ\"נ:"],[10,"","אפי' תימא רבי אליעזר ושאני הכא דכתיב ונודעה החטאת אשר חטאו עליה והקריבו. דמשמע שיודע להם החטא שחטאו עליו ע\"פ בית דין:"],[10,"התם נמי הא כתיב אשר חטא בה","דמשמע עד שיודע לו במה חטא:"],[10,"בה","(פרט למתעסק דבה) משמע דמתכוין לעשות החטא פרט למתעסק בשבת כגון שנתכוין להגביה את התלוש וחתך את המחובר דפטור אבל מתעסק בחלבי' ובעריות חייב שכבר נהנה כדאמר בפ' ד' מיתות (סנהדרין סב:):"],[11,"ד' קהל כתיבי","מעיני הקהל והקריבו הקהל דלימא קרא מעיני קהל מאי הקהל תרי וליכתוב קרא והקריבו קהל מאי הקהל תרי והרי ארבעה. חטאת הקהל לא קא חשיב דהא לא כתיב לא בהוראה ולא בהקרבה:"],[12,"לחייב על כל קהל וקהל","על כל שבט ושבט דשבט אחד איקרי קהל כדאמר לקמן:"],[12,"וחד להוראה תלויה בב\"ד","כדאמר לעיל (הוריות דף ג.) הקהל ועשו הוראה תלויה בב\"ד ומעשה תלוי בקהל וחד למידה דשאר שבטין שלא חטאו נגררין אחר החוטאין ומביאין על ידיהם פר פר:"],[12,"וחד לשבט שעשה בהוראת בית דינו","כדתנן בסיפא דמתניתין הורו ב\"ד של אחד מן השבטים כו':"],[13,"ג' קהל כתיבי","מעיני הקהל לא דרשינן ביה תרתי דהא לשמוש הוא דאתא דאורחיה דקרא דמשתעי הכי כדאמרי אינשי מעיני דפלניא הכא נמי מעיני הקהל משמע מעיני של קהל וחד הוא אבל והקריבו הקהל דרשינן ביה תרי דלכתוב קרא והקריבו קהל מאי הקהל תרי הא תלת:"],[14,"חד לחייב על כל קהל וקהל","דר\"ש נמי ס\"ל דשבט אחד איקרי קהל אייתרי ליה תרי לג\"ש נאמר קהל למעלה וכו':"],[16,"ור\"ש בן אלעזר מ\"ט","דכתיב בהוראה דעבודת כוכבים בפרשת שלח לך אנשים והיה אם מעיני העדה אלמא אפי' מיעוטא חטאו מביאין פר ושעירה דכתיב מעיני משמע מקצת עיני ולא כל עיני וכתיב כי לכל משמע דרובא אין דרובו ככולו ומיעוטא לא הא כיצד וכו' דמעיני אפי' מיעוט קהל כגון ברוב שבטים והאי דכתי' כי לכל דבעינן רובא דקהל אפילו במיעוט שבטים:"]],[[9,"","אם חלב אכל חייב כו'. תימה מי דמי התם בין בחלב בין בנותר חד קרבן הוא אבל הכא קרבן דעבודת כוכבים אינו שוה לחלב. וצ\"ל דה\"נ ידעי דלא איירי אלא בעניינים שקרבנם שוה כעין חלב ודם כדפרש\"י:"],[13,"","ור\"ש תלתא קהלי כתיבי כו'. יש ספרים דגרסי תרי קהל כתיבי וכן נראה ובעי למימר דחד קהל כוליה קרא לאורחא דקרא וחד קהל דרשינן קהל הקהל והיינו תרי קהל. ולר' מאיר חד קהל כוליה לאורחא דקרא ומיניה נמי שמעינן דאיירי בבית דין ולא בצבור וחד קהל לג\"ש ולפי הגירסא הכתוב בספרים בעי למימר דתרוייהו אתו לג\"ש ולא נהירא. מיהו אפשר דתלמודא בעי למימר לרבי שמעון דקהל האמור למעלה הוא בית דין עם הצבור ואי לא כתיב ההוא קהל ה\"א דקהל למטה היינו צבור ולא בית דין ולרבי מאיר משמע איפכא. וע\"ק אליבא דרבי שמעון לימא ד' קהל כתיבי ומייתר ליה חד קהל למעשה תלוי בקהל ולא הוה צריך לאהדורי אקרא אחרינא. מיהו ליכא למפרך לר\"מ לדרוש ג' קהל כרבי שמעון למדרש מעשה תלוי בקהל כיון דאית ליה ג\"ש דקהל בבית דין אמור א\"כ לא מצי למילף משם מעשה תלוי בקהל דהא לעיל אמר הקהל ועשו הוראה תלויה בב\"ד ומעשה תלוי בקהל א\"כ מי שלמד משם סובר דקהל האמור למעלה בצבור מיירי ולר\"מ לא ס\"ל הכי דבצבור מיירי:"]]],[["ורבי שמעון ורבי מאיר דהוראה תלויה בבית דין ומעשה תלוי בקהל מנא להו אמר אביי דאמר קרא (במדבר טו, כד) והיה אם מעיני העדה נעשתה לשגגה רבא אמר (במדבר טו, כו) מלכל העם בשגגה","וצריכא דאי כתב רחמנא והיה אם מעיני העדה נעשתה לשגגה הוה אמינא אפילו מיעוטא להכי כתיב לכל העם בשגגה ואי כתב לכל העם בשגגה הוה אמינא עד דעבדי בית דין בהדי רובא להכי כתיב והיה אם מעיני העדה נעשתה לשגגה","והא כי כתיבי הני קראי בעבודת כוכבים הוא דכתיבי ילפינן מעיני מעיני:","הורו ב\"ד של אחד וכו': איבעיא להו שבט אחד לרבי יהודה בהוראת ב\"ד הגדול מי מייתו שאר שבטים או לא מי אמרינן שבעה שבטים הוא דמייתו שאר שבטים בהדייהו משום דאיכא רובא אבל חד שבט דליכא רובא לא או דלמא לא שנא","תא שמע מה הן מביאין פר אחד רבי שמעון אומר שני פרים במאי עסקינן אילימא שחטאו שבעה ר\"ש תמניא בעי אלא דחטא שבט אחד במאי אי בהוראת בית דינו רבי שמעון לית ליה אלא לאו בהוראת בית דין הגדול","ותנא קמא מני אי נימא רבי מאיר הא רובא בעי אלא לאו רבי יהודה וכגון שחטא שבט אחד","אמרי הכא במאי עסקינן כגון שחטאו ששה שבטים והן רובן של קהל ורבי שמעון בן אלעזר היא דתניא ר\"ש בן אלעזר אומר משמו חטאו ששה והן רובו של קהל או שבעה אף על פי שאינן רובו של קהל מביאין פר","תא שמע רבי יהודה אומר שבט שעשה בהוראת בית דינו אותו השבט חייב ושאר כל השבטים פטורין ובהוראת ב\"ד הגדול אפילו שאר שבטים חייבים שמע מינה","אמר רב אשי מתניתין נמי דיקא דקתני ועשה אותו השבט על פיהם אותו השבט חייב ושאר כל השבטים פטורין למה לי למיתנא ושאר שבטים פטורים הא תנא אותו השבט חייב וכיון דתנא אותו השבט חייב ממילא ידענא שאר שבטים פטורין אלא הא קמשמע לן דבהוראת בית דינו הוא דשאר שבטים פטורים אבל בהוראת ב\"ד הגדול אפילו שאר שבטים חייבין שמע מינה","איבעיא להו שבט אחד שעשה בהוראת בית דין הגדול לרבי שמעון מי מייתי או לא","תא שמע מה הן מביאין פר אחד רבי שמעון אומר שני פרים במאי עסקינן אילימא שחטאו שבעה שני פרים שמנה פרים בעי אלא דחטא שבט אחד ובמאי אילימא בהוראת בית דינו רבי שמעון לית ליה אלא בהוראת בית דין הגדול","ותסברא תנא קמא מני אי רבי מאיר הא רובא בעי אי רבי יהודה שאר שבטים נמי מייתו אלא הא מני רבי שמעון בן אלעזר היא וכדתניא","תא שמע וחכמים אומרים לעולם אינו חייב אלא על הוראת בית דין הגדול מאן חכמים אילימא רבי מאיר רובא בעי אלא לאו רבי שמעון היא שמע מינה","ורבי יהודה ורבי שמעון שבט אחד דאקרי קהל מנא להו אמרי דכתיב ויעמד יהושפט בקהל יהודה וירושלים (נכח חצר בית ה') [בבית ה' לפני החצר] החדשה מאי חדשה א\"ר יוחנן שחידשו דברים ואמרו טבול יום אל יכנס במחנה לויה","מתקיף לה רב אחא בר יעקב ממאי דלמא שאני ירושלים דהוה נמי בנימין אלא אמר רב אחא בר יעקב דכתיב ויאמר אלי הנני מפרך והרביתיך ונתתיך לקהל עמים וגו' מאן אתיליד ליה ההיא שעתא בנימין ש\"מ ה\"ק רחמנא מתיליד לך השתא קהל אחרינא","א\"ל רב שבא לרב כהנא דלמא הכי קא\"ל רחמנא לכי מתיליד לך בנימין הוא דהוו י\"ב שבטים דמתקריית קהל א\"ל אלא שנים עשר שבטים איקרו קהל אחד עשר שבטים לא איקרו קהל","תניא ר\"ש אומר מה תלמוד לומר ופר שני בן בקר תקח לחטאת אם ללמד שהם שנים והלא כבר נאמר ועשה את האחד חטאת ואת האחד עולה לה' [אלא] יכול [תהא] נאכלת חטאת ללוים ת\"ל ופר שני שני לעולה מה עולה לא נאכלת"],[[0,"ור\"ש ור\"מ","דדרשי תרי קהל לג\"ש ולא אייתר חד להוראה תלויה בבית דין אם כן הוראה תלויה בבית דין מנא להו:"],[0,"מעיני העדה נעשתה לשגגה","שתעשה לשגגה על ידי אחרים דהיינו על ידי הוראת ב\"ד דהוראה תלויה בבית דין:"],[0,"רבא אמר כי לכל העם בשגגה","שיהו כולם תלויין בשגגת הקהל וב\"ד דהוראה תלויה בב\"ד ומעשה תלוי בקהל:"],[1,"הוה אמינא אפי' מיעוט","חטאו מביאין פר:"],[1,"הוה אמינא בית דין בהדי רובא","ולא יהו מביאין פר עד שיעשו בית דין עם הצבור דליבעי לבית דין הוראה ועשיה כתב רחמנא והיה אם מעיני העדה נעשתה לשגגה שתעשה שגגה על ידי אחרים דהוראה בלבד תלויה בבית דין:"],[2,"ילפינן מעיני מעיני","כתיב הכא מעיני הקהל וכתיב בעבודת כוכבים והיה אם מעיני העדה:"],[3,"אבל חד שבט דליכא רובא לא","והוא הדין לשנים או שלשה שבטים:"],[4,"רבי שמעון תמניא בעי","פר לכל שבט ושבט ופר לבית דין:"],[4,"אי בהוראת בית דינו רבי שמעון לית ליה","דהא לא מייתר ליה (לא) קהל להוראת בית דינו:"],[5,"אלא לאו רבי יהודה היא","וקתני מה הן מביאין פר אחד אלמא לא מייתו שאר שבטים בהדיה:"],[6,"אמרי הכא במאי עסקינן וכו'","ותנא קמא רבי שמעון בן אלעזר הוא ורבי שמעון דאמר שני פרים קסבר פר לכל שבט ושבט דשבט א' איקרי קהל כגון שחטאו שבעה שבטים והן רובן של קהל דכי הויא רובא בגברי ורובא בשבטים הוא דמביא פר לכל שבט ושבט ופר לב\"ד אבל היכא דאיכא ששה והן רובא או שבעה ואינן רובא כיון דלאו רובא בגברי ורובא בשבטים כחד שבט דמו ומביאין פר אחד ופר לב\"ד:"],[9,"","איבעיא להו שבט אחד שעשה בהוראת בית דין הגדול לרבי שמעון מי מייתו. פר או לא מי אמרינן כי אמר ר' שמעון לחייב על כל קהל וקהל דשבט אחד איקרי קהל כגון שחטאו שבעה שבטים דהוו רובן אבל היכא דליכא רובא כיחיד דמו ופטורים דיחיד שעשה בהוראת ב\"ד פטור או דלמא כיון דסבירא ליה דשבט אחד איקרי קהל לא שנא שבט אחד ולא שנא שבעה מביאין פר לכל שבט ושבט ופר לב\"ד:"],[11,"אלא","הכא במאי עסקינן כגון שחטאו ששה וכו' דכיון דאיכא רוב רובא כל דהו קאמר דמביאין פר ופר לב\"ד:"],[12,"אלא לאו רבי שמעון","וקתני שבט אחד חייב על הוראת בית דין הגדול אלמא כי אמר שבט אחד איקרי קהל אפי' כי חטא שבט אחד כמרובין דמו ומביאין פר ופר לב\"ד והכי סבירא ליה לרבי שמעון דהיכא דאיכא רובא בגברי ורובא בשבטים מביאין פר לכל שבט אבל היכא דחטאו ששה והן רובן או שבעה ואינן רובן כשבט אחד דמו ומביאין פר ופר לבית דין מדקתני מה הן מביאין וכו' ולא מתוקמא רישא אלא כרבי שמעון בן אלעזר כגון שחטאו ששה וכו' וקאמר רבי שמעון שני פרים פר להו ופר לבית דין:"],[13,"","מדכתיב קהל יהודה אלמא דשבט אחד איקרי קהל:"],[14,"ודלמא שאני שבט יהודה דהוה עמיה בירושלים שבט בנימין","ושני שבטים הוא דאקרי קהל אבל שבט אחד לא:"],[14,"אלא מהכא הנני מפרך והרביתיך ונתתיך לקהל עמים וגו'","והיכא אמר ליה הכי דכתיב וירא אלהים אל יעקב עוד בבואו מפדן ארם וגו' וכתיב ויאמר לו אלהים אני אל שדי פרה ורבה גוי וקהל גוים יהיה ממך וגו':"],[14,"מאן הוה אתיליד ליה בההיא שעתא","כלומר מאן הוה עתיד למילד ההיא שעתא בנימין ושמע מינה דקאמר ליה רחמנא השתא מתיליד לך קהל אחרינא:"],[15,"י\"א שבטים לא","בתמיהה והא אמרת דשני שבטים איקרו קהל יהודה ובנימין אלא ודאי הכי קאמר ליה דהשתא מתיליד לך קהל אחרינא אלמא שבט בנימין לבדו איקרי קהל:"]],[[1,"","ה\"א עד דעבדי בית דין בהדי רובא כו'. תימה השתא אע\"פ שמיעוט נשארו מצבור לא חיישינן כ\"ש דלא ניחוש לבית דין כיון דרובא נינהו בשלמא אי הוי בעינן כולהו ניחא דליבעי בית דין בהדייהו:"],[3,"","שבעה שבטים הוא דמייתו כו'. לר' יהודה דקאמר בברייתא לעיל אפילו שני שבטים ה\"מ למיבעי אבל בב' שבטים לא אלא אמתני' מיבעי ליה דאיירי בז' שבטים:"],[6,"","כגון שחטאו ששה שבטים והן רובן כו'. תימה א\"כ מ\"ט דרבי שמעון דלא מחייב אלא פר אחד הא לא אשכחן דפליג אר' יהודה אלא דבעי נמי פר לבית דין אבל מודה מיהו לרבי יהודה דשבט אחד איקרי קהל:"],[14,"","הנני מפרך והרביתיך וגו'. תימה דשביק קרא דאמר הקב\"ה ליעקב גוי וקהל גוים יהיה ממך:"]]],[["אף חטאת לא נאכלת","כיוצא בו אמר רבי יוסי (עזרא ח, לה) הבאים מהשבי הגולה הקריבו [עלות] לאלהי ישראל פרים שנים עשר וגו' הכל עולה הכל עולה סלקא דעתך אפשר שחטאת עולה אלא הכל כעולה מה עולה לא נאכלת אף חטאת לא נאכלת דתניא רבי יהודה אומר על עבודת כוכבים הביאום ואמר רב יהודה אמר שמואל על עבודת כוכבים שעשו בימי צדקיהו","בשלמא לרבי יהודה משכחת לה להני שנים עשר חטאות כגון דחטאו שנים עשר שבטים דמייתו שנים עשר שעירים אי נמי דחטאו שבעה שבטים ושארא אינך בגרירה ולרבי שמעון נמי משכחת לה כגון דחטאו אחד עשר שבטים דמייתו אחד עשר שעירים ואידך דב\"ד אלא לרבי מאיר דאמר בית דין מביאין ולא צבור שנים עשר היכי משכחת ליה כגון דחטאו והדר חטאו והדר חטאו עד תריסר זימני","והא מייתי להו הנהו דחטאו","אמר רב פפא כי גמירי חטאת שמתו בעליה במיתה הני מילי ביחיד אבל לא בצבור לפי שאין מיתה בצבור מנא ליה לרב פפא הא אילימא מדכתי' (תהלים מה, יז) תחת אבותיך יהיו בניך אי הכי אפילו ביחיד נמי","אלא דוקיא דרב פפא משעיר דראש חדש דאמר רחמנא מייתי מתרומת הלשכה והא מייתי להו מישראל והנך דפיישי היכי מייתו אלא שמע מינה חטאת שמתו בעליה בצבור קרבה","מי דמי שעיר ר\"ח דלמא לא מייתו מצבור אבל הכא ודאי מייתו אלא טעמא דרב פפא מהכא דכתיב (דברים כא, ח) כפר לעמך ישראל אשר פדית ה' ראויה כפרה זו שתכפר על יוצאי מצרים מדכתיב אשר פדית","מי דמי התם כולהו איתינון מגו דמכפרה אחיים מכפרה נמי אמתים אלא הכא מי הוו חיים אין הכי נמי דכתיב (עזרא ג, יב) ורבים מהכהנים והלוים וראשי האבות וגו'","ודלמא מועטין הוו ולא רבים הוו הכתיב (עזרא ג, יג) (ולא הכירו בקול) [ואין העם מכירים קול] תרועת השמחה לקול בכי העם [וגו'] והקול נשמע עד למרחוק","והא מזידין הוו הוראת שעה היתה הכי נמי מסתברא דאי לא תימא הכי (עזרא ח, לה) אילים תשעים וששה כבשים שבעים ושבעה כנגד מי אלא הוראת שעה היתה הכא נמי הוראת שעה היתה","ת\"ר מת אחד מן הצבור חייבין אחד מבית דין פטורין מאן תנא אמר רב חסדא אמר רבי זירא אמר רב ירמיה אמר רב רבי מאיר היא דאמר ב\"ד מביאים ולא צבור הלכך מת אחד מן הצבור חייבין דהא קאים כוליה בית דין מת אחד מבית דין פטורין דהויא לה חטאת שמת אחד מן השותפין ומשום הכי פטורין","מתקיף לה רב יוסף ונוקמה כרבי שמעון דאמר בית דין עם הצבור מת אחד מן הצבור חייבין דאין צבור מתים מת אחד מבית דין פטורין כדאמרינן דחטאת שותפין היא","א\"ל אביי שמעינן ליה לר\"ש דאמר חטאת שותפין אינה מתה דתניא פר ושעיר של יום הכפורים שאבדו והפריש אחרים תחתיהם ימותו כולן דברי רבי יהודה ר\"א ור\"ש אומר ירעו לפי שאין חטאת צבור מתה","א\"ל רב יוסף כהנים קא אמרת שאני כהנים דאיקרו קהל דכתיב (ויקרא טז, לג) על הכהנים ועל כל עם הקהל יכפר"],[[1,"הכל עולה סלקא דעתך","והכתיב שעירי עזים לחטאת:"],[1,"אף חטאת","דהקריבו לא נאכלת לפי שהיו שעירין של צבור הנשרפין לפי שהכניסו דמן לפני ולפנים כדכתיב וכל חטאת אשר יובא מדמה אל אהל מועד לכפר בקדש כדתנן (זבחים דף מז.) פרים הנשרפין ושעירים הנשרפין דהיינו שעירי עבודת כוכבים דצבור דאמר רב יהודה על עבודת כוכבים הביאום:"],[2,"ואידך דב\"ד","ואחד שהביאו ב\"ד הרי י\"ב:"],[3,"","בין לר' יהודה בין לר' שמעון בין לרבי מאיר היכי קרבי הנהו חטאות והא מייתי הנהו דחטאו בימי צדקיהו דהוו חטאת שמתו בעליהן:"],[4,"לפי שאין מיתה בצבור","דאע\"ג דמתו צבור לא אזלא למיתה חטאת דידהו:"],[4,"אילימא מדכתיב תחת אבותיך יהיו בניך","דמשמע דבנים במקום אבות קיימי וכאבות חיים דמו והכא איכא בנים דדורו של צדקיהו:"],[4,"אי הכי אפי' ביחיד נמי","לימא חטאת שמתו בעליה דלא למיתה אזלא דלהוי הבן במקום אב:"],[5,"משעיר דר\"ח","דהוי חטאת דאמר רחמנא דניתו מתרומת הלשכה דכל קרבנות צבור מתרומת הלשכה הם באין והא דלמא מייתי להו מישראל לאחר שנתרמה תרומת הלשכה:"],[5,"והנך","ישראל דפיישו:"],[5,"היכי מייתו","שעיר דר\"ח דאתא מתרומת הלשכה והא הוי חטאת שמתו בעליה אלא ש\"מ וכו':"],[6,"מי דמי שעיר דר\"ח","דלמא מיתו מצבור דלמא לא מיתו דספק הוי ואהכי קרבה אלא הכא דורו של צדקיהו ודאי מתו:"],[6,"ראויה כפרה זו","בעגלה ערופה שתכפר על יוצאי מצרים וכיון שתכפר על יוצאי מצרים ויוצאי מצרים מתים נינהו אלמא אין מיתה בצבור וה\"ה לדורו של צדקיהו דאע\"ג דמתו מתכפרין בהנהו חטאות:"],[7,"התם","גבי עגלה ערופה כולהו איתנהו בחיים דעיקר כי אתיא עגלה ערופה אהני (דהיכי) דאיתנהו קא אתיא ומגו דמכפרה אחיים מכפרה נמי אמתים דהיינו יוצאי מצרים אבל הכא מי הוו חיים הני דורו של צדקיהו:"],[8,"ודלמא מעוטי הוו","דהאי דכתיב ורבים מהכהנים והלוים דלמא מעוטי דצבור דבית שני הוו והוה ליה חטאת שמתו רוב בעליה ולא קרבה והכא כתיב דקרבה:"],[8,"הא לא מצית אמרת דמעוטי הוו","אלא ודאי רבים הוו דכתי' ואין העם מכירים קול תרועת השמחה לקול בכי העם ואותן דבוכים מדור של בית הראשון היו ומדאין מכירין קול השמחה שמע מינה דרובא הוו אותן דבוכין והוי כחטאת שרוב בעליה קיימין ומשום הכי קרבה:"],[9,"והא מזידין הוו","דורו של צדקיה ובני קטלא נינהו ולא בני קרבן נינהו והיכי מתכפרים בהנך חטאות:"],[9,"הוראת שעה היתה","דאף על גב דהוו מזידין הוו מתכפרים:"],[10,"תנו רבנן מת אחד מן הצבור","כגון שהורו ב\"ד ועשו צבור על פיהם ולא הספיקו להביא עד שמת אחד מן הצבור חייבין וכו':"],[10,"מת אחד מן ב\"ד","והויא ליה חטאת שמת אחד מן השותפין דהויא כמתו מקצת בעליה ולא קרבה הא דאיקרי להו שותפין לא משום דחטאת של שותפין דעלמא קרבה דאין שנים מביאין קרבן אלא האי דאיקרי להו שותפין משום דלא מצי קרי להו צבור דהא לאו צבור נינהו הלכך קרי להו שותפין:"],[11,"דאין צבור מתים","דאין דין מיתה בצבור דכי גמירי חטאת שמתו בעליה למיתה אזלא ביחיד ולא בצבור:"],[12,"שמעינן ליה לר\"ש דאמר חטאת השותפין אינה מתה דתניא פר ושעיר של יום הכפורים שאבדו והפריש אחרים תחתיהם","ונתכפרו בהן ואח\"כ נמצאו האבודים כולן ימותו דברי רבי יהודה ר' אלעזר ור' שמעון אומרים ירעו והא הכא דפר של יום הכפורים דהיינו פר של אהרן הוי חטאת השותפין דכהנים מתכפרים בו וקאמר רבי שמעון ירעו דלא הוי כחטאת שכפרו בעליה בעלמא דלמיתה אזלא משום דחטאת שותפות לאו כחטאת יחיד דמיא אלא כחטאת צבור דמיא והוא הדין כי מת אחד מן השותפין דלא כחטאת שמתו בעליה דמיא אלא חטאת השותפין היא ואינה מתה והכא הוא דקאמר ירעו משום דהא כפרו בעליה אבל היכא דמת אחד מן השותפין אימא לך דסבירא ליה לרבי שמעון דקרבה דחטאת השותפין אינה מתה הלכך לא מיתוקמא כרבי שמעון:"],[12,"רבי יהודה אומר כולן ימותו","דהכי ס\"ל דאפי' חטאת צבור מתה:"],[13,"אמר ליה רב יוסף כהנים קא אמרת שאני כהנים דאיקרו קהל דכתיב על הכהנים ועל כל עם הקהל יכפר","דאתקש לקהל וכיון דאיקרו קהל משום הכי קאמר רבי שמעון דפר חטאת דידהו כחטאת שעיר דקהל דמי דאינה מתה אבל בחטאת השותפין לעולם אימא לך דס\"ל לרבי שמעון דכי מת אחד מן השותפין דלא קרבה וכי מת אחד מן בית דין פטור ואכתי נוקמה כר\"ש:"]],[[1,"","ה\"ג בת\"כ וכן היה ר\"י אומר על עבודת כוכבים הביאום ואתא לפרושי דברי ר' יוסי:"],[9,"","אילים וכבשים. צריך עיון מאי טעמא נשרפו שהרי אינן באין על עבודת כוכבים:"],[9,"","הוראת שעה היתה. הוא הדין דעל כולהו מצי לתרוצי הכי:"],[12,"","ור' שמעון אומר ירעו. אף על גב דלא דמי דהכא מתו בעליהם מכל מקום לא חזו למקרבה ומה לי פסול זה ומה לי פסול אחר ואפילו הכי שמעינן ליה דירעו:"]]],[["אלא מעתה נייתו פר בהוראה וכי תימא הכי נמי טפי להו שבטים","אלא אמר רב אחא ברבי יעקב שבטו של לוי לא איקרו קהל דכתיב (בראשית מח, ד) הנני מפרך והרביתך ונתתיך לקהל עמים וגו' כל שיש לו אחוזה איקרי קהל וכל שאין לו אחוזה לא איקרי קהל","א\"כ חסרי להו י\"ב שבטים אמר אביי (בראשית מח, ה) אפרים ומנשה כראובן ושמעון יהיו לי אמר רבא והא כתיב על שם אחיהם יקראו בנחלתם לנחלה הוקשו ולא לדבר אחר","ולא והא חלוקין בדגלים כנחלתן כך חנייתן כדי לחלק כבוד לדגלים","והא חלוקים בנשיאים ההוא לחלוק כבוד לנשיאים דתניא שלמה עשה ז' ימי חנוכה ומה ראה משה לעשות שנים עשר ימי חנוכה כדי לחלוק כבוד לנשיאים","מאי הוי עלה","ת\"ש דתניא ר\"ש אומר חמש חטאות מתות ולד חטאת ותמורת חטאת וחטאת שמתו בעליה וחטאת שנתכפרו בעליה וחטאת שעברה שנתה ואי אתה יכול לומר ולד חטאת בצבור שאין צבור מפרישין נקבה ואי אתה יכול לומר תמורת חטאת בצבור שאין תמורה בצבור ואי אתה יכול לומר חטאת שמתו בעליה בצבור שאין צבור מתים","שנתכפרו בעליה ושעברה שנתה לא שמענו יכול ימותו אמרת ילמוד סתום מן המפורש מה מצינו בולד חטאת ותמורת חטאת ושמתו בעליה ביחיד דברים אמורים ולא בצבור אף שנתכפרו בעליה ושעברה שנתה ביחיד דברים אמורים ולא בצבור","וכי דנין אפשר משאי אפש' ר\"ש בחד מקום גמיר:","\u0001הדרן עלך הורו בית דין\u0002","מתני׳ \u0001הורה\u0002 כהן משיח לעצמו שוגג ועשה שוגג מביא פר שוגג ועשה מזיד מזיד ועשה שוגג פטור שהוראת כהן משיח לעצמו כהוראת ב\"ד לצבור:","\u0001גמ׳\u0002 שוגג ועשה שוגג מביא פר פשיטא","אמר אביי הכא במאי עסקינן כגון שהורה ושכח מאיזה טעם הורה ובשעה שטעה אמר הריני עושה על דעת הוראתו דמהו דתימא כיון דאילו מתידע ליה [שמא] הדר ביה כמזיד דמי ולא לחייב קמ\"ל:","מזיד ועשה שוגג כו': מנא ה\"מ דתנו רבנן (ויקרא ד, ג) לאשמת העם הרי משיח כצבור (שיכול) והלא דין הוא"],[[0,"אלא מעתה","דכהנים איקרו קהל לייתו פר בהוראה:"],[0,"וכ\"ת הכי נמי טפי להו שבטים","לר\"ש הויין י\"ג שבטים ותנן רבי שמעון אומר י\"ג פרים פר לכל שבט ושבט ופר לב\"ד דלא הוו אלא י\"ב שבטים:"],[1,"אלא אמר רב אחא בר יעקב שבטו של לוי לא איקרי קהל","והוא הדין לכהנים דלא איקרו קהל דכהנים הויין בכלל שבט לוי (ואכתי נוקמה) כר' שמעון:"],[1,"ונתתיך לקהל עמים ונתתי את הארץ הזאת לזרעך אחריך אחוזת עולם כל שיש לו אחוזה איקרי קהל","וכהנים ולוים אין להם אחוזה:"],[2,"כראובן ושמעון יהיו לי","דבתרי שבטים חשיב להו כראובן ושמעון:"],[2,"והא כתיב על שם אחיהם יקראו בנחלתם","דלנחלה הוקשו אפרים ומנשה לשאר שבטים שיהיו נוטלים בנחלה כשאר שני שבטים ולא לדברים אחרים הוקשו אבל אין מביאין ב' פרים ואכתי חסרי להו מי\"ב שבטים אלא שמעינן מינה דלוי איקרי קהל וכהנים לא איקרי קהל ושותפין נינהו ולא מתוקמא כר\"ש דקרא הכי משמע ומולדתך:"],[3,"כנחלתם כך חנייתם","שיעקב אבינו חלק להם את הארץ וציום היאך יחנו לדגליהם וכן מצינו במדרש תנחומא דיעקב אבינו תקן להם דגלים וחלק להם הארץ וכן מצינו איש על דגלו באותות באות אשר צוה להם אביהם שלאותן רוחות שנחלקו לשאת מטתו לאותן רוחות חנו לדגליהם והיינו דאמרי' כנחלתן כך חנייתן:"],[5,"מאי הוי עלה","אי הוה דוקא הא דאביי דאמר דשמעינן ליה לר\"ש דאמר דחטאת השותפין אינה מתה או לאו דוקא:"],[6,"ת\"ש דתניא ר\"ש אומר וכו' שאין צבור מפרישין נקבה","שאין אתה מוצא קרבן צבור שהיתה באה נקבה:"],[6,"שאין תמורה בצבור","דכתיב לא יחליפנו ולא ימיר דלשון יחיד הוא ולא צבור ושותפין והכי מפרש בפ\"ק דמס' תמורה (דף יג.):"],[7,"שנתכפרו בעליה ושעברה שנתה לא שמענו","אם מתים בצבור אי לא:"],[8,"וכי דנין אפשר משאי אפשר","הא ולד חטאת ותמורת חטאת ושמתו בעליה אי אפשר בצבור וקא אמר מה מצינו:"],[8,"","הא לא קשיא דלא הוי דנין אפשר משאי אפשר משום דר\"ש בחד מקום גמיר להו דכי נצטוו ישראל על ד' חטאות בחד מקום גמיר להו הלכה למשה מסיני שיהיו נהוגות יחד במקום אחד או ביחיד או בצבור וקא דייק ר\"ש אי ס\"ד בצבור הנך כולהו מי איתנהו יחד בצבור אלא ש\"מ דביחיד אמורה ולא בצבור דכי היכי שמתו בעליה ולד חטאת ותמורת חטאת ליתנהו בצבור ה\"נ שכיפרו בעליה ושעברה שנתה ליתנהו בצבור דעל כרחין ילמוד סתום מן המפורש והכי אמרינן במס' תמורה בפ' יש בקרבנות יחיד (ד' טז:) אמר ר\"ש בן לקיש ארבע נתנו להם דמתות והחמישי' ירעה ויחד ניתנו שיהיו נוהגות במקו' א' ומספק העמידום על חמש שיהיו חמשתן מתות ואי ס\"ד דארבע ניתנו להם בצבור הנך כולהו ד' מתות מי איתנהו בצבור הא לא משכחת לה דאפשר בצבור אלא שנים ותו לא אלא על כרחך ילמוד סתום מן המפורש וקא דייקא מהא מתניתא דכי היכי דאמר ר\"ש ה' חטאות מתות ביחיד ולא בצבור דמההיא דוקיא דייק ר\"ש דיחיד ולא בשותפין דהיינו ב\"ד משום דאי אתה יכול לומר ולד חטאת בשותפין שאין השותפין מביאין נקבה דפר ושעיר הוא דמביאין ואי אתה יכול לומר תמורת חטאת בשותפות שאין תמורה בשותפין דעלמא וכ\"ש בב\"ד דה\"נ תנן במס' תמורה (דף יג.) אין השותפין עושין תמורה וילמוד סתום מן המפורש מה מצינו בולד חטאת ותמורת חטאת ביחיד דברים אמורים ולא בשותפין אף חטאת שמתו בעליה ושכפרו (על) בעליה ושעברה שנתה ביחיד ולא בשותפין דחטאת שמת אחד מן השותפין קרבה הלכך הא דקתני מת אחד מב\"ד פטור לא מתקומא אליבא דר\"ש:"],[10,"פרק שני","הורה כהן משיח"],[10,"מתני' הורה כהן משיח","הורה שוגג ועשה מזיד או שהורה מזיד ועשה שוגג פטור מקרבן שהוראת כהן משיח לעצמו כהוראת ב\"ד לצבור מה הוראת ב\"ד לצבור אין חייבין אלא על העלם דבר עם שגגת מעשה אף הוראת כהן משיח לעצמו אינו חייב אלא על העלם דבר עם שגגת מעשה כדמפרש בגמרא לאשמת העם הרי משיח כצבור וכי הורו בית דין מזידין ועשו קהל שוגגין לא הוי הוראה והוי שגגת מעשה לחודיה והוו יחידין ומייתו כל חד וחד כשבה או שעירה אבל כהן משיח כי הורה מזיד ועשה שוגג לא דיניה כיחיד ופטור לגמרי דהכי אמרינן בפרק בתרא (דף יא.) מעם הארץ פרט למשיח דאינו מביא קרבן בשגגת מעשה:"],[11,"גמ' שוגג ועשה שוגג מביא פר פשיטא","דכי הורה בשוגג ועשה שוגג דהוי שוגג מעליא ומביא פר קרבן:"],[12,"מהו דתימא כיון דאי מתידע ליה","מאיזה טעם הורה שמא היה חוזר בו מאותו טעם וכי שכח ההוא טעמא ואף על פי כן הוא עושה ותולה בהוראתו ראשונה אימא כמזיד דמי ולא מחייב קרבן קא משמע לן:"],[13,"(שיכול","לגמור מדין קל וחומר שמשיח כצבור ולא צריך למכתב לאשמת העם אע\"ג דאילו לא נאמר לאשמת העם הייתי למד מן הדין):"]],[[10,"","מזיד ועשה שוגג. תימה היכא הוי שוגג בלא הוראה אי אכיל בשתיקה ולא מיקרי הוראה הא מאחר שאינו מורה לאחרים כי אם לעצמו מה לי בשתיקה מה לי בדיבור:"],[10,"","(אין) [כהוראת] בית דין כו'. כמה עניינים שונה הכא מה שכבר שנה בפרק קמא אלא משום דאתי לפרושי רישא אמאי שוה להוראת צבור לענין שוגג ועשה כו' משום דשוו פר כהן משיח וצבור להדדי:"],[11,"","שוגג ועשה שוגג פשיטא. לעיל בפ\"ק (הוריות ד:) דקתני שוגגין ועשו שוגגין לא פריך נמי פשיטא וצריך לומר אגב דתנא הכא דהתם ליכא לשנויי כדהכא דהיכי סלקא דעתך למימר דכולהו סנהדרין שכחו מאיזה טעם הורו:"]]],[["צבור מוצא מכלל יחיד ומשיח מוצא מכלל יחיד מה צבור אין חייבין אלא על העלם דבר עם שגגת מעשה אף משיח לא יהא חייב אלא על העלם דבר עם שגגת מעשה","או כלך לדרך זו נשיא מוצא מכלל יחיד ומשיח מוצא מכלל יחיד מה נשיא מביא בשגגת מעשה בלא העלם דבר אף משיח מביא בשגגת מעשה בלא העלם דבר","נראה למי דומה צבור בפר ואין מביאין אשם תלוי ומשיח בפר ואין מביא אשם תלוי מה צבור אינו חייב אלא על העלם דבר עם שגגת מעשה אף משיח לא יהא חייב אלא על העלם דבר עם שגגת מעשה","או כלך לדרך זו נשיא מביא שעירה בעבודת כוכבים ומביא אשם ודאי ומשיח מביא שעירה בעבודת כוכבים ומביא אשם ודאי מה נשיא מביא בשגגת מעשה אף משיח מביא בשגגת מעשה","ת\"ל (ויקרא ד, ג) לאשמת העם הרי הוא משיח כצבור מה צבור אינו מביא אלא על העלם דבר עם שגגת מעשה אף משיח אינו מביא אלא על העלם דבר עם שגגת מעשה","אימא מה צבור הורה ועשו אחריו בהוראתו חייבין אף משיח כשהורה ועשו אחריו בהוראתו יהא חייב ת\"ל (ויקרא ד, ג) והקריב על חטאתו אשר חטא על מה שחטא הוא מביא ואין מביא על מה שחטאו אחרים","אמר מר משיח בפר ואין מביא אשם תלוי מנא ליה דאין מביא אשם תלוי","דכתיב (ויקרא ה, יח) וכפר עליו הכהן על שגגתו אשר שגג מי שחטאתו ושגגתו שוה יצא משיח שאין שגגתו וחטאתו שוה דכתיב לאשמת העם הרי הוא משיח כצבור","לאשמת העם ע\"כ לא קאמר ליה אלא אשם כדי נסבה:","\u0001מתני׳\u0002 הורה בפני עצמו ועשה בפני עצמו מתכפר לו בפני עצמו הורה עם הצבור ועשה עם הצבור מתכפר לו עם הצבור שאין ב\"ד חייבין עד שיורו לבטל מקצת ולקיים מקצת וכן המשיח ולא בעבודת כוכבים עד שיורו לבטל מקצת ולקיים מקצת:","\u0001גמ׳\u0002 מנהני מילי דת\"ר הורה עם הצבור ועשה עם הצבור יכול יביא פר לעצמו","ודין הוא נשיא מוצא מכלל יחיד ומשיח מוצא מכלל יחיד מה נשיא חטא בפני עצמו מביא בפני עצמו חטא עם הצבור מתכפר לו עם הצבור אף משיח חטא בפני עצמו מביא בפני עצמו חטא עם הצבור מתכפר לו עם הצבור","לא אם אמרת בנשיא שכן מתכפר לו עם הצבור ביום הכפורים תאמר במשיח שאין מתכפר לו עם הצבור ביום הכפורים","הואיל ואין מתכפר לו עם הצבור ביום הכפורים יכול יביא פר לעצמו ת\"ל על חטאתו אשר חטא הא כיצד חטא בפני עצמו מביא בפני עצמו חטא עם הצבור מתכפר לו עם הצבור","היכי דמי אילימא דהוא מופלא והם אינן מופלאין פשיטא דמתכפר לו בפני עצמו הוראה דלהון ולא כלום ובעי אתויי כשבה או שעירה כל חד וחד ואי דאינון מופלאין והוא לאו מופלא אמאי מתכפר לו בפני עצמו הא הוראה דידיה ולא כלום היא"],[[0,"צבור מוצא מכלל יחיד","דיחיד מביא כשבה או שעירה וצבור מביא פר:"],[1,"נשיא מוצא מכלל יחיד","דבכלל אם נפש אחת הוא ומוצא מכללו דיחיד מביא כשבה או שעירה ונשיא מביא שעיר:"],[1,"","מה נשיא בשגגת מעשה בלא העלם דבר וכו':"],[2,"צבור בפר ואין מביאין אשם תלוי","כלל כדאמר לקמן דכתיב ביה באשם תלוי ואם נפש כי תחטא וגו' ולא ידע ואשם וכתיב וכפר עליו הכהן על שגגתו אשר שגג והוא לא ידע מי שחטאתו ושגגתו שוה חייב בשגגת מעשה בלא העלם דבר יצא כהן משיח שחטא בהעלם דבר וכ\"ש צבור דיצא מאשם תלוי משום דהעלם דבר בהדיא כתיב בהו ואין חטאתו ושגגתו שוה דבעינן העלם דבר עם שגגת מעשה ועוד דצבור אינו בכלל נפש:"],[3,"נשיא","משיח מביאין שעירה בעבודת כוכבים דכתיב בפרשת שלח לך אנשים בעבודת כוכבים ואם נפש דאחד יחיד ואחד נשיא ואחד משיח במשמע:"],[3,"ומביא אשם ודאי","בין נשיא ובין משיח דכתיב באשם גזילות ובאשם מעילות נפש ומשיח ונשיא בכלל נפש אחת הן וצבור אין מביאין אשם ודאי דאינן בכלל נפש אחת והא דתנן אין חייבין אלא על דבר שזדונו כרת ושגגתו חטאת וכן המשיח הכי משמע דב\"ד הוא דאינן חייבין כלל עד שיורו בדבר שחייבין על זדונו כרת ושגגתו חטאת שאם הורו בשחייבין על זדונו כרת ושגגתו אשם פטורין לגמרי ועוד דבאשמות אין בהם דין שוגג דעל זדון הוא מביא אשם וכן המשיח אין מביא פר אלא בדבר שחייבין על זדונו כרת ועל שגגתו חטאת אבל במקום אשם ודאי חייב אשם לפי שהוא בכלל נפש אחת דלהכי הושוה לצבור דאין מביאין פר במקום אשם:"],[6,"ומנא ליה","דאין משיח מביא אשם תלוי:"],[7,"דכתיב","באשם תלוי וכפר הכהן על שגגתו אשר שגג מחטאתו מי שחטאתו ושגגתו שוה דאינו חייב עד דהוי הכל בשגגת מעשה דהיינו יחיד יצא משיח שחטאתו ושגגתו אין שוה דאינו חייב אלא על העלם דבר עם שגגת מעשה:"],[8,"לאשמת העם ע\"כ לא קאמר ליה","כלומר מלאשמת העם קאמר דנפקא ליה דאין חטאתו ושגגתו שוה דמשיח כצבור והא אכתי לא קמה ליה היקש דלאשמת העם דעדיין לא הועמד לאשמת העם במקומו דהא קאמר אע\"ג דאילו לא נאמר לאשמת העם יכולני ללמוד מן הדין דמשיח צריך העלם דבר עם שגגת מעשה בצבור וקאמר נראה למי דומה צבור בפר ואין מביאין אשם תלוי ומשיח בפר ואין מביא אשם תלוי בענין זה הוא דומה משיח לצבור אע\"ג דאילו לא נאמר לאשמת העם והכא קאמר דמלאשמת העם נפקא ליה דמשיח אין חטאתו ושגגתו שוה דאין מביאין אשם תלוי והלא בלא אשמת העם הוא דן ולמד:"],[8,"אלא אשם כדי נסבה","אלא עיקר הדין שהוא דן כך הוא צבור בפר ומשיח בפר מה צבור אינו חייב אלא על העלם דבר עם שגגת מעשה אף משיח לא יהא חייב אלא על העלם דבר ושגגת מעשה:"],[9,"מתני' הורה","כהן משיח בעצמו כגון דמורו בתרי איסורי ב\"ד בחלב והוא בעבודת כוכבים:"],[9,"נתכפר לו בפני עצמו","דמביא פר בפני עצמו דאי הורה הוא בפני עצמו ולא הורו ב\"ד כלל לא איצטריך למיתני דחייב להביא פר דמקרא מלא הוא אלא כי איצטריך למיתני כגון שהורו בשני איסורים:"],[9,"הורה עם הצבור","ב\"ד כגון דהורו בחדא איסור הוא בחלב והן בחלב:"],[9,"נתכפר לו עם הצבור","שהוא מתכפר בשל ב\"ד ומפני מה מתכפר בשל בית דין עם הצבור כי הורה עם הצבור לפי שבדברים הרבה שוה משיח לב\"ד שאין ב\"ד חייבין קרבן עד שיורו לבטל מקצת וכן המשיח וכו' והואיל והושוה משיח לב\"ד הלכך כי הורה עם הצבור ועשה עם הצבור מתכפר עם הצבור והא דקתני שאין ב\"ד חייבין ולא קתני שאין צבור חייבין סתמא כר\"מ דאמר לעיל בפ\"ק ב\"ד מביאין על ידיהן פר והן פטורין:"],[9,"ולא בעבודת כוכבים","אין חייבין קרבן:"],[11,"גמ' מה נשיא חטא עם הצבור מתכפר לו עם הצבור","משום דבשגגת מעשה בלבד הוא מביא שעירה והואיל וחטאתו בשגגת מעשה הוא כיחיד דעלמא הלכך כי חטא ע\"פ ב\"ד עם הצבור דהוי העלם דבר עם שגגת מעשה מתכפר עם הצבור ועוד שכן מתכפר לו עם הצבור ביוה\"כ לפיכך מתכפר לו עם הצבור אף משיח הורה בפני עצמו וכו':"],[13,"ת\"ל","דכתיב בכהן משיח על חטאתו אשר חטא דמשמע דכי חטא בפני עצמו הוא דיביא בפני עצמו הא אם חטא עם הצבור מתכפר לו עם הצבור:"],[14,"ה\"ד","דכי הורה משיח בפני עצמו דמורו בתרי איסורי דמתכפר בפני עצמו:"],[14,"","אי דהוא מופלא ב\"ד והן אינן מופלאין פשיטא דמתכפר בפני עצמו דהוראה דידהו לאו כלום היא:"],[14,"ובעי איתויי","כל חד וחד מצבור:"],[14,"כשבה או שעירה","דהא תנן לעיל בפ\"ק (הוריות דף ד':) או שלא היה שם מופלא של ב\"ד דלא הויא הוראה שאע\"פ שאינו מסנהדרין שאילו היה מסנהדרין אפי' [אם] קטן שבכולם לא היה שם לא הויא הוראה כדאמרינן מאי כל עדת דאי איתא לכולה סנהדרין הויא הוראה ואי לא לא הויא הוראה וכשגגת מעשה לחודיה דמי דמייתי כל חד וחד כשבה או שעירה ה\"נ כי הוי הוא מופלא והן אינן מופלאין כי הורה בפני עצמו הואיל והוא לא היה שם עמהן פשיטא דמתכפר בפני עצמו דהוראה דידהו לאו כלום היא:"],[14,"ואי הן מופלאין והוא אינו מופלא","כי הורה בפני עצמו אמאי מתכפר בפני עצמו:"],[14,"והא הוראה דידיה לאו כלום היא","דכיון דאינו מופלא לא ידע מאי קא מורה ולא הוה הוראה מעליא וכשגגת מעשה לחודיה דמי ואשכחן משיח בשגגת מעשה גרידתא פטור לגמרי כדאמרינן בסוף פירקא שאין חטאתו שוה ליחידים:"]],[[5,"","מה צבור הורו ועשו אחריהן בהוראתן כו'. תימה היאך שייך לדמותו לב\"ד דהכתיב לאשמת העם וטפי מסתבר לומר מה צבור אין חייבין עד שיורו הן אחרים אף משיח לא יהיה חייב כו':"],[12,"","לא אם אמרת בנשיא שכן מכפר לו ביוה\"כ. המ\"ל שכן נשיא אין מביא בהוראה אלא דאלימא פריך שמתכפר בצבור:"],[14,"","ואי דאינהו (כו') מופלאים הוראה דידיה כו'. דהא איתקש לאשמת העם ותנן לעיל כו' כדפרש\"י:"]]],[["אמר רב פפא כגון שהיו מופלין שניהן","סבר אביי למימר חטא בפני עצמו ועשה בפני עצמו היכי דמי דיתבי בשני מקומות וקא מורו בתרי איסורי אמר ליה רבא אטו שני מקומות גורמין אלא אפילו יתבי בחד מקום וכיון דקא מורו בתרי איסורי חטא בפני עצמו הוא:","פשיטא הוא בחלב והן בעבודת כוכבים חטא בפני עצמו הוא דהא חלוקין בטעמייהו וחלוקין בקרבנות דהוא בפר והן בפר ושעיר דהא קא מייתו הני שעיר והוא לא מייתי וכל שכן הוא בעבודת כוכבים והן בחלב דחלוקין בקרבנותיהן [לגמרי] דהוא שעירה ואינהו פר","אלא הוא בחלב המכסה את הקרב והן בחלב שעל הדקין מהו מי אמרינן אף על גב דקרבנן שוה כיון דמתרי קראי קאתו הא פליגין בטעמייהו או דלמא שם חלב אחד הוא","אם תמצא לומר שם חלב אחד הוא הוא בחלב והן בדם מהו מי אמרינן בטעמייהו הא פליגין או דלמא כיון דשוין בקרבן בתר קרבן אזלינן תיקו:","שאין בית דין חייבין עד שיורו לבטל מקצת ולקיים מקצת וכו': מנלן דעד שיורו לבטל מקצת ולקיים מקצת כדאמרינן באידך פירקין ונעלם דבר דבר ולא כל הגוף:","וכן המשיח: מנלן דכתי' (ויקרא ד, ג) לאשמת העם הרי משיח כצבור:","ולא בעבודת כוכבים כו': מנלן דתנו רבנן לפי שיצאה עבודת כוכבים לדון בעצמה יכול יהו חייבין על עקירת מצוה כולה","נאמר כאן מעיני ונאמר להלן מעיני מה להלן בב\"ד אף כאן נמי בב\"ד ומה להלן דבר ולא כל הגוף אף כאן נמי דבר ולא כל הגוף:","\u0001מתני׳\u0002 אין חייבין אלא על העלם דבר עם שגגת המעשה וכן המשיח ולא בעבודת כוכבים אין חייבין אלא על העלם דבר עם שגגת המעשה:","\u0001גמ׳\u0002 מנלן דתנו רבנן ישגו יכול יהו חייבין על שגגת מעשה ת\"ל ישגו ונעלם דבר אין חייבין אלא על העלם דבר עם שגגת מעשה:","וכן המשיח: מנלן דכתיב לאשמת העם הרי משיח כצבור:","ולא בעבודת כוכבים אלא על העלם דבר עם שגגת מעשה: מנלן","דת\"ר לפי שיצאה עבודת כוכבים לדון בעצמה יכול יהו חייבין על שגגת המעשה נאמר כאן מעיני ונאמר להלן מעיני מה להלן אין חייבין אלא על העלם דבר עם שגגת מעשה אף כאן אין חייבין אלא על העלם דבר עם שגגת מעשה","ואילו משיח בעבודת כוכבים לא קתני מתניתין מני רבי היא","דתניא משיח בעבודת כוכבים רבי אומר בשגגת מעשה וחכמים אומרים בהעלם דבר ושוין שבשעירה ושוין שאין מביא אשם תלוי","ותסברא בזדונו כרת ובשגגתו חטאת מי קתני","אלא תני הא הוא הדין להא ה\"נ תנא הא והוא הדין להא","מ\"ט דרבי אמר קרא וכפר הכהן על הנפש השוגגת בחטאה בשגגה הנפש זה משיח השוגגת זה נשיא בחטאה בשגגה רבי סבר חטא זה בשגגה יהא","ורבנן סברי מי שחטאתו בשגגה יצא משיח שאין חטאתו בשגגה אלא בהעלם דבר","ושוין שבשעירה כיחיד מנלן דאמר קרא ואם נפש אחת אחד יחיד ואחד נשיא ואחד משיח כולם בכלל נפש אחת הן:"],[[0,"אמר רב פפא","בשוין דהוא מופלא והן מופלאים הלכך איצטריך למיתני דכי חטא בפני עצמו אע\"ג דהוראה דידהו הוי הוראה מעליא אפילו הכי מתכפר בפני עצמו משום דקא מורו בשני איסורי חטא עם הצבור אע\"ג דהוא מופלא דהוראה דידיה הוי הוראה מעליא אפ\"ה מתכפר עם הצבור משום דקא מורו בחדא איסורא:"],[1,"בשני מקומות","משיח במקום אחד וב\"ד במקום אחר:"],[2,"בטעמייהו","בפסוקים דחלב ועבודת כוכבים מתרי קראי נפקי:"],[2,"וחלוקין בקרבנות","דב\"ד מייתי שעיר אעבודת כוכבים והוא לא מייתי שעיר:"],[2,"דהוא שעירה","לחודיה דכתיב בעבודת כוכבים בפרשת שלח לך אנשים ואם נפש דאחד יחיד ואחד נשיא במשמע:"],[3,"הוא בחלב המכסה את הקרב","דהוי דבר שאין הצדוקים מודין דהא לא מפרש קרא מאי ניהו דאפי' אמוראי פליגי בשחיטת חולין באלו טריפות (חולין דף נ:) מאי ניהו כרס הפנימי וכ\"ש חלב שעל גבי הדקים שאין הצדוקים מודין דהא לא כתיב בהדיא אי נמי דהורו בחלב שעל הקרב בין בכזית לפחות מכזית דכזית לא כתיב בהדיא והוי דבר שאין הצדוקין מודין:"],[3,"אע\"ג דקרבנן שוה","דהן בפר והוא בפר:"],[3,"כיון דמתרי קראי קא אתו","כדאמרינן לעיל בפרק קמא (הוריות דף ג.) ואת החלב וי\"ו יתירא להביא חלב שעל גבי הדקין:"],[3,"הא פליגין בטעמייהו","הא חלוקים בפסוקים ומתכפר בפני עצמו:"],[3,"או דלמא שם חלב אחד הוא","והורה עם הצבור הוא ומתכפר עם הצבור:"],[4,"והן בדם","כגון בדם המובלע באיברים או בין כזית לפחות מכזית והוי דבר שאין הצדוקין מודין:"],[4,"בתר קרבן אזלינן","דכיון דשוין בקרבן הורה עם הצבור הוא ומתכפר עם הצבור תיקו:"],[7,"לפי שיצאה עבודת כוכבים","מכלל פר העלם דבר של צבור לידון בעצמו בהבאת פר ושעיר:"],[8,"נאמר כאן","בעבודת כוכבים מעיני והיה אם מעיני העדה:"],[8,"ונאמר להלן מעיני","ונעלם דבר מעיני הקהל:"],[8,"מה להלן ב\"ד","דכתיב ונעלם דבר מעיני הקהל ועשו ואמרינן לעיל בפ\"ק (הוריות דף ה.) הוראה תלויה בב\"ד דכתיב ונעלם דבר מעיני הקהל דהיינו ב\"ד ומעשה תלוי בקהל דכתיב הקהל ועשו ובעבודת כוכבים לא כתיב ב\"ד דכתיב והיה אם מעיני העדה נעשתה לשגגה ואי ס\"ד ב\"ד והא אין מעשה תלוי בב\"ד אלא בקהל דהכא כתיב מעיני העדה נעשתה דהיינו מעשה אלא מה להלן ב\"ד דכתיב בפרשת ויקרא אף כאן בית דין:"],[9,"מתני' אין חייבין בקרבן וכו'","אין ב\"ד חייבין קרבן אלא על העלם דבר עם שגגת מעשה וכן המשיח וצבור הוא דכי עבדי בשגגת מעשה לחודיה מייתו כל חד וחד כשבה או שעירה דדיניהם כיחידים דכיון דלא עשו ע\"פ ב\"ד מחלקי כולהו מהדדי והוו יחידים ויחידים חייבין בשגגת מעשה אבל משיח בשגגת מעשה לחודיה פטור מכלום כדאמר לקמן בפרק בתרא (הוריות דף יא.) מעם הארץ פרט למשיח דאינו מביא בשגגת מעשה כלל והיינו דקאמר יצא משיח שאין חטאתו בשגגה דהיינו בשגגת מעשה וכו':"],[14,"גמ' ואילו משיח בעבודת כוכבים לא קתני","דקתני ולא בעבודת כוכבים אין חייבים אלא על העלם דבר עם שגגת מעשה ולא קתני וכן המשיח ומדלא קתני וכן המשיח מכלל דמשיח בעבודת כוכבים חייב בשגגת מעשה לחודיה:"],[14,"מתני' מני ר' היא דתניא משיח בעבודת כוכבים ר' אומר בשגגת מעשה","לחודיה:"],[15,"וחכ\"א בהעלם דבר","כלומר עם שגגת מעשה כשאר מצות ושוין שאין מביא שום אשם תלוי:"],[16,"ותסברא זדונו כרת ושגגתו חטאת","דעבוד' כוכבי' דקתני ולא בעבוד' כוכבים אלא על דבר שחייבין על זדונו כרת ועל שגגתו חטאת מי קתני וכן המשיח והא קי\"ל דמשיח נמי בעבודת כוכבים אינו חייב אלא על דבר שזדונו כרת ועל שגגתו חטאת כדאמרי' לקמן נאמר כאן עליה כו' לאשמת העם הרי משיח כצבור ואפי' הכי לא קתני במתני' וכן המשיח:"],[17,"אלא תנא בהא","בדבר שחייבין על זדונו כרת ושגגתו חטאת כשאר מצות וכן המשיח והוא הדין בעבודת כוכבים דמשיח כצבור דאינו חייב בעבודת כוכבים אלא בדבר שזדונו כרת ושגגתו חטאת:"],[17,"הכא נמי תנא בהא","דאין חייבין בשאר מצות אלא על העלם דבר עם שגגת מעשה וכן המשיח והוא הדין לעבודת כוכבים דמשיח כצבור כי היכי דאין ב\"ד חייבין על עבודת כוכבים אלא על העלם דבר עם שגגת מעשה ודלא כרבי:"],[18,"מאי טעמא דרבי אמר קרא","בפרשת שלח לך וכפר הכהן על הנפש השוגגת וגו' סבר רבי חטאה בשגגה הכי משמע חטא זה בשגגה יהא כלומר בשגגת מעשה לחודיה ואפילו משיח:"],[19,"ורבנן סברי מי שחטאו בשגגה","דהכי משמע וכפר הכהן על הנפש השוגגת דיביא שעירה בשגגת מעשה מי שחטאו בשגגה בשאר מצות:"],[19,"יצא משיח שאין חטאתו בשגגה","בשאר מצות כלומר בשגגת מעשה אלא בהעלם דבר עם שגגת מעשה דעל שגגת מעשה לחודיה פטור לגמרי:"]],[[1,"","דיתבי בתרי מקומות וקמורו בחד איסורא. תימה מאי אצטריך בשוין אפי' לא שוו נמי הוראתן הוראה דהא דבעינן לעיל מופלא בב\"ד שהיה להן ללמוד ולא למדו והכא מאי אצטרכין ללמוד כיון דבאיסור אחד הורו ושניהן הורו שוה ונראה כספרים דגרסי מלתא דרב טפי בשוין בתר דמוקי בתרי אסורי:"],[8,"","נאמר כאן מעיני. תימה דלעיל בפ\"ק משמע בדברי אביי דלא ידעינן שאר מצות אלא מעבודת כוכבים והכא משמע איפכא וי\"ל דאביי נמי הכי בעי למילף כי הכא דעיני דעבודת כוכבים לא פשוט לן שהוא ב\"ד אלא ה\"ק ילפינן עיני עיני כלומר האי עיני דעבודת כוכבים ילפינן משאר מצות שהוא ב\"ד והדר ילפינן ההוא מעיני מהאי לענין זה דכי היכי דגבי עבודת כוכבים מעשה תלוי בקהל כדמשמע נעשתה ה\"נ האי עיני דשאר מצות:"],[10,"","דת\"ר ישגו יכול יהיו חייבין על שגגת מעשה. תימה למאי איצטריך הא כבר ילפינן מדבר דבר דמקצת דבר בעינן והא לא שייך כי אם בהוראה ועוד איך יהיו חייבין על שגגת מעשה למ\"ד ב\"ד מביאין פר טוביה חטא וזיגוד מינגד מה חטאו ב\"ד ועוד תניא פ\"ק עם הארץ לרבות אפי' רובו ואפי' כולו דמייתו שעירה או כשבה ולא פר. וי\"ל דאי לאו דמשמע דבעינן העלם דבר לא היינו אומרים שב\"ד יהיו חייבין אלא צבור דאע\"ג דלעיל דרשינן דמעשה תלוי בקהל והוראה תלויה בב\"ד השתא מיהו לא דרשינן הכי מיהו הקישא דדבר צ\"ל דמתחלה צריך למילף הוא ואח\"כ לומר דבר ולא כל הגוף:"]]],[["ושוין שאין מביא אשם תלוי מנלן דכתיב (ויקרא ה, יח) וכפר [עליו] הכהן על שגגתו אשר שגג רבי סבר מי שכל חטאו בשגגה יצא זה שאין [כל] חטאו בשגגה אלא בהעלם דבר","מידי כל כתיב אין דאם כן נכתוב על שגגתו למה לי אשר שגג הא קמ\"ל דעד דאיכא כל חטאו בשגגה (יצא משיח שאין כל חטאו בשגגה אלא בעבודת כוכבים ולא בשאר מצות אלא בהעלם דבר עם שגגת מעשה)","ורבנן מי שחטאו בשגגה יצא משיח שאין חטאו בשגגה לא בעבודת כוכבים ולא בשאר מצות אלא בהעלם דבר עם שגגת מעשה:","\u0001מתני׳\u0002 אין בית דין חייבין עד שיורו בדבר שזדונו כרת ושגגתו חטאת וכן המשיח ולא בעבודת כוכבים עד שיורו על דבר שזדונו כרת ושגגתו חטאת:","\u0001גמ׳\u0002 מנלן","דתניא רבי אומר נאמר כאן (ויקרא ד, יד) עליה ונאמר להלן (ויקרא יח, יח) עליה מה להלן דבר שזדונו כרת ושגגתו חטאת אף כאן דבר שזדונו כרת ושגגתו חטאת","אשכחן צבור משיח מנלן לאשמת העם הרי משיח כצבור","נשיא יליף מצות מצות כתיב גבי נשיא (ויקרא ד, כב) ועשה אחת מכל מצות ה' וכתיב בצבור (ויקרא ד, יג) ועשו אחת מכל מצות מה צבור דבר שזדונו כרת ושגגתו חטאת אף נשיא דבר שזדונו כרת ושגגתו חטאת","יחיד אמר קרא (ויקרא ד, כז) ואם נפש וילמד תחתון מעליון:","ולא בעבודת כוכבים עד שיורו: בעבודת כוכבים מנלן דת\"ר לפי שיצאה עבודת כוכבים לדון בעצמה יכול יהו חייבין אפילו על דבר שאין זדונו כרת ושגגתו חטאת","נאמר כאן מעיני ונאמר להלן מעיני מה להלן דבר שזדונו כרת ושגגתו חטאת אף כאן דבר שזדונו כרת ושגגתו חטאת","אשכחן צבור יחיד נשיא משיח מנלן אמר קרא (ויקרא ד, כז) ואם נפש אחת אחד יחיד ואחד נשיא ואחד משיח כולן בכלל נפש אחת הן וילמד תחתון מן העליון","הניחא למאן דמפיק לה לעליה לג\"ש כדאמרן אלא לרבנן דמפקי לה לעליה לעריות וצרות דבר שזדונו כרת ושגגתו חטאת מנא להו","נפקא להו מדמתני ליה ר' יהושע בן לוי לבריה (במדבר טו, כט) תורה אחת יהיה לכם לעושה בשגגה והנפש אשר תעשה ביד רמה וגו' הוקשה כל התורה כולה לעבודת כוכבים מה עבודת כוכבים שחייבין על זדונו כרת ועל שגגתו חטאת אף כאן שחייבין על זדונו כרת ועל שגגתו חטאת","אשכחן יחיד נשיא ומשיח בין בעבודת כוכבים בין בשאר מצות צבור מנלן יליף עליון מתחתון","ורבי הא דר' יהושע בן לוי מאי עביד ליה מפיק ליה לכדתניא לפי שמצינו שחלק הכתוב בין רבים ליחידים רבים בסייף וממונן אבד יחידים בסקילה וממונן פלט יכול נחלוק בקרבנותיהם ת\"ל תורה אחת יהיה וגו'","מתקיף לה רב חלקיה מהגרוניא טעמא דלא חלק הכתוב הא חלק הוה אמינא נחלוק מאי נייתי","נייתי פר צבור בשאר מצות הוא דמייתו נייתי פר לעולה ושעיר לחטאת צבור בעבודת כוכבים הוא דמייתו נייתי שעיר נשיא בשאר מצות הוא דמייתי נייתי שעירה יחיד נמי היינו קרבנו","אלמה לא איצטריך ס\"ד אמינא צבור מייתי פר לעולה ושעיר לחטאת הני נייתי איפכא פר לחטאת ושעיר לעולה א\"נ צריך ואין לו תקנה קמ\"ל","דכ\"ע מיהת כי כתיבי הני קראי בעבודת כוכבים הוא דכתיבי מאי משמע אמר רבא ואי תימא ר' יהושע בן לוי ואמרי לה כדי אמר קרא (במדבר טו, כב) וכי תשגו ולא תעשו את כל המצות האלה איזו היא מצוה שהיא שקולה ככל המצות הוי אומר זו עבודת כוכבים","דבי רבי תנא אמר קרא (במדבר טו, כב) אשר דבר ה' אל משה וכתיב (במדבר טו, כג) אשר צוה ה' אליכם ביד משה איזו היא מצוה שהיא בדיבורו של הקב\"ה וצוה על ידי משה הוי אומר זו עבודת כוכבים דתנא רבי ישמעאל (שמות כ, ב) אנכי (שמות כ, ב) ולא יהיה לך מפי הגבורה שמענום","דבי רבי ישמעאל תנא"],[[0,"ושוין שאין","משיח מביא אשם תלוי דכתיב באשם תלוי וכפר הכהן על שגגתו אשר שגג והוא לא ידע מי שחטאו בשגגה יצא משיח ולרבי היכי מצי אמר יצא משיח והא לרבי חטאו בעבודת כוכבים בשגגה הוא דהא תניא לעיל משיח בעבודת כוכבים רבי אומר בשגגת מעשה אלא רבי סבר דהכי מתרץ קרא לטעמיה מי שכל חטאו בשגגה יצא משיח שאין כל חטאו בשגגה דבעבודת כוכבים בלבד הוא דחטאו בשגגה אבל בשאר מצות אין חטאו בשגגה בלבד אלא בהעלם דבר עם שגגת מעשה:"],[2,"ורבנן","סברי יצא משיח שאין חטאו בשגגה לא בעבודת כוכבים ולא בשאר מצות אלא העלם דבר עם שגגת מעשה ולדברי הכל משיח אין מביא אשם תלוי וכ\"ש צבור דאין חייבין אשם תלוי דהעלם דבר כתיב בהו בהדיא:"],[3,"מתני' אין ב\"ד חייבין","קרבן אלא על דבר שזדונו כרת ושגגתו חטאת ואם הורו בדבר שחייבין אשם ודאי פטורין דכתיב באשם ודאי ואם נפש אחת וב\"ד אין הם בכלל נפש אחת ועוד דבאשמות אין בהן דין העלם דבר דחייבין אשם ודאי על המזיד כשוגג:"],[3,"וכן המשיח","אין מביא פר אלא על העלם דבר שזדונו כרת ושגגתו חטאת אבל במקום אשם ודאי חייב להביא אשם ודאי לפי שהוא בכלל נפש אחת ולהכי השוה לצבור דאין מביא פר במקום אשם אבל אשם יביא כדתנן לקמן (הוריות ד' ט.) אשם ודאי הנשיא המשיח והיחיד חייבין וב\"ד פטורין:"],[5,"גמ' נאמר כאן עליה","ונודעה החטאת אשר חטאו עליה (ויקרא ד׳:י״ד):"],[5,"ונאמר להלן","לגלות ערותה עליה (שם יח):"],[7,"נשיא","נמי לא יביא שעיר אלא על דבר שזדונו כרת ושגגתו חטאת כדתנן (שם) כל מצות שבתורה שחייבין על זדונן כרת ועל שגגתן חטאת יחיד מביא כשבה או שעירה ונשיא מביא שעיר דיליף מצות מצות:"],[8,"יחיד","נמי אינו מביא חטאת אלא על דבר שזדונו כרת דתנן כל מצות שבתורה וכו':"],[8,"אמר קרא","בפרשת ויקרא אם נפש:"],[8,"וילמוד תחתון מעליון","יחיד מנשיא:"],[9,"לפי שיצאה עבודת כוכבים","דהכא כתיב וכי תשגו ולא תעשו ולא כתיב הכא כרת:"],[9,"יכול יהו חייבין על דבר שאין זדונו כרת","כגון מגפף ומנשק ומרבץ כדאמרינן במסכת סנהדרין בפרק ד' מיתות (סנהדרין דף ס:) בלא תעשה ואינו בכרת:"],[11,"וילמוד תחתון מעליון","יחיד נשיא ומשיח מצבור:"],[12,"אלא לרבנן","דמפקי להאי עליה לדרשא אחרינא כדאמרינן בפ\"ק דיבמות (דף ג:) ואשה אל אחותה וגו' עליה מה ת\"ל לפי שנאמר יבמה יבא עליה וגו':"],[13,"תורה אחת יהיה לכם לעושה בשגגה והנפש אשר תעשה ביד רמה","בעבודת כוכבים משתעי קרא דתניא בסיפרי ר\"ש אומר בעבודת כוכבים הכתוב מדבר שנא' כי דבר ה' בזה שבזה על דיבור ראשון שנאמר בו אנכי ה' אלהיך ולא יהיה לך אלהים אחרים על פני:"],[13,"מה עבודת כוכבים שחייבין על זדונו כרת","דהכא כתיב הכרת תכרת אף כו':"],[14,"אשכחן יחיד ונשיא ומשיח בין בעבודת כוכבים ובין בשאר מצות","דכתיב ואם נפש וכתיב תורה אחת יהיה לכם והנפש אשר תעשה ביד רמה דיחיד ונשיא ומשיח בכלל ואם נפש אחת:"],[14,"צבור מנלן ילמוד עליון מן התחתון","דכתיב בפרשה למעלה וכי תשגו דהיינו צבור וילמד מתחתון מואם נפש מה להלן דבר שחייבין על זדונו כרת ועל שגגתו חטאת בין בעבודת כוכבים בין בשאר מצות דגבי יחיד הוקשה כל התורה כולה לעבודת כוכבים אף צבור אין חייבין אלא בדבר שחייבין על זדונו כרת ועל שגגתו חטאת בין בעבודת כוכבים בין בשאר מצות:"],[15,"רבים בסייף","במזיד אנשי עיר הנדחת:"],[15,"יכול נחלוק בשוגג בקרבנותיהם","דכי היכי דחלוק צבור מיחידים דקרבן צבור בעבודת כוכבים לא דמי לשום קרבן יחיד ה\"נ נחלוק בקרבנותיהם דלהוי חלוק דמרובין שעשו שוגגין דעיר הנדחת דלא להוי דמי לעולם לשום קרבן לא לצבור ולא ליחיד:"],[15,"ת\"ל תורה אחת","דעיר הנדחת דשוגג כיחידים דמו ומייתי כל חד וחד שעירה כיחיד:"],[16,"מאי נייתי","אנשי עיר הנדחת רבים דבסייף:"],[17,"נייתי פר צבור בשאר מצות הוא דמייתי","ולא הוי חלוק וכ\"ש דבעי' חלוק בין אנשי עיר הנדחת לצבור דהא אין צבור נעשין עיר הנדחת כלל:"],[17,"יחיד נמי היינו קרבנו","ולא הוי חלוק:"],[18,"איצטריך","תורה אחת דס\"ד וכו':"],[18,"אי נמי צריך","לחלוק בקרבן:"],[18,"ואין לו תקנה","לעיר הנדחת בשוגג דאי אפשר לחלוק:"],[18,"קמ\"ל","תורה אחת דמייתי כל חד שעירה כיחיד:"],[19,"ולא תעשו את כל המצות איזו היא מצוה ששקולה כנגד כל המצות הוי אומר זו עבודת כוכבים","שכל המודה בה ככופר בכל התורה כולה:"],[20,"כתיב כל אשר צוה ה' אליכם ביד משה","דמשמע שצוה ע\"י משה וכתיב אשר דבר ה' דמשמע שהיא בדיבורו של הקב\"ה כלומר ששמעו ישראל מפיו כשדבר עם משה:"],[20,"איזו היא מצוה שהיא בדבורו של הקב\"ה וצוה ע\"י משה הוי אומר זו עבודת כוכבים","דאנכי ולא יהיה לך מפי הגבורה שמענום דהיינו ששמעו בדבורו של הקב\"ה וצוה ע\"י משה בכמה פרשיות שבתורה כגון לא תשתחוה לאל אחר דלא שמענו אלא מפי משה:"]],[[3,"","אין חייבין אלא על דבר שזדונו כרת ושגגתו חטאת. תימה אמאי קאמר על שגגתו חטאת הא היא גופה חטאת היא ומה שייך לומר אין חייבין חטאת אלא על דבר ששגגתו חטאת ושמא אגב דוכתא אחריתי דנקיט לה גבי מלקות נקיט נמי הכא עי\"ל דה\"פ דמה שאדם אחר היה מחויב חטאת על שגגתו הכא מביאין פר:"],[8,"","ויחיד דאמר קרא ואם נפש. ה\"נ ה\"מ למילף גבי יחיד מצות מצות דה\"נ כתיב ואם נפש אחת תחטא ועשתה אחת מכל מצות ה' אלא דהכי ניחא ליה למילף:"],[11,"","ילמוד תחתון מעליון. וא\"ת היכי יליף יחיד מנשיא והא נשיא גמיר מג\"ש ואינו חוזר ומלמד בהיקש [כדאיתא בזבחים נ:] ויש לומר דגילוי מילתא בעלמא הוא ולא היקש דתרוייהו בכלל יחיד ובכלל נפש מיהו לעיל קשה דיליף עבודת כוכבים משאר מצות ושאר מצות מזקן ממרא והלא הלמד מגזירה שוה אין חוזר ומלמד בגזירה שוה [עי' זבחים ניפשט הש\"ס דדבר הלמד בגזירה שוה חוזר ומלמד בגזירה שוה ואין חולק על זה וצריך עיון גדול] ויש לומר דבתר מלמד [אזלינן] והמלמד (תולין) [חולין]:"],[19,"","שהיא שקולה כנגד כל המצות. דכיון דמודה בה מה צורך לו לקיים כל המצות ומסתמא יעבור על כולן ובספרי מפיק לה מאת בריתי היפר משמע שכל הברית מיפר:"]]],[["(במדבר טו, כג) למן היום אשר צוה ה' והלאה לדורותיכם איזו היא מצוה שהיא נאמרה בתחלה הוי אומר זו עבודת כוכבים והא אמר מר עשר מצות נצטוו ישראל במרה (דכתי' (שמות טו, כו) והיה אם שמוע תשמע לקול ה' אלהיך) אלא מחוורתא כדשנינן מעיקרא:","\u0001מתני׳\u0002 אין חייבין על עשה ועל לא תעשה שבמקדש ואין מביאין אשם תלוי על עשה ועל לא תעשה שבמקדש","אבל חייבין על עשה ועל לא תעשה שבנדה ומביאים אשם תלוי על עשה ועל לא תעשה שבנדה איזו היא מצות עשה שבנדה פרוש מן הנדה ומצות לא תעשה אל תבא על הנדה:","\u0001גמ׳\u0002 מנא הני מילי דצבור לא מחייבי קרבן בעלמא ויחיד אשם תלוי נמי לא","אמר רב יצחק בר אבדימי נאמר ואשם בחטאת ובאשם תלוי ונאמר ואשמו בצבור מה ואשם ביחיד בחטאת קבועה אף ואשמו בצבור בחטאת קבועה","ומה צבור בחטאת קבועה אף אשם תלוי נמי אין בא אלא על ספק חטאת קבועה אמרי אי הכי קרבן עולה ויורד נמי הא כתיב (ויקרא ה, ה) והיה כי יאשם לאחת מאלה דנין (אשם מן אשמו) [אשם מן אשם] ואין דנין אשם מן יאשם","ומאי נ\"מ והא תני דבי רבי ישמעאל (ויקרא יד, לט) ושב הכהן ובא הכהן זו היא שיבה זו היא ביאה ועוד נילף מן ואשם מטומאת מקדש וקדשיו דכתיב (ויקרא ה, ב) והוא טמא ואשם","אמר רב פפא דנין ואשם ומצות ה' מן ואשם ומצות ה' א\"ל רב שימי בר אשי לרב פפא ונילף ואשם ונשיאת עון מן ואשם ונשיא' עון","אלא אמר ר\"נ בר יצחק דנין ואשם ומצות ה' אשר לא תעשינה מואשם ומצות ה' אשר לא תעשינה ואל יוכיח שמיעת קול וביטוי שפתים וטומאת מקדש וקדשיו שלא נאמר בהם ואשם ומצות ה' אשר לא תעשינה:","\u0001מתני׳\u0002 אין חייבין על שמיעת קול ועל ביטוי שפתים ועל טומאת מקדש וקדשיו והנשיא כיוצא בהם דברי רבי יוסי הגלילי ר\"ע אומר הנשיא חייב בכולן חוץ משמיעת הקול שהמלך לא דן ולא דנין אותו [לא מעיד ולא מעידין אותו]:","\u0001גמ׳\u0002 אמר עולא מ\"ט דר' יוסי הגלילי אמר קרא והיה כי יאשם לאחת מאלה כל שמתחייב באחת מתחייב בכולן ושאין מתחייב באחת אין מתחיי' בכולן","ואימא מתחיי' באחת מהן ואע\"פ שאין מתחיי' בכולן","אלא טעמא דר' יוסי הגלילי מהכא דתניא היה רבי ירמיה אומר נאמר"],[[0,"למן היום וגו'","הכי משמע את כל אשר צוה ה' אליכם ביד משה דזו עבודת כוכבים ומנין שזו עבודת כוכבים מדכתיב בהדי' למן היום אשר צוה ה' והלאה שאר מצות והלאה כלומר מכאן ואילך לדורותיכם איזו היא מצוה שנאמרה בתחילה הוי אומר זו עבודת כוכבים דכתיב בתחילת עשרת הדברות אנכי ולא יהיה לך דהיינו עבודת כוכבים:"],[0,"י' מצות נצטוו במרה","דהיינו קודם מתן תורה אלמא עבודת כוכבים לא נאמרה תחלה:"],[0,"מחוורתא כדשנינן מעיקרא","כדברי ר' יהושע בן לוי או כדברי רבי:"],[1,"מתני' אין ב\"ד חייבין קרבן על עשה ועל לא תעשה שבמקדש","דהיינו טומאת מקדש וקדשיו עשה שבמקדש וישלחו מן המחנה כל צרוע לא תעשה ולא יטמאו את מחניהם שאע\"פ שהוא דבר שזדונו כרת ושגגתו חטאת הואיל ואין שגגתו חטאת קבועה אלא קרבן חטאת עולה ויורד הלכך פטור לגמרי כדמפרש בגמרא והאי דקתני אין חייבין על עשה ועל לא תעשה שבמקדש לא קא מיירי בכהן משיח כלל משום דהוי פלוגתא דר\"ש ור\"ע ר\"ע לא פטר ליה מפר על טומאת מקדש וקדשיו ור\"ש פטר ליה לגמרי כדמפרש בגמרא בסוף פירקין:"],[1,"ואין מביאין","יחידין:"],[1,"אשם תלוי על עשה ועל לא תעשה שבמקדש","דאין אשם תלוי בא אלא על ספק חטאת קבועה כדמפרש בגמ' אבל בב\"ד לא איצטריך למיתנא אין מביאין אשם תלוי על עשה ועל לא תעשה שבמקדש שהרי אין ב\"ד מביאין אשם תלוי אפי' במקום ספק חטאת קבועה כדאמרי' בריש פירקין משוח בפר ואין מביא אשם תלוי דכתיב באשם תלוי וכפר עליו הכהן על שגגתו אשר שגג מי שחטאתו ושגגתו שוה יצא משיח ומנלן דאין חטאתו ושגגתו שוה דכתיב לאשמת העם הרי משיח כצבור דצבור צריכין העלם דבר עם שגגת מעשה לפיכך אינו באשם תלוי הלכך כי איצטריך אין מביא אשם תלוי על עשה ועל לא תעשה שבמקדש כגון ביחיד דעלמא:"],[2,"אבל חייבין","ב\"ד על עשה ועל לא תעשה שבנדה דהוי זדונו כרת ושגגתו חטאת קבועה ומביאין יחידים אשם תלוי על עשה ועל לא תעשה שבנדה משום דהוי ספק חטאת קבועה:"],[2,"פרוש מן הנדה","כלומר בסמוך לוסתה כדי שלא תהא רואה בשעת תשמיש דכתיב והזרתם את בני ישראל כדמפרש בגמרא במסכת שבועות בפרק ידיעות הטומאה (שבועות דף יח:):"],[2,"אל תבא על הנדה","דכתיב (ויקרא יח) ואל אשה בנדת טומאתה לא תקרב:"],[3,"גמ' מנא הני מילי","דצבור לא מחייבי שום קרבן בעולם אלא במקום חטאת קבועה:"],[3,"ויחיד אשם תלוי נמי","אין חייבין אלא על ספק חטאת קבועה:"],[4,"אמר רב יצחק בר אבדימי נאמר כאן ואשם","בחטאת קבועה דיחיד דכתיב בפ' ויקרא ואם נפש אחת תחטא בשגגה מעם הארץ בעשותה אחת ממצות ה' אשר לא תעשינה ואשם וכתיב והביא את קרבנו דמביא כשבה או שעירה דאינו בעולה ויורד:"],[4,"ונאמר ואשמו בצבור מה ואשם","האמור בפרשת ויקרא בחטאת יחיד הוי חטאת קבועה אף ואשמו האמור בצבור אין מביאין שום קרבן אלא במקום חטאת קבועה דאילו עשאו יחיד הוי בעולה ויורד ונאמר ואשם (בא) באשם תלוי דכתיב באשם תלוי ואם נפש כי תחטא ועשתה אחת מכל מצות ה' אשר לא תעשינה ולא ידע ואשם מה צבור חטאת בקבועה כלומר מה ואשמו האמור בצבור חטאתו בקבועה דגמרי מואשם דחטאת יחיד:"],[5,"אף","ואשם האמור באשם תלוי אינו בא אלא על ספק חטאת קבועה לאפוקי עשה ולא תעשה שבמקדש דאין אשם תלוי בא עליו משום דהוי חטאת עולה ויורד ולא הוי חטאת קבועה (ועוד דאין אשם תלוי בא עליו) ותרתי מפקינן מדר' יצחק בר אבדימי חדא דצבור בחטאת קבועה דאין ב\"ד חייבין על עשה ועל לא תעשה שבמקדש ואידך דאין אשם תלוי בא עליו אלא על ספק חטאת קבועה דאשם תלוי אפי' דיחיד אינו בא על עשה ועל לא תעשה שבמקדש שהרי אינו ספק חטאת קבועה:"],[5,"אי הכי קרבן עולה ויורד נמי הא כתיב כי יאשם","דכתיב נפש כי תחטא בשגגה ושמעה קול אלה דהיינו שמיעת הקול [וכתיב או נפש אשר תגע וגו' דהיינו טומאת מקדש וקדשיו וכתיב] או נפש כי תשבע לבטא בשפתים וגו' דהיינו בטוי שפתים דכולהו בקרבן עולה ויורד וכתיב והיה כי יאשם לאחת מאלה מה כי יאשם בעולה ויורד אף ואשם דכתיב באשם תלוי תהוי במקום עולה ויורד דלהוי אשם תלוי בא ואפי' על ספק חטאת שאינה קבועה:"],[6,"זו היא שיבה זו היא ביאה","דהא דכתיב ושב הכהן לא תימא ושב הכהן מבית המנוגע לביתו אלא הכי הוא ושב הכהן מביתו לבית המנוגע דהאי שיבה זו היא ביאה לבית המנוגע:"],[6,"נילף ואשם מטומאת מקדש וקדשיו","דכתיב בו או נפש אשר תגע וגו' והוא טמא ואשם דהיינו טומאת מקדש וקדשיו דהוא בקרבן עולה ויורד דחטאת שאינה קבועה הוא:"],[7,"דנין ואשם ומצות ה'","דכתיב באשם תלוי מואשמו ומצות ה' לאפוקי טומאת מקדש וקדשיו דלא כתב ואשם ומצות ה':"],[7,"נילף ואשם ונשיאת עון","דכתיב באשם תלוי ולא ידע ואשם ונשא עונו וכתיב בעולה ויורד אם לא יגיד ונשא עונו והוא ידע ואשם לאחת מאלה:"],[8,"","באשם תלוי כתיב ואשם ומצות ה' אשר לא תעשינה ובפר ובהעלם דבר של צבור כתי' אחת מכל מצות ה' אשר לא תעשינה ואשם הלכך אמרי' מה צבור חטא' בקבוע' אף אשם תלוי אינו בא אלא על ספק חטאת קבועה:"],[9,"","מתני' אין ב\"ד חייבין על שמיעת קול ועל בטוי שפתים ועל טומאת מקדש וקדשיו. דכל הני הויין בקרבן עולה ויורד כדאמרינן לעיל דצבור אין מביאין חטאת אלא בקבוע' ובדין הוא דלא איבעי למיתנא דהא תנא לעיל אין חייבין על עשה ועל לא תעשה שבמקדש ואמרינן משום דבעי' צבור בחטאת קבועה וטומאת מקדש וקדשיו הוי בעולה ויורד וה\"ה על שמיעת קול ועל בטוי שפתים דלא הוי חטאת קבועה דב\"ד פטור והאי דקתני הכא אין ב\"ד חייבין על שמיעת קול כו' משום דבעי אפלוגי ר' יוסי הגלילי ור\"ע אין ב\"ד חייבין על שמיעת קול ועל בטוי שפתים וטומאת מקדש וקדשיו וה\"ה למשיח:"],[9,"והנשיא כיוצא בהן","דאינו בקרבן עולה ויורד דברי ר' יוסי הגלילי טעמא דר' יוסי הגלילי מפרש בגמרא:"],[9,"ר\"ע אומר הנשיא חייב בכולן","בקרבן עולה ויורד חוץ משמיעת קול שאין שמיעת קול חל עליו שהמלך לא דן ולא דנין אותו לא מעיד ולא מעידין אותו כדתנן במסכת סנהדרין בפרק כ\"ג (סנהדרין דף יח.) ור\"ע במשיח לא פי' במתניתין ופירש בברייתא כדאמרינן בברייתא תניא ר\"ע אומר משוח פטור מכולן מקרבן עולה ויורד ומביא על כולן פר כדאמרי' בסוף פירקין דר\"ע לא פטר ליה מפר:"],[10,"גמ' והיה כי יאשם לאחת מאלה","דאשמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו קאי וקסבר ר' יוסי הגלילי כי יאשם לאחת הכי משמע כל שיש באחת כלומר כל שמצווה בכל אחת ואחת מתחייב קרבן בכולן ושאין מתחייב באחת אין מתחייב בכולן ונשיא הואיל ואינו מתחייב באחת מהן דהיינו בשמיעת קול אין מתחייב בכולן דפטור מכולן:"],[11,"ואימא","כי יאשם לאחת הכי משמע כי אפשר שיהא מתחייב אפי' באחת מהן אע\"פ שאין מתחייב בכולן הוי חייב ונשיא נמי אע\"פ שאינו חייב בשמיעת קול יהא חייב בבטוי שפתים וטומאת מקדש וקדשיו:"],[12,"אלא טעמא דר' יוסי הגלילי מהכא וכו'","נאמר בשמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו:"]],[[0,"","והא אמר מר עשר מצות נצטוו במרה. הא דלא מייתי מהני דכתיב בהדיא כגון מילה לאברהם שפיכת דמים דכתיב שופך דם האדם וגילוי עריות. משום דהכא נצטוו ישראל והתם בני נח:"],[2,"","חייב על עשה ועל לא תעשה שבנדה. בפרק ידיעות הטומאה מפרש שפירש מן הנדה בקושי שיציאתו הנאה לו כביאתו אלא ינעץ צפרניו ויפרוש באבר מת ולהכי חייב על אותו עשה דהוי בלא תעשה שיש לפרוש באבר מת. ובת\"כ מפרש דאין חייבין על עשה דכתיב אשר לא תעשינה יכול שאני מוציא אף עשה שבנדה ת\"ל מצות ה' ריבה וכו' ומה ראית כו' מוציא אני שאר מצות שאין בהן לא תעשה ומרבה אני עשה שבנדה שיש בה לא תעשה: סליק"]]],[["(ויקרא ה, ז) לא תגיע ידו ונאמר (ויקרא ה, יא) לא תשיג ידו מי שבא לידי עניות ועשירות יצא נשיא ומשיח שאין באין לידי עניות","נשיא דכתיב (ויקרא ד, כב) ועשה אחת מכל מצות ה' אלהיו מי שאין על גביו אלא ה' אלהיו משיח דכתיב (ויקרא כא, י) והכהן הגדול מאחיו שהוא גדול מאחיו בנוי בכח בחכמה ובעושר אחרים אומרים מנין שאם אין לו גדלהו משל אחיו ת\"ל והכהן הגדול מאחיו אשר יוצק על ראשו גדלהו מאחיו","בעא מיניה רבינא מר\"נ בר יצחק נשיא שנצטרע מהו מידחא דחי או מיפטר פטיר א\"ל דילך או דגזא","תניא ר\"ע אומר משיח פטור מכולן אמר רבא מ\"ט דר\"ע אמר קרא (ויקרא ו, יג) זה קרבן אהרן ובניו זו באה חובה לו ואין אחרת באה חובה לו","ואימא כי ממעט ליה רחמנא מדלי דלות ומאי ניהו עשירית האיפה אבל עניות ועשירו' לא מעטיה רחמנא לא ס\"ד דכתי' (ויקרא ה, יג) וכפר עליו הכהן על חטאתו אשר חטא מאחת מאלה המתכפר באחת מתכפר בכולן ושאין מתכפר באחת אין מתכפר בכולן","אלא מעתה דכתיב (ויקרא ה, ה) והיה כי יאשם לאחת מאלה ה\"נ דכל המתחייב באחת מתחיי' בכולן ושאין מתחיי' באחת אין מתחייב בכולן אלמה תנן ר\"ע אומר נשיא חייב חוץ משמיעת קול","אביי ורבא דאמרי תרוייהו מאחת משמע ליה לאחת לא משמע ליה ומ\"ש מאחת דמשמע ליה","דכתביה רחמנא לבסוף גבי עשירית האיפה למימרא דכל דמחייב בעשירית האיפה מחייב בכולן דאי ס\"ד מתחייב באחת אע\"פ שאין מתחייב בכולן נכתביה להאי מאחת מאלה בדלות א\"נ בעשירות:","\u0001מתני׳\u0002 כל המצות שבתורה שחייבין על זדונן כרת ועל שגגתן חטאת היחיד מביא כשבה ושעירה והנשיא שעיר ומשיח וב\"ד מביאין פר ובעבודת כוכבים היחיד והנשיא והמשיח מביאין שעירה וב\"ד פר ושעיר פר לעולה ושעיר לחטאת","אשם תלוי היחיד והנשיא חייבין ומשיח וב\"ד פטורין אשם ודאי היחיד והנשיא והמשיח חייבין וב\"ד פטורין","על שמיעת הקול ועל בטוי שפתים ועל טומאת מקדש וקדשיו ב\"ד פטורין והיחיד והנשיא והמשיח חייבין אלא שאין כ\"ג משיח חייב על טומאת מקדש וקדשיו דברי ר\"ש ומה הן מביאין קרבן עולה ויורד ר\"א אומר הנשיא מביא שעיר:","\u0001גמ׳\u0002 תניא ר\"ש היה נותן כלל כל שהיחיד באשם תלוי הנשיא כיוצא בו משיח וב\"ד פטורין וכל שהוא באשם ודאי נשיא ומשיח כיוצא בהן וב\"ד פטורין","שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו בית דין פטורין נשיא ומשיח חייבין אלא שאין הנשיא חייב בשמיעת הקול ולא משיח בטומאת מקדש וקדשיו כל שהוא בעולה ויורד נשיא כיוצא בו משיח ובית דין פטורין","הא גופא קשיא אמרת שאין משיח חייב בטומאת מקדש וקדשיו בטומאת מקדש וקדשיו הוא דפטור אבל בשמיעת הקול ובטוי שפתים חייב אימא סיפא כל שהוא בעולה ויורד נשיא כיוצא בו משיח ובית דין פטורין קתני משיח ובית דין פטורין מה בית דין פטורין מכולהון אף משיח פטור מכולהון"],[[0,"לא תגיע ידו לא תשיג ידו","דמשמע מי שבא לידי עניות ועשירות דפעמים עני ופעמים עשיר הוא דישנו בקרבן עולה ויורד יצא משיח ונשיא דלעולם עשירים הם:"],[0,"נשיא","שאין על גביו שום אדון אלא ה' דהיינו מלך ומלך לעולם עשיר הוא וכ\"ג בעינן שיהא גדול מאחיו בעושר דליהוי לעולם עשיר:"],[2,"נשיא שנצטרע","לר' ירמיה ולר' יוסי הגלילי דעבר מנשיאותו שאין ראוי להיות מלך כשהוא מצורע כדאמרי' לקמן בפ\"ב (הוריות דף י.) וינגע ה' את המלך ויהי מצורע עד יום מותו וישב בבית החפשית דמשמע שנעשה חפשי ממלכותו:"],[2,"מהו","מי אמרי' פטור מקרבן עולה ויורד כשהוא נשיא ועכשיו כשנצטרע דעבר מנשיאותו ליחייב או דלמא מאי דהוי הוי כשהוא נשיא כלומר הואיל ונדחה ידחה כשנצטרע: ל\"א מדחא דחי להאי נשיאות מקרבן עולה ויורד לגמרי דהואיל ונדחה ידחה אפילו כשנצטרע או דלמא מיפטר פטר נשיאות מקרבן עולה ויורד ובזמן דליכא נשיאות ליחייב דהיינו משנצטרע:"],[2,"א\"ל","ממאי קבעית לחיוביה לאתויי קרבן כשנצטרע מממון שלך או מממון דגזא דידיה הוי אומר מגזא דידי' הוא דבעי לאתויי וכיון דמגזא דידיה קבעי אתויי אמטו להכי פטור לגמרי מקרבן עולה ויורד דה\"ק רבי ירמיה ור' יוסי יצא נשיא ומשיח שאין באין לידי עניות האי נשיא שנצטרע נמי אינו בא לידי עניות דגזא דידיה כדקאי קאי הלכך פטור לגמרי:"],[3,"תניא ר\"ע אומר משיח פטור מכולם","מקרבן עולה ויורד דכתיב זה קרבן אהרן ובניו ביום המשח אותו עשירית האיפה דהיינו חביתי כהן משיח דחביתין באה לו חובה ואין אחרת באה לו דעשירית האיפה עולה ויורד לא באה לו חובה הלכך פטור מכולם מעולה ויורד ואמרינן לקמן דמפר לא פטר ליה ר\"ע ואיכא לתרוצי דטעמא דר\"ע משום דמעולה ויורד הוא דאמעיט כדכתיב זה קרבן אהרן אבל מפר לא אמעיט:"],[4,"אימא כי מעטי' קרא","לכהן משיח:"],[4,"מדלי דלות","דהיינו מעשירית האיפה דכתיב זה קרבן אהרן דאין אחרת עשירית האיפה באה לו חובה:"],[4,"מדלות לא מעטיה","דעל שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו לחייב כשבה או שעירה או תורין ובני יונה:"],[4,"לא ס\"ד דכתיב","גבי עשירית האיפה וכפר עליו הכהן מאחת מאלה דמשמע כל המתכפר באחת כלומר בכל אחת ואחת אפילו בעשירית האיפה מתכפר בכולן דישנו בעשירות ובדלות ובדלי דלות:"],[4,"ושאין מתכפר באחת מהן","כגון משיח דודאי אין מתכפר בעשירית האיפה דכתיב זה קרבן:"],[4,"אין מתכפר בכולם","דאמעיט נמי דאינו בקרבן עולה ויורד כלל:"],[5,"אלא מעתה האי דכתיב לאחת מאלה הכי נמי דכל דמחייב באחת","כלומר בכל אחת ואחת מחייב בכולן ושאין מתחייב באחת כגון נשיא שאין מתחייב בשמיעת הקול אינו חייב בכולן כדאמר ר' יוסי הגלילי והא חוץ משמיעת הקול קתני דקתני ר\"ע אומר הנשיא חייב בכולן חוץ משמיעת הקול דאע\"ג דאין מתחייב באחת מהן מתחייב בשאר כולן:"],[7,"נכתביה רחמנא להאי מאחת בדלות","בתורין ובני יונה:"],[7,"אי נמי בעשירות","דהיינו כשבה או שעירה אלא מדכתב ביה רחמנא מאחת גבי עשירית האיפה למימרא דשאין מתחייב בעשירית האיפה אין מתחייב בכולן כלל הלכך פטור משיח מכולן הואיל ואין מתכפר בעשירית האיפה דכתיב זה קרבן דאין אחרת באה לו חובה:"],[8,"מתני' כל המצות שבתורה שחייבין על זדונן כרת ועל שגגתן וכו' משיח וב\"ד מביאין פר","כדאמרינן לעיל (הוריות דף ח.) נאמר כאן עליה ונאמר להלן לגלות ערותה עליה וכו' ונשיא יליף ממצות יחיד ואם נפש ילמוד תחתון מעליון:"],[8,"ובעבודת כוכבים יחיד ונשיא ומשיח מביאים שעירה","דכתיב בפרשת שלח לך בעבודת כוכבים ואם נפש וגו' וכולן בכלל נפש אחת הן:"],[8,"וב\"ד מביאין פר ושעיר","כדכתיב בפרשת שלח לך ואמר לעיל (הוריות דף ז:) יליף מעיני מעיני מה להלן ב\"ד אף כאן ב\"ד:"],[9,"אשם תלוי היחיד והנשיא חייבים בית דין ומשיח פטורים","כדאמר בריש פירקין דכתיב באשם תלוי וכפר הכהן על שגגתו אשר שגג מי שחטאו ושגגתו שוה וכו':"],[9,"אשם ודאי יחיד ונשיא ומשיח חייבין","דכתיב באשמות ואם נפש ונשיא ומשיח בכלל נפש אחת הן והא דתנן לעיל (הוריות דף ח.) אין חייבים אלא על דבר שזדונו כרת ושגגתו חטאת ואשם ודאי אין שגגתו חטאת וכן המשיח הכי משמע וכן המשיח דגבי אשם ודאי פר הוא דלא יביא אבל אשם ודאי יביא כהדיוט:"],[9,"וב\"ד פטורים","מאשם ודאי דפטורים לגמרי דאינן בכלל נפש אחת:"],[10,"על שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו ב\"ד פטורין","דאמר לעיל (שם:) אין חטאת צבור אלא בקבועה והני עולה ויורד נינהו:"],[10,"יחיד ונשיא ומשיח חייבין","בשמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו דכולן בכלל נפש אחת הן:"],[10,"","אלא שאין כ\"ג משיח חייב על טומאת מקדש וקדשיו דברי רבי שמעון. מפרש בגמרא והוא הדין דקאמר רבי שמעון אלא שאין הנשיא חייב על שמיעת הקול דמלך לא מעיד ולא מעידין אותו אלא לא אצטריך ליה למיתנא דהא תנא ליה לעיל ר\"ע:"],[10,"ומה הן מביאין","נשיא בבטוי שפתים וטומאת מקדש וקדשיו ומשיח בשמיעת קול ובטוי שפתים קרבן עולה ויורד:"],[10,"ר\"א אומר נשיא מביא שעיר","ושלש מחלוקות בדבר ר' יוסי הגלילי סבר נשיא ומשיח פטורין מכולן ור\"ע סבר נשיא חייב בכולן חוץ משמיעת הקול ומשיח פטור מכולן מעולה ויורד ור\"ש סבר נשיא ומשיח חייבין בכולן בעולה ויורד אלא שאין כ\"ג ומשיח חייב על טומאת מקדש וקדשיו:"],[11,"","גמ' היה נותן בהן כלל:"],[12,"כל שהוא בעולה ויורד","דהיינו שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו:"],[12,"משיח וב\"ד פטורין","משיח דומיא דב\"ד מה ב\"ד פטורים מכולהו משמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו דצבור אין חטאתו אלא בקבועה אף משיח פטור מכולהו:"]],[]],[["קשיין אהדדי","אמר רב הונא בריה דרב יהושע לא קשיא כאן בדלות כאן בדלי דלות ור\"ש סבר לה כר\"ע בחדא ופליג עליה בחדא סבר לה כר\"ע בדלי דלות דפטור ופליג עליה בדלות:","אלא שאין כ\"ג חייב כו': אמר חזקיה מ\"ט דר\"ש דכתיב (במדבר יט, כ) ונכרתה הנפש ההיא מתוך הקהל מי שקרבנו שוה לקהל יצא זה שאין קרבנו שוה לקהל","א\"כ נשיא נמי אין קרבנו שוה לקהל שוה בכפרה דיוה\"כ א\"כ כהנים נמי לא שוו לקהל בכפרה דיוה\"כ כהנים שוו לקהל בשאר מצות דשנה כולה","משיח נמי הא שוה בשאר מצות דשנה אלא אמר רבא אימא הכי מי שחטאתו שוה ליחידים ומאי ניהו קהל:","ר\"א אומר הנשיא מביא שעיר וכו': א\"ר יוחנן לא אמר ר' אליעזר אלא בטומאת מקדש וקדשיו הואיל ונאמר כרת בו כבקבועה","אמר רב פפא ה\"נ מסתברא דאי ס\"ד ר\"א על כולהון קאמר מכדי שעיר נשיא ופר משיח במקום יחיד לחטאת קאי ניתני נמי משיח מביא פר בשמיעת קול ובטוי שפתים אלא מדלא קתני משיח ש\"מ אטומאת מקדש וקדשיו קאי דמשיח פטור","א\"ל רב הונא בריה דרב נתן לר\"פ ממאי דלמא ר\"א אכולהון קאי ובמשיח סבר לה כר\"ע דאמר משיח פטור בכולן א\"ל ור\"ע מי פטר ליה מפר ותו לא מידי","א\"ר יוחנן מודה ר\"א שאין מביא אשם תני תנא קמיה דרב ששת אשם תלוי בא על טומאת מקדש וקדשיו א\"ל דאמר לך מני ר\"א היא דאמר הואיל ונאמר בו כרת כבקבועה מייתי נשיא שעיר עליה והא\"ר יוחנן מודה ר' אליעזר שאין מביא אשם תלוי קשיא:","\u0001הדרן עלך הורה כהן משיח\u0002","מתני׳ \u0001כהן\u0002 משיח שחטא ואח\"כ עבר ממשיחותו וכן נשיא שחטא ואחר כך עבר מגדולתו כהן משיח מביא פר והנשיא מביא שעיר משיח שעבר ממשיחותו ואחר כך חטא וכן הנשיא שעבר מגדולתו ואח\"כ חטא כהן משיח מביא פר והנשיא כהדיוט:","\u0001גמ׳\u0002 השתא יש לומר עבר ממשיחותו"],[[0,"קשיין אהדדי","דקתני אלא שאין משיח [חייב] אטומאת מקדש וקדשיו הא בשמיעת קול ובטוי שפתים חייב:"],[1,"בדלי דלות","משיח פטור מכולהו כדכתיב זה קרבן אהרן דאין אחרת באה לו חובה והאי דקאמר דמשיח חייב בשמיעת קול ובטוי שפתים כגון בדלות בתורין ובני יונה שעדיין לא בא לדלי דלות:"],[1,"דר\"ש סבר לה כר\"ע בחדא","דפטר ליה למשיח מדלי דלות מזה קרבן אהרן ובניו:"],[1,"ופליג עליה בחדא","בדלות דאילו ר\"ע פטר ליה נמי בדלות דקאמר שאין מתכפר בעשירית האיפה אין מתכפר בכולן ולר\"ש בדלי דלות הוא דאין מתכפר הא בדלות ועשירות מתכפר:"],[2,"מ\"ט דר' שמעון","דאמר ולא משיח אינו חייב בטומאת מקדש וקדשיו:"],[2,"דכתיב","בטומאת מקדש וקדשיו ונכרתה הנפש ההיא מתוך הקהל:"],[2,"מי שקרבנו שוה לקהל","דמתכפר בשל קהל הוא דחייב בטומאת מקדש וקדשיו:"],[2,"יצא","משיח שאין קרבנו שוה דאין מתכפר בשל קהל בכפרת יוה\"כ דהוא מתכפר בפר והם בשעיר:"],[3,"א\"כ נשיא נמי אין קרבנו שוה לקהל","דהוא מביא שעיר והם מתכפרין בפר בשאר ימות השנה ואמאי קתני המשיח לחודיה פטור בטומאת מקדש וקדשיו ולא נשיא ויחיד:"],[3,"","ומשני הא לאו מילתא היא משום דהא שוה לקהל בכפרת יוה\"כ:"],[3,"אי הכי כהנים נמי הא לא שוו לקהל בכפרה דיוה\"כ","דמתכפרין בפרו של אהרן וליפטרו בטומאת מקדש וקדשיו:"],[3,"הא לא קשיא משום דכהנים שוו לקהל בשאר מצות דשנה כולה","דמתכפרי עם הצבור בפר הבא על כל המצות הלכך חייבין בטומאת מקדש וקדשיו:"],[4,"כהן משיח נמי הא שוה לקהל בשאר מצות","דכל השנה כולה דכי הורה עם הצבור מתכפר עם הצבור וליחייב בטומאת מקדש וקדשיו:"],[4,"אלא אמר רבא אימא הכי","מתוך הקהל מי שחטאו שוה ליחידים דמחייבי בשגגת מעשה כיחידים דיחידים שחטאו בשגגת מעשה מייתי כל חד ומאן יחידים קהל דכי חטאו קהל בשגגת מעשה לחודיה בלא העלם דבר מייתו כל חד קרבן דאותן השוה ליחידים בדבר זה הוא דמחייבי בטומאת מקדש וקדשיו יצא משיח שאין חטאו שוה ליחיד דכי חטא בשגגת מעשה בלא העלם דבר פטור לגמרי כדאמרינן לקמן בפרק בתרא (הוריות דף יא.) מע\"ה פרט למשיח דאין מביא בשגגת מעשה והיינו דאמרינן לעיל (הוריות דף ז:) יצא משיח שאין חטאו בשגגה וכיון דאין חטאו שוה ליחיד לפיכך פטור בטומאת מקדש וקדשיו:"],[5,"א\"ר יוחנן לא א\"ר אליעזר","דנשיא מביא שעיר בידיעה במקום עולה ויורד:"],[5,"אלא בטומאת מקדש וקדשיו הואיל ונאמר בו כרת כבקבועה","כלומר כבחטאת קבועה דקסבר ר\"א דכי היכי דבמקום שחייבים על זדונו כרת ועל שגגתו חטאת דהיינו במקום חטאת קבועה נשיא מביא שעיר ה\"נ היכא דחייב לה על זדונו כרת ועל שגגתו עולה ויורד מביא שעיר הואיל ודמי לחטאת קבועה לענין כרת אבל בשמיעת קול ובטוי שפתים דאין חייבין על זדונו כרת דלא דמי לחטאת קבועה לא בזדון ולא בשוגג מודה ר' אליעזר דנשיא אין מביא שעיר אלא קרבן עולה ויורד כהדיוט:"],[6,"אמר רב פפא הכי נמי מסתברא דאי ס\"ד רבי אליעזר","דאמר נשיא מביא שעיר אכולהו שמיעת קול ובטוי שפתים וטומאת מקדש וקדשיו:"],[6,"מכדי שעיר","דנשיא במקום חטאת קבועה דיחיד קאי והוא הדין לפר כהן משיח דבמקום חטאת קבועה דיחיד קאי וכדתנא כל מצות שבתורה שחייבין על זדונן כרת ועל שגגתן חטאת דהיינו חטאת קבועה יחיד מביא כשבה או שעירה ונשיא מביא שעיר ומשיח פר וכיון דשעיר דנשיא ופר כהן משיח במקום חטאת קבועה דיחיד קיימי אי אמרת אכולהו קאמר ר\"א דנשיא מביא שעיר אע\"ג דלית בהו כרת כבקבועה:"],[6,"ניתני נמי משיח מביא פר בשמיעת קול ובטוי שפתים","כי דיניה אע\"ג דלית בהו כרת כבקבועה:"],[6,"אלא לאו","מדלא קתני הכי ש\"מ דאטומאת מקדש וקדשיו קא\"ר אליעזר דנשיא מביא שעירה הואיל ונאמר בו כרת כבקבועה והאי דלא קתני ומשיח מביא פר בטומאת מקדש וקדשיו הואיל ונאמר בו כרת כבקבועה משום דמשיח פטור לגמרי בטומאת מקדש וקדשיו דסבר לה כר\"ש דפוטר:"],[7,"א\"ל רב הונא בריה דרב נתן לרב פפא וממאי דלמא ר\"א אכולהו קאי","דנשיא מביא שעיר אפי' שלא במקום כרת והאי דלא קתני נמי משיח מביא פר בטומאת מקדש וקדשיו ובשמיעת קול ובטוי שפתים משום דבמשיח סבר לה כר\"ע דאמר משיח פטור מכולן משמיעת קול ובטוי שפתים ולעולם אכולהו קאי ר\"א דנשיא מביא שעיר:"],[7,"א\"ל ר\"ע מי פטר","נמי למשיח מפר (דלמא) כי קא\"ר עקיבא משיח פטור מכולן מטומאת מקדש וקדשיו ושמיעת קול ובטוי שפתים כגון להביא קרבן עולה ויורד אבל להביא פר מחייב וכיון דמחייב בפר א\"כ ניתני נמי ר\"א משיח מביא פר בשמיעת קול ובטוי שפתים אלא מדלא קתני הכי ש\"מ דאטומאת מקדש וקדשיו קאי רבי אליעזר דנשיא מביא שעיר הואיל ונאמר בו כרת כבקבועה והא דלא קתני ומשיח מביא פר בטומאת מקדש וקדשיו משום דסבר לה כר\"ש דאמר דאין כהן משיח חייב בטומאת מקדש וקדשיו:"],[7,"ותו לא מידי","ותו ליכא למיקשי ולא מידי:"],[8,"א\"ר יוחנן","אע\"ג דקאמר ר\"א הואיל ונאמר בו כרת כבקבועה דנשיא מביא שעיר כבחטאת קבועה מודה ר\"א לענין אשם תלוי דלאו דיניה כבחטאת קבועה דכי היכי דאמר לעיל אין יחיד מביא אשם תלוי אלא על ספק קבועה ה\"נ אין מביא אשם תלוי על ספק טומאת מקדש וקדשיו שאע\"פ שנא' בו כרת כבקבועה הואיל ואינה ממש חטאת קבועה אין מביא אשם תלוי:"],[8,"תני תנא קמיה דרב ששת אשם תלוי בא על ספק טומאת מקדש וקדשיו","הואיל ונאמר בו כרת כבקבועה:"],[8,"א\"ל דאמר לך מני ר\"א היא דאמר","נשיא מביא שעיר הואיל ונאמר בו כרת כבקבועה וקאמ' דה\"ה לענין אשם תלוי: ומי מצית אמרת הכי והא א\"ר יוחנן מודה ר\"א שאין מביא אשם תלוי:"],[8,"קשיא","דמתני' דידך לא מיתוקמא דלא כחד:"],[9,"פרק שלישי","כהן משיח"],[11,"","השתא יש לומר עבר ממשיחותו ואחר כך חטא מביא פר חטא ואחר כך עבר ממשיחותו מיבעיא נשיא איצטריכא ליה סלקא דעתך הואיל ועבר מנשיאותו ואחר כך חטא הוי כהדיוט חטא ואחר כך עבר מנשיאותו נמי ליהוי כהדיוט קמ\"ל לישנא אחרינא צריכא למימר דחטא ואחר כך עבר ממשיחותו דמביא פר הא כיון דתנא ליה עבר ממשיחותו דמביא פר כל שכן חטא ואחר כך עבר ממשיחותו דמביא פר הא לא קשיא משום דקתני גבי נשיא כי עבר מגדולתו ואחר כך חטא כי הדיוט מייתי סלקא דעתך אמינא כי חטא ואחר כך עבר נייתי נמי כי הדיוט הלכך תנא גבי נשיא שחטא ואחר כך עבר דמייתי כי נשיא ואיידי דתנא גבי נשיא חטא ואחר כך עבר תנא נמי גבי משיח חטא ואח\"כ עבר ממשיחותו מביא פר ומה שכתוב בספרים תני גבי משיח עבר ואחר כך חטא לאו מתרצתא היא ולשון ראשון עיקר דקאמר השתא יש לומר כו':"]],[]],[["ואח\"כ חטא מביא פר חטא ואח\"כ עבר ממשיחותו צריכא למימר משום דקתני גבי נשיא דכי עבר מנשיאותו ואח\"כ חטא כהדיוט מייתי אהכי תני גבי משיח [חטא ואח\"כ עבר] מביא פר","מנא ה\"מ דתנו רבנן (ויקרא ד, ג) והקריב על חטאתו מלמד שמביא חטאתו משעבר","שיכול והלא דין הוא ומה נשיא שמביא בשגגת מעשה אין מביא חטאתו משעבר משיח שאין מביא בשגגת מעשה אלא על העלם דבר עם שגגת מעשה [לא] כ\"ש תלמוד לומר והקריב על חטאתו מלמד שמביא על חטאתו משעבר","ונייתי נמי נשיא מק\"ו ומה משיח שאין מביא בשגגת מעשה מביא חטאת משעבר נשיא שמביא חטאת בשגגת מעשה אינו דין שמביא חטאתו משעבר תלמוד לומר (ויקרא ד, כב) אשר נשיא יחטא כשהוא נשיא אין כשהוא הדיוט לא:","\u0001מתני׳\u0002 חטאו עד שלא נתמנו ואח\"כ נתמנו הרי אלו כהדיוטות ר\"ש אומר אם נודע להם עד שלא נתמנו חייבים ומשנתמנו פטורים","איזהו נשיא זה מלך שנאמר (ויקרא ד, כב) מכל מצות ה' אלהיו שאין על גביו אלא ה' אלהיו:","\u0001גמ׳\u0002 מה\"מ דתנו רבנן (ויקרא ד, ג) אם הכהן המשיח יחטא (לאשמת) פרט לקודמות","שיכול והלא דין הוא ומה נשיא שמביא בשגגת מעשה אין מביא על הקודמות משיח שאין מביא אלא על העלם דבר עם שגגת מעשה אינו דין שלא יביא על הקודמות","לא אם אמרת בנשיא שכן אין מביא חטאתו משעבר תאמר במשיח שמביא חטאתו משעבר הואיל ומביא חטאתו משעבר יביא על הקודמות תלמוד לומר המשיח יחטא חטא כשהוא משיח מביא כשהוא הדיוט אינו מביא","ותניא נמי גבי נשיא כה\"ג (ויקרא ד, כב) אשר נשיא יחטא פרט לקודמות","שיכול והלא דין הוא ומה משיח שמביא חטאתו משעבר אינו מביא על הקודמות נשיא שאין מביא חטאתו משעבר אינו דין שלא יביא על הקודמות","מה למשיח שכן אין מביא בשגגת מעשה תאמר בנשיא שמביא בשגגת מעשה הואיל ומביא בשגגת מעשה יביא על הקודמות תלמוד לומר אשר נשיא יחטא שחטא והרי הוא נשיא ולא שחטא ועודהו הדיוט:","ת\"ר אשר נשיא יחטא יכול גזרה ת\"ל אם הכהן המשיח יחטא מה להלן לכשיחטא אף כאן לכשיחטא","אמר מר יכול גזרה גזרה מהיכא תיתי","אמרי אין אשכחן דכתיב (ויקרא יד, לד) ונתתי נגע צרעת בבית ארץ אחוזתכם בשורה היא להם שנגעים באים עליהם דברי רבי יהודה רבי שמעון אומר פרט לנגעי אונסין לאו אמר רבי יהודה בשורה הכא נמי אימא גזרה היא הלכך כתיב אם","ולרבי שמעון נגעי אונסין מי לא מטמו והא תניא (ויקרא יג, ב) אדם כי יהיה מן הדבור ואילך והלא דין הוא טמא בזב וטמא בנגעים מה זב מן הדבור ואילך אף נגעים מן הדבור ואילך","לא אם אמרת בזב שכן אין מטמא באונס תאמר בנגעים שמטמאין באונס תלמוד לומר אדם כי יהיה מן הדבור ואילך רבא אמר פרט לנגעי רוחות רב פפא אמר פרט לנגעי כשפים","תנו רבנן אשר נשיא יחטא פרט לחולה משום דהוה ליה חולה אידחי ליה מנשיאותיה אמר רב אבדימי בר חמא פרט לנשיא שנצטרע שנאמר (מלכים ב טו, ה) וינגע ה' את המלך ויהי מצורע עד יום מותו וישב בבית החפשית ויותם בן המלך על הבית מדקאמר בבית החפשית מכלל דעד השתא עבד הוה","כי הא דר' גמליאל ורבי יהושע הוו אזלי בספינתא בהדי דר' גמליאל הוה פיתא בהדי רבי יהושע הוה פיתא וסולתא שלים פיתיה דר' גמליאל סמך אסולתיה דרבי יהושע אמר ליה מי הוה ידעת דהוה לן עכובא כולי האי דאיתית סולתא אמר ליה כוכב אחד לשבעים שנה עולה ומתעה את (הספינות) [הספנים] ואמרתי שמא יעלה ויתעה [אותנו]","אמר ליה כל כך בידך ואתה עולה בספינה א\"ל עד שאתה תמה עלי תמה על שני תלמידים שיש לך ביבשה רבי אלעזר חסמא ורבי יוחנן בן גודגדא שיודעין לשער כמה טפות יש בים ואין להם פת לאכול ולא בגד ללבוש נתן דעתו להושיבם בראש","כשעלה שלח להם ולא באו חזר ושלח ובאו אמר להם כמדומין אתם ששררה אני נותן לכם"],[[1,"מה\"מ","דמשיח שעבר ואח\"כ חטא דמביא פר:"],[4,"מתני' חטאו עד שלא נתמנו ואח\"כ נתמנו הרי אלו כהדיוטות","דרבנן בתר חטא אזלי:"],[4,"ר\"ש אומר אם נודע להם עד שלא נתמנו חייבין","דר\"ש חטאה וידיעה בעי וה\"ה דפליג ר\"ש ברישא דקתני נשיא שחטא ואח\"כ עבר מגדולתו מביא שעיר דר\"ש קאמר נמי דאם נודע לו משעבר דאין מביא שעיר דחטאה וידיעה בעי כשהוא נשיא:"],[6,"גמ' אם הכהן המשיח יחטא","חטא במשיחות הוא דמביא פר:"],[6,"פרט לקודמות","לשחטא ואח\"כ נתמנה דהרי הוא כהדיוט ואין מביא פר:"],[7,"ומה נשיא שמביא בשגגת מעשה אין מביא על הקודמות","כדאמר לקמן אשר נשיא יחטא כשיחטא והרי הוא נשיא ולא כשיחטא והרי הוא הדיוט:"],[8,"שאין מביא חטאתו משעבר","כדתנן וכן הנשיא שעבר מגדולתו ואח\"כ חטא הנשיא כהדיוט:"],[12,"יכול גזרה","דגזרת מלך היא שנשיא יחטא מדלא כתיב ואם נשיא יחטא:"],[12,"ת\"ל אם הכהן המשיח יחטא","מה יחטא האמור להלן לכשיחטא דהא כתיב אם אף יחטא האמור כאן גבי נשיא לכשיחטא:"],[13,"גזרה מהיכא תיתי","כלומר היכי מצית למימר יכול גזרה דהיכא אשכחן גזרה כה\"ג:"],[14,"אין","דודאי אשכחן כה\"ג:"],[14,"דכתיב ונתתי נגע צרעת בבית ארץ אחוזתכם בשורה היא להם","שהכתוב מבשרן שעתיד להיות אע\"פ שדבר רע הוא הכא נמי אימא גזרה הלכך כתיב אם הכהן המשיח יחטא לכשיחטא וה\"נ אשר נשיא יחטא לכשיחטא:"],[14,"ר\"ש אומר","ונתתי נגע צרעת שיהא בא מאליו:"],[14,"פרט לנגעי אונסין","שאם באו נגעים ע\"י נפיחת שד דלא מיטמו:"],[15,"אדם כי יהיה בעור בשרו מדבור ואילך","דנגעים בין באדם ובין בבתים פטר בהן לפני הדבור דאותן נגעים שארעו לפני הדבור אין מטמאין לאחר הדבור:"],[15,"מה זב מדבור ואילך","דכתיב כי יהיה זב מבשרו דזבין שהיו לפני הדבור אין מטמאין לאחר הדבור אלא אם כן ראו זיבות אחר הדבור:"],[16,"תאמר בנגעי אדם שמטמאין באונס","כגון על ידי נפילה והכאה וכויה או ע\"י שד וה\"ה לנגעי בתים דמטמאו באונס:"],[16,"רבא אמר","לא קשיא הא דקאמר ר\"ש פרט לנגעי אונסין כגון נגעי רוחות דע\"י נפיחת שד ולא ע\"י אדם וכי קתני תאמר בנגעים שמטמאין באונס כגון ע\"י הכאה וכויה:"],[16,"רב פפא אמר","כי אמר ר\"ש פרט לנגעי אונס ע\"י כשפים דלא מטמו וכי קתני תאמר בנגעים דמטמאו באונס כגון שלא ע\"י כשפים:"],[17,"וישב בבית החפשית","דנעשה חפשי מן המלכות כהדיוט דמי ואינו מביא שעיר ודלא כרבי יוסי דאמר לעיל בפרק הורה כהן משיח (הוריות דף ט.) מי שבא לידי עניות והאי נצטרע לא בא לידי עניות דגזא דידיה מיהא איתיה:"],[17,"מכלל דעד השתא עבד הוה","דשררות עבדות הוא לו לפי שמוטל עליו עול רבים:"],[18,"וסולתא","סולת ולהכי נקט בהדי פיתא סולת קמחא לפי שהפת מתעפש ואינו מתקיים כסולת:"],[18,"ומתעה את הספנים","שכן דרך של ספנים לשעה הפורשין לים רב החובל נותן עיניו [בצפון והכוכב מתהלך לדרום ורואה] בכוכב אחד העומד לימינו או לשמאלו וכל זמן שרואה אותו כוכב לצדו אחר יודע שנהפכה הספינה ומיישרה לדרכה וכוכב שעולה אחת לשבעים שנה פעמים נראה בצפון ופעמים נראה בדרום וכשרב החובל נותן עיניו בו בצפון והספינה תהפך בדרום ורואהו לצדו אחר סבור שנהפכה הספינה ומיישרה אחר הכוכב והוא סבור ליישרה ומהפכה לדרך אחר וכן הוא מתעה את הספנים:"],[19,"אמר לו כל כך","חכמה יש בידך ואתה יורד לספינה לסחורה (על) [בשביל] מזונותיך כלומר ואתה צריך לירד לספינה לצורך מזונות:"],[19,"נתן","רבן גמליאל דעתו עליהם להושיבם בראש כדי שיהו מתפרנסים [מאותה] שררה שיתן להם:"],[20,"כמדומין אתם ששררה אני נותן לכם","שלא באתם בשליחות ראשון שהייתם בורחים מן הגדולה:"]],[]],[["עבדות אני נותן לכם שנאמר (מלכים א יב, ז) וידברו אליו לאמר אם היום תהיה עבד לעם הזה:","ת\"ר (ויקרא ד, כב) אשר נשיא יחטא אמר ריב\"ז אשרי הדור שהנשיא שלו מביא קרבן על שגגתו אם נשיא שלו מביא קרבן צריך אתה לומר מהו הדיוט ואם על שגגתו מביא קרבן צריך אתה לומר מהו זדונו","מתקיף לה רבא בריה דרבה אלא מעתה דכתי' (ויקרא ה, טז) ואת אשר חטא מן הקדש ישלם ובירבעם בן נבט דכתיב ביה (מלכים א יד, טז) אשר חטא ואשר החטיא הכי נמי דאשרי הדור הוא שאני הכא דשני קרא בדבוריה","דרש רב נחמן בר רב חסדא מאי דכתיב (קהלת ח, יד) יש הבל אשר נעשה על הארץ וגו' אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים של עולם הבא בעולם הזה אוי להם לרשעים שמגיע אליהם כמעשה הצדיקים של עולם הבא בעולם הזה","אמר רבא אטו צדיקי אי אכלי תרי עלמי מי סני להו אלא אמר רבא אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים של עולם הזה בעולם הזה אוי להם לרשעים שמגיע אליהם כמעשה הצדיקים של עולם הזה בעולם הזה","רב פפא ורב הונא בריה דרב יהושע אתו לקמיה דרבא אמר להו אוקימתון מסכתא פלן ומסכתא פלן אמרו ליה אין איעתריתו פורתא אמרו ליה אין דזבנן קטינא דארעא קרי עלייהו אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים שבעולם הזה בעולם הזה","אמר רבה בר בר חנה אמר רבי יוחנן מאי דכתיב (הושע יד, י) כי ישרים דרכי ה' וצדיקים ילכו בם ופושעים יכשלו בם משל לשני בני אדם שצלו פסחיהם אחד אכלו לשום מצוה ואחד אכלו לשום אכילה גסה זה שאכלו לשום מצוה צדיקים ילכו בם זה שאכלו לשום אכילה גסה ופושעים יכשלו בם","א\"ל ריש לקיש רשע קרית ליה נהי דלא עביד מצוה מן המובחר פסח מי לא קאכיל אלא משל לשני בני אדם זה אשתו ואחותו עמו בבית וזה אשתו ואחותו עמו בבית אחד נזדמנה לו אשתו ואחד נזדמנה לו אחותו זה שנזדמנה לו אשתו צדיקים ילכו בם וזה שנזדמנה לו אחותו ופושעים יכשלו בם","מי דמי אנן קאמרינן חדא דרך והכא שני דרכים אלא משל ללוט ושתי בנותיו הן שנתכוונו לשם מצוה צדיקים ילכו בם הוא שנתכוון לשם עבירה ופושעים יכשלו בם","ודלמא הוא נמי לשם מצוה הוא מכוין א\"ר יוחנן כל הפסוק הזה לשם עבירה נאמר","(בראשית יג, י) וישא לוט (בראשית לט, ז) ותשא אשת אדניו את עיניה את עיניו (בראשית לד, ד) ויאמר שמשון [וגו'] אותה קח לי כי היא ישרה בעיני וירא (בראשית לד, ב) וירא אותה שכם בן חמור את כל ככר הירדן (משלי ו, כו) כי בעד אשה זונה עד ככר לחם כי כלה משקה (הושע ב, ז) אלכה אחרי מאהבי נותני לחמי ומימי צמרי ופשתי שמני ושקויי","והא מינס אניס תנא משום רבי יוסי בר רבי חוני למה נקוד על וי\"ו שבקומה של בכירה לומר לך שבשכבה לא ידע אבל בקומה ידע ומאי ה\"ל למעבד מאי דהוה הוה נפקא מינה דלפניא אחרינא לא איבעי ליה למישתי","דרש רבה מאי דכתיב (משלי יח, יט) אח נפשע מקרית עוז ומדינים כבריח ארמון אח נפשע מקרית עוז זה לוט שפירש מאברהם ומדינים כבריח ארמון שהטיל מדינים בין ישראל לעמון שנאמר (דברים כג, ד) לא יבא עמוני ומואבי בקהל ה'","דרש רבא ואיתימא ר' יצחק מאי דכתיב (משלי יח, א) לתאוה יבקש נפרד (ובכל) [בכל] תושיה יתגלע לתאוה יבקש נפרד זה לוט שנפרד מאברהם (ובכל) [בכל] תושיה יתגלע שנתגלה קלונו בבתי כנסיות ובבתי מדרשות דתנן עמוני ומואבי אסורין איסור עולם","ואמר עולא תמר זנתה וזימרי זינה תמר זנתה יצאו ממנה מלכים ונביאים זימרי זינה נפלו כמה רבבות מישראל אמר רב נחמן בר יצחק גדולה עבירה לשמה ממצוה שלא לשמה שנאמר (שופטים ה, כד) תבורך מנשים יעל אשת חבר הקיני מנשים באהל תבורך מאן נינהו נשים באהל שרה רבקה רחל ולאה","איני והאמר רב יהודה אמר רב לעולם יעסוק אדם בתורה ובמצות אפילו שלא לשמה שמתוך שלא לשמה בא לשמה אימא כמצוה שלא לשמה","אמר רבי יוחנן שבע בעילות בעל אותו רשע באותה שעה שנאמר (שופטים ה, כז) בין רגליה כרע נפל שכב וגו' והא קא מיתהניא מעבירה אמר רבי יוחנן משום רבי שמעון בן יוחאי אפילו טובתם של רשעים רעה היא אצל צדיקים","אמר רב יהודה אמר רב לעולם יעסוק אדם בתורה ובמצות אפילו שלא לשמה שמתוך שלא לשמה בא לשמה שבשכר מ\"ב קרבנות שהקריב בלק הרשע זכה ויצתה ממנו רות דאמר רבי יוסי ברבי חנינא רות בת בנו של עגלון בן בנו של בלק מלך מואב","א\"ר חייא בר אבא א\"ר יוחנן מנין שאין הקב\"ה מקפח אפילו שכר שיחה נאה מהכא דאילו בכירה דקרייה מואב אמר ליה רחמנא למשה (דברים ב, ט) אל תצר את מואב ואל תתגר בם מלחמה מלחמה"],[[0,"עבדות אני נותן לכם","שהשררות עבדות הוא לו לאדם לפי שמוטל עליו עול רבים:"],[1,"אשר","כמו אשרי:"],[1,"צריך אתה לומר מהו הדיוט","בתמיה כלומר אם המלך שאין לבו כפוף מרגיש ומביא קרבן על שגגתו כ\"ש שהדיוטות מרגישין שלבם כפופים:"],[1,"מהו על זדונו","בתמיה כלומר אם על שגגתו מרגיש כ\"ש שמרגיש על זדונו וחוזר בתשובה:"],[2,"שאני הכא דשני קרא בדבוריה","דבאידך כתיב אם כל עדת ישראל ישגו אם הכהן המשיח אם נפש והכא כתיב אשר נשיא יחטא ודאי אשרי משמע:"],[3,"אשריהם לצדיקים","כלומר אשרי הצדיקים שמגיע אליהם כמעשה הרשעים שבעולם הבא בעולם הזה כלומר שמגיע אליהם צרות לצדיקים בעולם הזה כדרך שמגיע לרשעים בעוה\"ב:"],[3,"אוי","כמו ווי דהכא לא כתיב אשר דמשמע אוי להם לרשעים שמגיע אליהם טובות בעולם הזה כדרך שמגיע טובות לצדיקים בעולם הבא דרעה היא לרשעים כדכתיב ומשלם לשונאיו אל פניו וגו' (דברים ז׳:י׳):"],[4,"צדיקים אי אכלי תרי עלמי מי סני להו","מי שנאוי הוא להם [כלומר כלום רע להם] לצדיקים שאוכלים שני עולמות שיש להם טובה בעוה\"ז ובעוה\"ב:"],[4,"אלא אמר רבא אשריהם לצדיקים שמגיע להם","טובות כמעשה הרשעים שבעוה\"ז שיש להם טובה כדכתיב ומשלם לשונאיו דכך מגיע לצדיקים בעוה\"ז אשריהם שיש להם טובה בעולם הזה ולעוה\"ב:"],[4,"ואוי להם לרשעים שמגיע להם","צרות כמעשה הצדיקים שבעולם הזה [דמשמע שבאים עליהם צרות כמו שבאים על הצדיקים בעוה\"ז] דהקב\"ה עושה כדי לגבות [חובם] מהצדיקים בעוה\"ז כדי שיהא להם שכר טוב בעוה\"ב דכך מצינו צרות לרשעים בעוה\"ז אוי להם שאין להם טובה לא בעולם הזה ולא בעולם הבא:"],[5,"אוקימתון מסכתא פלן","כלומר יש לכם מסכתא סדורה בפיכם מסכתא פלוני ופלוני:"],[5,"איעתריתו פורתא","כלומר יש לכם עושר ואין לכם לטרוח אחר מזונות ויש לכם פנאי לעסוק תדיר בתורה:"],[5,"אמרו לו אין דזבנן","לכל חד וחד מינן קטינא דארעא ומתזנינן מינה ברווחא:"],[5,"קרי עלייהו אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים שבעוה\"ז","דאכלי צדיקים תרי עלמי:"],[6,"לשם אכילה גסה","שלא לשום מצוה אלא נתכוין לאוכלו לשם קנוח סעודה:"],[8,"מי דמי אנן קאמרינן חד דרך","דזה ילך בה וזה יכשל בה:"],[8,"והכא שני דרכים","דלזה נזדמנה לו אשתו ולזה נזדמנה לו אחותו:"],[12,"נפשע","נמרד שמרד בו שפירש ממנו:"],[12,"מקרית עוז","עוז כמו עז אברהם כדכתיב אל צור חוצבתם (ישעיהו נא):"],[12,"שהטיל מדינים","בינו ובין בני ישראל כבריחים שנועלים שהחיצונים אינם יכולין ליכנס לפנים וכך אין עמוני ומואבי יכולין להתערב בישראל דכתיב לא יבא עמוני ומואבי:"],[13,"לתאוה","של עבירה יבקש נפרד:"],[13,"זה לוט","דכתיב ביה ויפרדו איש מעל אחיו:"],[13,"יתגלע","כמו לפני התגלע (משלי י״ז:י״ד) לשון גלוי:"],[14,"תמר זנתה","ונתכוונה לשום מצוה כדי להעמיד זרע מן הצדיקים כדכתיב כי ראתה כי גדל שלה:"],[14,"זמרי זינה","ונתכוון לשם עבירה:"],[15,"","מדקאמר גדולה עבירה לשמה ממצוה שלא לשמה מכלל דמצוה שלא לשמה גריעותא הוא והא אמר רב יהודה וכו':"],[15,"אלא אימא גדולה עבירה לשמה","כלומר לשום מצוה כמצוה שלא לשמה:"],[16,"בין רגליה כרע נפל שכב","בין רגליה כרע נפל באשר כרע שם נפל שדוד הרי שבעה:"],[16,"נתכוונה לשם מצוה","כדי להתיש כחו ותהא יכולה להורגו:"],[17,"מ\"ב קרבנות","ג\"פ ז' מזבחות פר ואיל במזבח:"],[17,"יצאה ממנו רות","שיצא ממנה דוד שריוה להקב\"ה בשירות ובתשבחות (ברכות ז: ב\"ב יד:):"],[18,"דקרייה מואב","משמע מאבי:"]],[]],[["הוא דלא הא צעורי צערינהו ואילו צעירה דקרייה בן עמי א\"ל (דברים ב, יט) אל תצורם ואל תתגר בם כלל אפילו צעורי לא","א\"ר חייא בר אבין א\"ר יהושע בן קרחה לעולם יקדים אדם לדבר מצוה שבשכר לילה אחת שקדמה בכירה לצעירה זכתה וקדמתה ארבע דורות למלכות","תנו רבנן (ויקרא ד, כז) מעם הארץ פרט למשיח מעם הארץ פרט לנשיא","והלא כבר יצאו משיח לידון בפר נשיא לידון בשעיר שיכול משיח על העלם דבר עם שגגת מעשה מביא פר על שגגת מעשה לחודיה מביא כשבה ושעירה ת\"ל מעם הארץ פרט למשיח מעם הארץ פרט לנשיא","תינח משיח אלא נשיא בשגגת מעשה הוא דמייתי","אמר רב זביד משמיה דרבא הכא במאי עסקינן כגון שאכל כזית חלב כשהוא הדיוט ונתמנה ואח\"כ נודע לו סלקא דעתך אמינא נייתי כשבה או שעירה קמ\"ל הניחא לר\"ש דאזל בתר ידיעה אלא לרבנן דאזלו בתר חטאה מאי איכא למימר","אלא אמר רב זביד משמיה דרבא הכא במאי עסקינן כגון שאכל חצי כזית חלב כשהוא הדיוט ונתמנה והשלימו ואח\"כ נודע לו סלקא דעתך אמינא נצטרף ונייתי כשבה או שעירה קמ\"ל","בעא מיניה רבא מרב נחמן נשיאות מהו שתפסיק היכי דמי כגון שאכל חצי כזית חלב כשהוא הדיוט ונתמנה ועבר והשלימו התם הוא דלא מצטרף דאכליה פלגא כשהוא הדיוט ופלגא כשהוא נשיא אבל הכא דאידי ואידי כשהוא הדיוט אכליה מצטרף או דלמא לא שנא מאי","תפשוט ליה מהא דאמר עולא א\"ר יוחנן אכל חלב והפריש קרבן והמיר וחזר בו הואיל ונדחה ידחה הכי השתא מומר לאו בר אתויי קרבן הוא האי בר אתויי קרבן הוא","בעא מיניה רבי זירא מרב ששת אכל ספק חלב כשהוא הדיוט ונתמנה ונודע לו על ספקו מהו אליבא דרבנן דאזלי בתר חטאה לא תבעי לך דמייתי אשם תלוי אלא כי תבעי לך אליבא דרבי שמעון","מדאשתני לודאי אשתני לספק או דלמא כי אשתני לודאי דאשתני קרבן דידיה אבל הכא דלא אשתני קרבן דידיה אימא לייתי אשם תלוי תיקו","ת\"ר מעם הארץ פרט למומר","ר\"ש בר יוסי אומר משום ר\"ש (ויקרא ד, כב) אשר לא תעשינה בשגגה ואשם השב בידיעתו מביא קרבן על שגגתו לא שב בידיעתו אינו מביא קרבן על שגגתו","מאי בינייהו א\"ר המנונא מומר לאכול חלב ומביא קרבן על הדם איכא בינייהו מ\"ס כיון דמומר לאכול חלב לדם נמי מומר הוי ומ\"ס לדם מיהא שב בידיעתו הוא","והא רבא אמר דכולי עלמא מומר לאכול חלב לא הוי מומר לדם אלא הכא באוכל נבלה לתאבון ונתחלף לו בשומן ואכלו קמיפלגי מר סבר כיון דלתאבון אכיל במזיד מומר הוא ומ\"ס כיון דאילו אשכח דהיתרא לא אכל דאיסורא לאו מומר הוא","תנו רבנן אכל חלב זהו מומר ואיזהו מומר אכל נבילות וטריפות שקצים ורמשים ושתה יין נסך רבי יהודה אומר אף הלובש כלאים אמר מר אכל חלב זהו מומר ואיזהו מומר אוכל נבילות כו' מאי קאמר","אמר רבה בר בר חנה א\"ר יוחנן ה\"ק אכל חלב לתאבון הרי זה מומר להכעיס הרי זה צדוקי ואיזהו מומר דבסתמו צדוקי הוי אומר אוכל נבילה וטריפה שקצים ורמשים ושתה יין נסך רבי יוסי ברבי יהודה אומר אף הלובש כלאים","מאי בינייהו איכא בינייהו כלאים דרבנן מר סבר מדאורייתא הוי מומר דרבנן לא הוי מומר ומר סבר כלאים כיון דמפרסם אסוריה אפי' בדרבנן הוי מומר","פליגי בה רב אחא ורבינא חד אמר לתאבון מומר להכעיס צדוקי וחד אמר להכעיס נמי מומר אלא איזהו צדוקי כל העובד עבודת כוכבים מיתיבי אכל פרעוש אחד או יתוש אחד ה\"ז מומר והא הכא דלהכעיס הוא וקא קרי ליה מומר התם דאמר אטעום טעם דאיסורא:","ואיזהו נשיא זה מלך כו': תנו רבנן נשיא יכול נשיא שבט כנחשון בן עמינדב ת\"ל (ויקרא ד, כב) מכל מצות ה' אלהיו ולהלן הוא אומר (דברים יז, יט) למען ילמד ליראה את ה' אלהיו"],[[0,"בן עמי","בלשון נקיה הוא דלא רצתה להודיע דמאביה נתעברה:"],[0,"אמר אל תצורם ואל תתגר בם","ומדלא כתיבא בהו מלחמה ש\"מ דאפילו צערא לא ליעבד להם ולא עוד אפילו בכירה דקריתיה אב הכתוב פירסמה דכתיב (בראשית י״ט:ל״ג) ותשכב את אביה ובצעירה כתיב ותשכב עמו:"],[1,"וקדמתה ארבע דורות","בישראל עובד ישי דוד שלמה ואילו צעירה לא הוה בישראל עד רחבעם בן שלמה דהוה ליה מנעמה העמונית:"],[2,"ת\"ר ואם נפש אחת תחטא בשגגה מעם הארץ","ולא כל ע\"ה פרט למשיח דמשמע דלא יביא כשבה או שעירה כיחיד:"],[2,"למה לי מעם הארץ","למעוטי הני והלא כבר יצא משיח מכלל יחיד לידון בפר ונשיא יצא מכלל יחיד לידון בשעיר:"],[3,"שיכול","כלומר אילו לא נאמר מעם הארץ הייתי אומר משיח על העלם דבר עם שגגת מעשה יביא פר ועל שגגת מעשה לחודיה יביא כשבה או שעירה כהדיוט:"],[3,"ת\"ל מעם הארץ פרט למשיח","דאינו מביא בשגגת מעשה לחודה כלל והיינו דקאמרן בפרק דלעיל (הוריות דף ז:) יצא משיח שאין חטאו בשגגה דהיינו בשגגת מעשה:"],[4,"אלא נשיא הא בשגגת מעשה הוא מייתי","ומאי קא ממעט דקאמר מעם הארץ פרט לנשיא:"],[5,"ס\"ד אמינא","הואיל וחטא כשהוא הדיוט נייתי כשבה או שעירה כהדיוט:"],[5,"קמ\"ל","מעם הארץ פרט לנשיא דאינו מביא כשבה או שעירה:"],[5,"אלא לרבנן דאזלי בתר חטאה","ומייתי ודאי כשבה או שעירה כדתנן חטאו עד שלא נתמנו ואח\"כ נתמנו הרי אלו כהדיוטות:"],[5,"מאי איכא למימר","דממאי קא ממעט לנשיא דקתני פרט לנשיא:"],[6,"ס\"ד אמינא נצטרף","חצי זית בתרא לחצי זית קמא ולייתי כשבה או שעירה:"],[6,"קמ\"ל","מעם הארץ פרט לנשיא דכהאי גוונא לא מייתי כשבה או שעירה וכהאי גוונא נמי לא מייתי שעיר דהא לא מצטרפי כלל והוא הדין דמצי למימר סלקא דעתך אמינא נצטרף ונייתי שעיר אלא משום דקרא קא מישתעי בכשבה או שעירה:"],[7,"כגון שאכל חצי זית חלב כשהוא הדיוט ונתמנה ועבר","מנשיאותו והשלימו:"],[9,"אכל ספק חלב כשהוא הדיוט","דקא סבור דשומן הוא:"],[9,"ונתמנה ונודע לו על ספקו","שנודע לו לאחר שנתמנה שספק חלב אכל:"],[9,"מהו","מי מייתי אשם תלוי או לא:"],[10,"מדאישתני לודאי","דקאמר ר' שמעון דקודם לכן היו שוגגים שלא ידעו אם אכלו כלל ובההיא ליכא אשם תלוי אם נודע להם משנתמנו פטורים לפי שנשתנה גופם דהשתא נתמנו ומדאישתנו לקרבן ודאי אישתנו נמי לקרבן ספק ופטור ואין מביאין אשם תלוי:"],[10,"או דלמא כי אישתני לודאי","היינו טעמא דר' שמעון דפטר משום דאישתני קרבן דידיה דכשהוא הדיוט מביא כשבה או שעירה והשתא כי נתמנה משיח מביא פר ונשיא מביא שעיר:"],[10,"אבל הכא","כי נודע לו על ספק דנודע לו משנתמנה דספק חלב אכל:"],[10,"דלא אישתני קרבן דידיה","דעל ספק חטאת קבוע בין כשהוא הדיוט ובין כשהוא נשיא מביא אשם תלוי מודה רבי שמעון דמייתי אשם תלוי תיקו:"],[11,"מעם הארץ","מביא קרבן ולא כל עם הארץ:"],[11,"פרט למומר","שאין מקבלין מידו:"],[14,"אלא הכא באוכל נבילה לתאבון","דכי אין לו בשר דהיתרא אוכל חלב ונבלה ונתחלף לו לזה חלב בשומן ואכלו דסבור דשומן הוא קא מיפלגי ולכשנודע לו דחלב הוא רוצה להקריב קרבן ת\"ק סבר כיון דלתאבון אכיל במזיד מומר הוא ואין מקבלין מידו ור\"ש בר יוסי סבר כיון דבמזיד אי משכח היתרא לא אכיל איסורא שב מידיעתו קרינא ביה ולא מומר הוא ומקבלין מידו:"],[15,"","קתני אכל חלב שחוטה זה מומר והדר תני איזהו מומר מאי קאמר:"],[16,"להכעיס","דאית ליה היתרא ואכיל איסורא:"],[16,"הרי זה צדוקי","ושחיטתו לעבודת כוכבים:"],[16,"אוכל נבילה וטריפה שקצים ורמשים ושתה יין נסך","הואיל והני אוכלין הוו דברים שהנפש קצה בהם ודאי להכעיס הוא עושה וסתמו רע הוא:"],[16,"ר' יוסי בר רבי יהודה אומר אף הלובש כלאים","הרי זה מומר:"],[17,"מאי איכא","בין ת\"ק לרבי יוסי בר רבי יהודה כיון דאמר ת\"ק אכל חלב הרי זה מומר מה לי אוכל חלב מה לי לובש כלאים אידי ואידי דאורייתא ואסור:"],[17,"","ת\"ק סבר כלאים דאורייתא דומיא דחלב הוי מומר דהיינו ארוג ביה חוט של צמר וחוט של פשתים יחד על פני כולו:"],[17,"","ור' יוסי סבר אף הלובש נמי כלאים דרבנן הוי מומר דהיינו או שוע או טווי או נוז דהכי מפרשי רבנן שעטנז שוע טווי ונוז כדאמרינן במסכת נדה (דף סא:) ורבנן גזור בחד מנייהו שוע שמנפץ כאחת ועשה מהם לבד טווי שנטוה כאחת ותכף בו שתי תכיפות נוז שארוג אפי' חוט אחד של צמר בבגד פשתן או חוט אחד של פשתן בבגד צמר דכולהו אסור מדרבנן:"],[18,"חד אמר","האוכל חלב ונבילה לתאבון הרי זה מומר:"],[18,"להכעיס","דאית ליה היתרא ואפי' הכי אכיל איסורא צדוקי הוא:"],[18,"אכל פרעוש או יתוש הרי זה מומר","דהכא ודאי להכעיס קא עביד דלאו מידי דבר מיכל הוא וקתני הרי זה מומר ואינו צדוקי וקשיא למאן דאמר להכעיס צדוקי הוא:"],[18,"","לעולם אימא לך להכעיס צדוקי הוא והכא היינו טעמא דהוי מומר ולא הוי צדוקי משום דקאמר בעינא למיטעם טעמא דאיסורא שתאב לטעום דבר אסור ולא להכעיס קא עביד:"]],[]],[["מה להלן שאין על גביו אלא ה' אלהיו אף נשיא שאין על גביו אלא ה' אלהיו","בעא מיניה רבי מרבי חייא כגון אני מהו בשעיר אמר ליה הרי צרתך בבבל איתיביה מלכי ישראל ומלכי בית דוד אלו מביאים לעצמם ואלו מביאים לעצמם אמר ליה התם לא כייפי אהדדי הכא אנן כייפינן להו לדידהו","רב ספרא מתני הכי בעא מיניה רבי מרבי חייא כגון אני מהו בשעיר א\"ל התם שבט הכא מחוקק ותניא (בראשית מט, י) לא יסור שבט מיהודה זה ראש גולה שבבבל שרודה את ישראל במקל (בראשית מט, י) ומחוקק מבין רגליו אלו בני בניו של הלל שמלמדים תורה לישראל ברבים:","\u0001מתני׳\u0002 ואיזהו המשיח המשוח בשמן המשחה לא המרובה בבגדים אין בין כהן המשוח בשמן המשחה למרובה בגדים אלא פר הבא על כל המצות","ואין בין כהן משמש לכהן שעבר אלא פר יוה\"כ ועשירית האיפה","זה וזה שוים בעבודת יוה\"כ ומצווים על הבתולה ואסורים על האלמנה ואינם מטמאים בקרוביהם ולא פורעים ולא פורמים ומחזירין הרוצח:","\u0001גמ׳\u0002 ת\"ר שמן המשחה שעשה משה במדבר היו שולקים בו את העיקרים דברי רבי יהודה רבי יוסי אומר והלא לסוך את העקרים אינו סופק אלא שורין את העקרים במים ומציף עליו שמן וקולט את הריח וקפחו","אמר לו רבי יהודה וכי נס אחד נעשה בשמן המשחה והלא תחלתו שנים עשר לוגין וממנו היה נמשח משכן וכליו אהרן ובניו כל שבעת ימי המלואים וכולו קיים לעתיד לבוא שנאמר (שמות ל, לא) שמן משחת קדש יהיה זה לי לדורותיכם","תניא אידך (ויקרא ח, י) ויקח משה את שמן המשחה וימשח [את] המשכן [ואת] כל אשר בו רבי יהודה אומר שמן המשחה שעשה משה במדבר כמה נסים נעשו בו מתחלה ועד סוף תחלתו לא היה אלא שנים עשר לוגין ראה כמה יורה בולעת וכמה עקרים בולעים וכמה האור שורף ובו נמשח משכן וכליו ואהרן ובניו כל שבעת ימי המלואים ובו נמשחו כהנים גדולים ומלכים","ואפילו כהן גדול בן כהן גדול טעון משיחה ואין מושחים מלך בן מלך ואם תאמר מפני מה משחו את שלמה מפני מחלוקתו של אדוניה ואת יואש מפני עתליה ואת יהואחז מפני יהויקים שהיה גדול ממנו שתי שנים ואותו שמן קיים לעתיד לבוא שנאמר שמן משחת קדש יהיה זה לי לדורותיכם זה בגימטריא שנים עשר לוגין הוו","אמר מר ואפילו כהן גדול בן כהן גדול טעון משיחה מנלן דכתיב (ויקרא ו, טו) והכהן המשיח תחתיו מבניו נימא קרא והכהן מתחתיו מבניו מאי המשיח קמ\"ל דמבניו דכהן גדול אי הוי משיח הוי כהן גדול ואי לא לא הוי כהן גדול","אמר מר ואין מושחין מלך בן מלך מנלן אמר רב אחא בר יעקב דכתיב (דברים יז, כ) למען יאריך ימים על ממלכתו וגו' ירושה היא לכם ומנלן דכי איכא מחלוקת בעי משיחה ולאו כל דבעי מלכא מורית מלכותא לבניה אמר רב פפא אמר קרא הוא ובניו בקרב ישראל בזמן ששלום בישראל קרינא ביה הוא ובניו ואפילו בלא משיחה","תנא אף יהוא בן נמשי לא נמשח אלא מפני מחלוקתו של יורם ותיפוק ליה משום דראשון הוא חסורי מחסרא והכי קתני מלכי בית דוד משוחין מלכי ישראל אין משוחין מנלן אמר רבא אמר קרא (שמואל א טז, יב) קום משחהו כי זה וגו' זה טעון משיחה ואין אחר טעון משיחה","אמר מר אף יהוא בן נמשי לא נמשח אלא מפני מחלוקתו של יורם ומשום מחלוקתו של יורם בן אחאב נמעול בשמן כדאמר רב פפא באפרסמא דכיא ה\"נ באפרסמא דכיא","ואת יהואחז מפני יהויקים שהיה גדול ממנו שתי שנים ומי קשיש מיניה והכתיב (דברי הימים א ג, טו) ובני יאשיהו הבכור יוחנן השני יהויקים השלישי צדקיהו הרביעי שלום וא\"ר יוחנן הוא שלום הוא צדקיהו הוא יוחנן הוא יהואחז לעולם יהויקים קשיש ומאי בכור בכור למלכות","ומי מלכי זוטרי מקמי קשישי והא כתיב (דברי הימים ב כא, ג) ואת הממלכה נתן ליהורם כי הוא הבכור יהורם ממלא מקום אבותיו הוה יהויקים לאו ממלא מקום אבותיו הוה","אמר מר הוא שלום הוא צדקיהו הוא יוחנן הוא יהואחז והא חד חד קא חשיב דכתי' (דברי הימים א ג, טו) השלישי הרביעי מאי שלישי שלישי לבנים ומאי רביעי רביעי למלכות דמעיקרא מלך יהואחז ולבסוף יהויקים ולבסוף יכניה ולבסוף צדקיהו","ת\"ר הוא שלום הוא צדקיהו ולמה נקרא שמו שלום שהיה משולם במעשיו איכא דאמרי שלום ששלמה מלכות בית דוד בימיו ומה שמו מתניה שמו שנאמר (מלכים ב כד, יז) וימלך מלך בבל את מתניה דודו תחתיו ויסב את שמו צדקיהו א\"ל יה יצדיק עליך את הדין אם תמרוד בי (שנאמר (מלכים ב כה, ז) ויביאהו בבלה) וכתיב (דברי הימים ב לו, יג) וגם במלך נבוכדנצר מרד אשר השביעו באלהים"],[[0,"מה להלן שאין על גביו אלא ה' אלהיו","דבמלך קא משתעי קרא דכתיב שום תשים עליך מלך (דברים יז):"],[1,"כגון אני מהו בשעיר","כלומר נשיאות דידי מי הוי נשיאות מעליא דאילו הוינא בזמן שבית המקדש קיים מייתינא שעיר או לא:"],[1,"א\"ל הרי צרתך בבבל","ראש גולה שבבבל דהוי על גבך ואנן בעינן שאין על גביו אלא ה' אלהיו:"],[2,"התם שבט","דהיינו מקל כמו כי תכנו בשבט לא ימות (משלי כ״ג:י״ג):"],[2,"והכא מחוקק","חכם:"],[3,"מתני' איזה הוא המשיח","שמביא פר בהוראה זה המשוח בשמן המשחה:"],[3,"ולא מרובה בבגדים","שבבית שני שלא היה להם שמן המשחה:"],[3,"אין בין כהן משוח בשמן המשחה למרובה בגדים אלא פר הבא על כל המצות","שמרובה בגדים אינו מביא פר העלם דבר לא משלו ולא משל צבור אבל מביא כשבה או שעירה דיחיד:"],[4,"ואין בין כהן המשמש","והיינו ראשון שחזר לעבודתו ולאחר שחזר הוי פר של יוה\"כ שלו ועשירית האיפה שלו:"],[5,"וזה וזה","בין כהן המשמש דהיינו ראשון שחזר לעבודתו ובין כהן שעבר דהיינו שני שמינו תחתיו דלאחר (שנעבר) [שחזר] הראשון מעבירין השני:"],[5,"שוים בעבודת היום","דמקרבי קרבנות היום ביוה\"כ איזה שירצה:"],[6,"גמ' שמן המשחה שעשה משה","כדכתיב שמן משחת קדש יהיה זה לי (שמות ל׳:ל״א):"],[6,"בו שולקין את העקרים","אותם שרשים של בשמים האמורים בפרשה דכתיב ואתה קח לך בשמים ראש מר דרור וגו':"],[6,"והלא לסוך בו את העקרים אינו מספיק","לפי שהשמן לא היה אלא שנים עשר לוגין כדמפרש לקמן והעקרים היו מרובים ואפילו בסיכה היא נבלע בעקרים כל שכן בשליקה:"],[6,"אלא שורה את העקרים במים","ברישא שהיו מתמלאים מן המים ושוב לא יהו בולעים מן השמן כל כך:"],[6,"ומציף עליהן שמן","לאחר שהוציאם מן המים כדי שיקלוט השמן מריח הבשמים:"],[6,"וקפחו","ומוציא השמן לאלתר וקפחו כמו קפחתי את הרועה (יומא דף פג:):"],[9,"טעון משיחה","ואי לא משוח בשמן לא הוי כה\"ג:"],[9,"מפני מחלוקתו","דהיכא דאיכא מחלוקת בעי משיחה:"],[11,"ממלכתו הוא ובניו בקרב ישראל","משמע ירושה היא להם כאדם שמוריש ירושה לבניו:"],[11,"ולא כל דבעי מלכא מורית לבניה מלכותא","אפילו בלא משיחה:"],[11,"ירושה היא","בזמן ששלום בישראל:"],[12,"משום דמלך ראשון הוא","ממשפחתו דאינו מלך בן מלך:"],[12,"זה","דמלכות בית דוד טעון משיחה:"],[12,"ואין אחר","שאינו ממלכי בית דוד טעון משיחה:"],[13,"משום מחלוקתו של יורם נמעול בשמן המשחה","דאמרינן לעיל דמלכי ישראל אין מושחין ממנו:"],[13,"באפרסמא דכיא","דלא הוי משמן המשחה:"],[14,"ומאי בכור","דקרי ליה הבכור יוחנן:"],[14,"בכור למלכות","שמלך ראשון:"],[15,"יורם ממלא מקום אבותיו הוה","דכי מלך אכתי הוה צדיק ממלא מקום אבותיו הוה ואחר כך החמיץ:"],[17,"משולם במעשיו","דצדיק גמור הוה בעל מעשים טובים:"],[17,"אמר לו","נבוכד נצר יה יצדיק עליך את הדין אם תמרוד בי:"]],[]],[["ומי הוה שמן המשחה והתניא משנגנז ארון נגנז שמן המשחה וצנצנת המן ומקלו של אהרן שקדיה ופרחיה וארגז ששלחו פלשתים דורון לישראל שנאמר (שמואל א ו, ח) ואת כלי הזהב אשר השבותם לו אשם תשימו בארגז מצדו ושלחתם אותו והלך","ומי גנזו יאשיהו מלך יהודה גנזו שראה שכתוב בתורה (דברים כח, לו) יולך ה' אותך ואת מלכך וגו' צוה וגנזום שנאמר (דברי הימים ב לה, ג) ויאמר ללוים המבינים לכל ישראל הקדושים לה' תנו את ארון הקדש בבית אשר בנה שלמה בן דוד מלך ישראל אין לכם משא בכתף עתה עבדו את ה' אלהיכם ואת עמו ישראל","ואמר רבי אלעזר אתיא שם שם אתיא משמרת משמרת אתיא דורות דורות אמר רב פפא באפרסמא דכיא","ת\"ר כיצד מושחין את המלכים כמין נזר ואת הכהנים כמין כי מאי כמין כי אמר רב מנשיא בר גדא כמין כף יוני","תני חדא בתחלה מוצקין שמן על ראשו ואח\"כ נותנין לו שמן בין ריסי עיניו ותניא אחריתי בתחלה נותנין לו שמן בין ריסי עיניו ואח\"כ מוצקים לו שמן על ראשו תנאי היא איכא דאמרי משיחה עדיפא ואיכא דאמרי יציקה עדיפא","מ\"ט דמאן דאמר יציקה עדיפא דכתיב (ויקרא ח, יב) ויצוק משמן המשחה על ראש אהרן וימשח אותו לקדשו ומאן דאמר משיחה עדיפא מ\"ט קסבר שכן אתה מוצא אצל כלי שרת והכתיב ויצוק ובסוף וימשח הכי קאמר מאי טעם ויצוק משום דוימשח","ת\"ר (תהלים קלג, ב) כשמן הטוב [וגו'] יורד על הזקן זקן אהרן וגו' כמין שני טפי מרגליות היו תלויות לאהרן בזקנו אמר רב פפא תנא כשהוא מספר עולות ויושבות לו בעיקר זקנו ועל דבר זה היה משה דואג אמר שמא חס ושלום מעלתי בשמן המשחה יצתה בת קול ואמרה כשמן הטוב וגו' (תהלים קלג, ג) כטל חרמון מה טל חרמון אין בו מעילה אף שמן המשחה שבזקן אהרן אין בו מעילה","ועדיין היה אהרן דואג אמר שמא משה לא מעל אבל אני מעלתי יצתה בת קול ואמרה לו (תהלים קלג, א) הנה מה טוב ומה נעים שבת אחים גם יחד מה משה לא מעל אף אתה לא מעלת","ת\"ר אין מושחים את המלכים אלא על המעיין כדי שתמשך מלכותם שנא' (מלכים א א, לג) ויאמר המלך להם קחו עמכם את עבדי אדוניכם [וגו'] והורדתם אותו אל גחון","אמר רבי אמי האי מאן דבעי לידע אי מסיק שתיה אי לא ניתלי שרגא בעשרה יומי דבין ראש השנה ליום הכפורים בביתא דלא נשיב זיקא אי משיך נהוריה נידע דמסיק שתיה","ומאן דבעי למיעבד בעיסקא ובעי למידע אי מצלח אי לא מצלח לירבי תרנגולא אי שמין ושפר מצלח","האי מאן דבעי למיפק [לאורחא] ובעי למידע אי חזר ואתי לביתא אי לא ניקום בביתא דחברא אי חזי בבואה דבבואה לידע דהדר ואתי לביתא ולאו מלתא היא דלמא חלשא דעתיה ומיתרע מזליה אמר אביי השתא דאמרת סימנא מילתא היא [לעולם] יהא רגיל למיחזי בריש שתא קרא ורוביא כרתי וסילקא ותמרי","אמר להו רב משרשיא לבריה כי בעיתו מיעל ומיגמרי קמי רבייכו גרסו מתניתא ועלו לקמי רבייכו וכי יתביתו קמיה חזו לפומיה דכתיב (ישעיהו ל, כ) והיו עיניך רואות את מוריך וכי גרסיתו גרסו על נהרא דמיא דכי היכי דמשכן מיא משכן שמעתתייכו ותיבו אקילקלי דמתא מחסיא ולא תיבו אפדני דפומבדיתא טב גלדנא סריא [דמתא מחסיא למיכל] מכותחא דרמי כיפי","(שמואל א ב, א) רמה קרני באלהי רמה קרני ולא רמה פכי דוד ושלמה שנמשחו בקרן נמשכה מלכותן שאול ויהוא שנמשחו בפך לא נמשכה מלכותן:","המשוח בשמן המשחה וכו': ת\"ר משיח יכול מלך ת\"ל כהן אי כהן יכול מרובה בגדים ת\"ל משיח אי משיח יכול משוח מלחמה תלמוד לומר והכהן המשיח שאינו משיח על גביו","מאי משמע כדאמר רבא הירך המיומנת שבירך הכא נמי המשיח המיומן שבמשוחים","אמר מר משיח יכול מלך מלך פר הוא דמייתי שעיר הוא דמייתי איצטריך ס\"ד אמינא על שגגת מעשה יביא שעיר על העלם דבר יביא פר קמ\"ל:","אין בין משוח בשמן המשחה כו': מתניתין דלא כרבי מאיר דאי ר\"מ הא תניא מרובה בגדים מביא פר הבא על כל המצות דברי ר\"מ ולא הודו לו חכמים","מ\"ט דר\"מ דתניא (ויקרא ד, ג) משיח אין לי אלא משוח בשמן המשחה מרובה בגדים מנין תלמוד לומר הכהן המשיח","במאי אוקימתיה כרבנן"],[[0,"ומי הוה שמן המשחה","בימי יהואחז דקתני ויהואחז נמשח מפני יהויקים:"],[0,"והתניא משנגנז הארון וכו'","מדכתיב תשימו בארגז מצדו דארגז בצד ארון קאי אלמא בהדי ארון נגנז ומדקאמר יאשיהו תנו את ארון ה' בבית וגו' משמע שצוה לגונזו:"],[1,"אין לכם משא בכתף","ואמרינן במסכת שקלים אמר להם אם גולה עמכם שוב אינכם מחזירין אותו בכתפיכם צוה לגונזו:"],[2,"אתיא שם שם","דכתיב בארון ונועדתי לך שם ודברתי אתך מעל הכפורת וגו' וכתיב ונועדתי שמה לבני ישראל וכתיב בצנצנת המן ותן שמה מלא העומר מן מה ארון נגנז אף צנצנת המן נגנז:"],[2,"אתיא דורות דורות","דכתיב בצנצנת המן והנח אותו לפני ה' למשמרת לדורותיכם וכתיב בשמן המשחה שמן משחת קדש יהיה זה לי לדורותיכם מה צנצנת המן נגנז אף שמן המשחה נגנז:"],[2,"משמרת משמרת","דכתיב בצנצנת המן דהוי נגנז למשמרת לדורותיכם וכתיב במקלו של אהרן למשמרת לאות לבני מרי וגו' מה צנצנת המן נגנז אף מקלו של אהרן נגנז:"],[2,"אמר רב פפא באפרסמא דכיא","משחו את יהואחז:"],[3,"כמין נזר","דהדר ליה הודרני באצבעתיה ככלילא (כזה):"],[3,"כמין כף יוני","שמתחיל למשוח באצבעו בין ריסי עיניו ומושך אצבעו על הראש והולך עד שמגיע לעורף ככף יוני כזה [ציור] :"],[4,"נותנים לו שמן בין ריסי עיניו","ושם מושחים לכהן כמין כף יוני כדפרישנא:"],[5,"מאן דאמר יציקה עדיפא דכתיב ויצוק משמן המשחה","והדר וימשח:"],[5,"שכן אתה מוצא אצל כלי שרת","דהוה משיחה ולא יציקה:"],[5,"מה טעם ויצוק משום דוימשח","כבר:"],[6,"כשהוא מספר","כשהיה מדבר עם אחרים:"],[6,"עולות ויושבות","בעקרי זקנו כדי שלא יפלו:"],[6,"שמא ח\"ו מעלתי בשמן המשחה","שנגעתי בו כשהלבשתיו:"],[7,"ואני מעלתי","שמא נפל עלי מן השמן במקום שאין ראוי למשיחה ומעלתי:"],[8,"והורדתם אותו אל גיחון","אלמא בעי משיחה על המעיין:"],[9,"ניתלי","ידליק:"],[9,"אי משוך נהוריה","שדולק כל זמן שהשמן בתוכו:"],[10,"לירבי תרנגולא","על שם ההוא עיסקא:"],[10,"שמין ושפיר","שמשמנת ומשבחת:"],[11,"ביתא דחברא","בית חשוך:"],[11,"ולאו מילתא היא","דזימנא דאף על גב דלית ליה בבואה דבבואה הדר אתי ואפי' הכי לא ליעבד הכי דדלמא לא חזי בבואה דבבואה חלשה דעתיה ומתרע מזליה ולא הדר אתי [משום דמיתרע מזליה דאי לא הוה עביד הכי לא הוה מיתרע מזליה והדר אתי] הלכך לא ליעביד:"],[11,"קרא ורוביא כרתי וסילקא ותמרי","דהני גדלי לעגל טפי משאר ירקות קרא דלעת רוביא תלתן:"],[12,"גרסו מתניתא","מעיקרא כי היכי דתהוי מרגלא מילתא בפומייכו ותהוון ידעין למשאל ליה:"],[12,"ממשכן שמעתא","דלא ליפסוק מפומייכו כמעין זה שמושך והולך:"],[12,"דמתא מחסיא","הוו תלמידי חכמים ראויים להוראה ותרבות יפה היה בהם אבל בפומבדיתא לא הוי תרבות מעליא כל כך וקאמר ליה מוטב לו לדור באשפה במתא מחסיא מלדור באפדנא בפומבדיתא:"],[12,"גילדנא סריא","מוטב לאכול דג קטן מוסרח כדאמרינן בפ\"ק דמו\"ק (דף יא:) כוורא סמוך למיסרחיה מעלי:"],[12,"מכותחא דרמי כיפי","אפילו מכותח שהוא משובח וחזק שמשבר את האבן כששופכים הימנו אעפ\"כ לא תאכל הימנו כדאמרינן בפרק (ערבי פסחים) [ואלו עוברין (פסחים מב.)] שלשה דברים נאמרו בכותח מטמטם את הלב וכו' כיפי סלעים כדמתרגמינן סלע כיפא אית דמפרשי מוטב תאכל גילדנא סריא שאין דמיהם יקרים מכותח שאוכלים אותו עשירים ושרים הדרים ברמי כיפי כלומ' במגדלים וחומות גדולות לפי שדמיהם יקרים:"],[14,"אם הכהן המשיח יכול מלך","יביא פר שהיה משוח ת\"ל כהן:"],[15,"המיומן שבמשוחים","דהיינו כהן גדול:"],[18,"","מרובה בגדים מנין תלמוד לומר והביא הכהן המשיח:"]],[]],[["אימא סיפא אין בין כהן משמש לכהן שעבר אלא פר יום הכפורים ועשירית האיפה אתאן לרבי מאיר דתניא אירע בו פסול בכהן גדול ועבר ומינו כהן אחר תחתיו הראשון חוזר לעבודתו והשני כל מצות כהונה עליו דברי ר\"מ [רבי יוסי אומר ראשון חוזר לעבודתו ושני אינו ראוי לא לכהן גדול ולא לכהן הדיוט]","אמר רבי יוסי מעשה ביוסף בן אילים מצפורי שאירע בו פסול בכהן גדול (ועבר ומינו אחר תחתיו ולא הניחוהו אחיו הכהנים להיות לא כהן גדול ולא כהן הדיוט כהן גדול משום איבה כהן הדיוט משום מעלין בקדש ואין מורידין","רישא רבנן וסיפא ר\"מ אמר רב חסדא אין רישא רבנן וסיפא ר\"מ רב יוסף אמר רבי היא ונסיב לה אליבא דתנאי","רבא אמר ר\"ש היא וסבר לה כר\"מ בחדא ופליג עליה בחדא","דתניא דברים שבין כהן גדול לכהן הדיוט אלו הם פר הבא על כל המצות ופר יוה\"כ ועשירית האיפה ולא פורע ולא פורם אבל הוא פורם מלמטה וההדיוט מלמעלה ואין מטמא לקרובים ומוזהר על הבתולה ואסור באלמנה ומחזיר את הרוצח","ומקריב אונן ואינו אוכל [ואינו חולק] מקריב חלק בראש ונוטל חלק בראש ומשמש בשמונה כלים וכל עבודת יום הכפורים אינה כשרה אלא בו ופטור על טומאת מקדש וקדשיו","וכולן נוהגין במרובה בגדים חוץ מפר המביא על כל המצות וכולן נוהגין במשיח שעבר חוץ מפר יוה\"כ ועשירית האיפה וכולן אין נוהגין במשוח מלחמה חוץ מה' דברים האמורים בפרשה לא פורע ולא פורם ואין מטמא לקרובים ומוזהר על הבתולה ואסור באלמנה ומחזיר את הרוצח דברי רבי יהודה וחכמים אומרים אינו מחזיר","והאי ממאי דר\"ש היא א\"ר פפא מאן שמעת ליה דאמר פטור על טומאת מקדש וקדשיו ר\"ש:","חוץ מה' דברים האמורים בפרשה: מה\"מ דת\"ר (ויקרא כא, י) והכהן הגדול מאחיו זה כהן גדול אשר יוצק על ראשו שמן המשחה זה משוח מלחמה ומלא את ידו ללבוש את הבגדים זה מרובה בגדים על כולן הוא אומר ראשו לא יפרע ובגדיו לא יפרום ועל כל נפשות מת לא יבא","יכול יהו כולן מקריבין אוננים ת\"ל (ויקרא כא, יב) כי נזר שמן משחת אלהיו עליו עליו ולא על חבירו ואחר שחלקו הכתוב יכול לא יהא מצווה על הבתולה ת\"ל והוא","כתנאי (ויקרא כא, יג) והוא אשה בבתוליה יקח אחר שחלק הכתוב ריבה דברי רבי ישמעאל רבי עקיבא אומר אין לי אלא שעבר מחמת קריו מחמת מומין מנין ת\"ל והוא","בעא מיניה רבא מרב נחמן משיח שנצטרע מהו באלמנה מידחא דחי או מיפטר פטר לא הוה בידיה","זימנין הוי יתיב רב פפא וקמבעיא ליה א\"ל הונא בריה דרב נחמן לרב פפא תנינא אין לי אלא שעבר מחמת קריו עבר מחמת מומין מנין ת\"ל והוא קם נשקיה ברישיה ויהיב ליה ברתיה:","\u0001מתני׳\u0002 כהן גדול פורם מלמטה וההדיוט מלמעלה כהן גדול מקריב אונן ולא אוכל וההדיוט לא מקריב ולא אוכל:","\u0001גמ׳\u0002 אמר [רב] למטה למטה ממש למעלה למעלה ממש ושמואל אמר למטה למטה מקמי שפה למעלה למעלה מקמי שפה וזה וזה בצואר","מיתיבי על כל המתים כולן רצה מבדיל קמי שפה שלו רצה אינו מבדיל קמי שפה שלו על אביו ועל אמו מבדיל כיון דבעלמא הוי קרע קרי כאן בגדיו לא יפרום","שמואל כרבי יהודה סבירא ליה דאמר כל קרע שאינו מבדיל שפה שלו אינו אלא קרע של תפלות ומי אית ליה לר\"י קריעה בכהן גדול","והא תניא אילו נאמר ראש לא יפרע ובגד לא יפרום הייתי אומר בראש ובגד של סוטה הכתוב מדבר ת\"ל (ויקרא כא, י) את ראשו לא יפרע ובגדיו לא יפרום שאינו בפריעה ופרימה כל עיקר דברי רבי יהודה רבי ישמעאל אומר אינו פורם כדרך שבני אדם פורמין אלא הוא מלמטה וההדיוט מלמעלה","שמואל סבר לה כר\"י בחדא ופליג עליה בחדא:","\u0001מתני׳\u0002 כל התדיר מחבירו קודם את חבירו וכל המקודש מחבירו קודם את חבירו פר המשיח ופר העדה עומדים פר המשיח קודם לפר העדה בכל מעשיו:","\u0001גמ׳\u0002 מנא הני מילי אמר אביי דאמר קרא (במדבר כח, כג) מלבד עולת הבקר אשר לעולת התמיד (למה לי) מכדי כתיב עולת הבקר עולת התמיד למה לי הכי קאמר רחמנא כל דתדירה קדמה:","וכל המקודש מחבירו הוא קודם את חבירו: מנלן דתנא דבי רבי ישמעאל וקדשתו לכל דבר שבקדושה לפתוח ראשון ולברך ראשון וליטול מנה יפה ראשון:"],[[0,"אימא סיפא אין בין כהן המשמש לכהן שעבר","דהיינו שני:"],[0,"אלא פר יום הכפורים ועשירית האיפה","דמשל ראשון הן באין הא לכל שאר דבריהם זה וזה שוין דשני נמי כל מצות כהונה גדולה עליו:"],[0,"אתאן לרבי מאיר דתניא וכו'","עבר דברייתא לא דמי לשעבר דמתניתין:"],[2,"רבי היא ונסיב לה אליבא דתנאי","בחדא סבר לה כרבי מאיר וסתמה כרבי מאיר וברישא סבר לה כרבנן וסתמה כרבנן:"],[3,"רבי שמעון סבר לה כרבי מאיר בחדא","דכהן שעבר דשני כל מצות כהונה עליו חוץ מפר יוה\"כ ועשירית האיפה:"],[3,"ופליג עליה בחדא","דאילו רבי מאיר סבר מרובה בגדים מביא פר הבא על כל המצות דהיינו פר העלם דבר של צבור ואילו ר' שמעון סבר דאינו מביא פר הבא על כל המצות כדתנן אין בין משוח בשמן המשחה למרובה בגדים אלא פר הבא על כל המצות:"],[5,"ונוטל חלק בראש","אע\"פ שאינו מקריב:"],[5,"ומשמש בח' כלים","וההדיוט בד':"],[6,"וכולם נוהגין במשיח שעבר","דהיינו שני:"],[6,"חוץ מפר יוה\"כ ועשירית האיפה","דאין בין כהן המשמש לכהן שעבר אלא פר יוה\"כ ועשירית האיפה:"],[7,"","מאן שמעת ליה דאמר פטור על טומאת מקדש וקדשיו רבי שמעון:"],[9,"ת\"ל כי נזר שמן משחת (קדש) אלהיו עליו ולא על משיח חבירו","למעוטי משוח מלחמה דאין מקריב אונן אבל כהן גדול מקריב אונן בין מרובה בגדים ובין ראשון שחוזר לעבודה ואפילו שני מפני שהן בכלל כהונה [גדולה] לאפוקי משוח מלחמה דלאו בכלל כהונה גדולה הוא:"],[9,"ואחר שחלקו הכתוב","למשוח מלחמה שאינו מקריב אונן ככהן גדול יכול לא יהא מצווה על הבתולה:"],[10,"אלא שעבר מחמת קריו","דהוי כהן גדול מעליא שהרי חוזר לעבודתו הוא:"],[10,"עבר מחמת מומו","דאינו חוזר לעבודתו מפני המום מנין שמצווה על הבתולה תלמוד לומר והוא:"],[11,"משיח שנצטרע","כלומר כהן גדול שנצטרע מהו באלמנה:"],[11,"","מי אמרינן כהונה גדולה מדחא דחי להאי מאלמנה או דלמא כהונה גדולה מיפטר פטר ליה להאי מאלמנה וכי נצטרע דליכא כהונה גדולה לא פטר ומותר באלמנה:"],[12,"עבר מחמת מומו מנין תלמוד לומר והוא","דאפילו עבר ראשון מחמת מומו אסור באלמנה וכי נצטרע אין לך מום גדול מזה ושמעי' מינה דאפילו הכי אסור באלמנה:"],[14,"למטה למטה ממש","דהיינו בשפת חלוקו:"],[14,"למעלה למעלה ממש","בצואר בשפה במפתח חלוקו:"],[14,"למטה מקמי שפה","שקורעין למטה משפה לפיו שהוא למטה מבית הצואר:"],[14,"למעלה מקמי שפה","שקורעין בית הצואר ממש:"],[15,"כיון דבעלמא הוי קרע","דאם רצה אינו מבדיל אלא קורעין למטה משפה ויצא ידי קריעה אם כן כהן גדול היכי מצי קרע למטה מקמי שפה קרי כאן בגדיו לא יפרום:"],[16,"אינו אלא קרע של תפלות","דבעלמא לא יצא ידי קריעה הלכך מותר בכהן גדול:"],[17,"בראש ובגד של סוטה","דכתיב ופרע את ראש האשה (במדבר ה׳:י״ח) ותנן במס' סוטה (דף ז.) הכהן אוחז בבגדיה אם נקרעו נקרעו ואם נפרמו נפרמו:"],[18,"שמואל סבר לה בחדא כרבי יהודה","דכל שאינו מבדיל מקמי שפה הוי קרע של תפלות:"],[18,"ופליג עליה בחדא","דאילו רבי יהודה סבר דכהן גדול אינו בפריעה ופרימה כל עיקר ושמואל סבר דפורם מלמטה למטה מקמי שפה:"],[20,"למה לי למכתב אשר לעולת התמיד","אלא לכל דתדירא בכל מקום היא קדמה דזה בנה אב דבכל מקום תדיר קודם דמשמע אשר לעולת התמיד שהיתה כבר:"],[21,"לפתוח ראשון","לקרות בתורה:"],[21,"ולברך ראשון","בזמון:"]],[]],[["פר כהן משוח ופר עדה כו': מנא הני מילי דת\"ר (ויקרא ד, כא) ושרף אותו כאשר שרף את הפר הראשון מה ת\"ל הראשון שיהא ראשון קודם לפר העדה בכל מעשיו","ת\"ר פר כהן משיח ופר העדה עומדים פר כהן משיח קודם לפר העדה בכל מעשיו הואיל ומשיח מכפר ועדה מתכפרת דין הוא שיקדים המכפר למתכפר וכן הוא אומר (ויקרא טז, יז) וכפר בעדו ובעד ביתו ובעד כל קהל ישראל","פר העלם דבר של צבור קודם לפר של עבודת כוכבים מ\"ט האי חטאת והאי עולה ותניא (ויקרא ה, ח) והקריב את אשר לחטאת ראשונה מה ת\"ל אם ללמד שתהא חטאת ראשונה הרי כבר נאמר ואת השני יעשה עולה כמשפט אלא זה בנה אב שיהו כל חטאות קודמות לעולות הבאים עמהם וקיי\"ל דאפילו חטאת העוף קודמת לעולת בהמה","פר עבודת כוכבים קודם לשעיר עבודת כוכבים אמאי האי חטאת והאי עולה אמרי במערבא משמיה דרבא בר מרי חטאת עבודת כוכבים חסירא אל\"ף (במדבר טו, כד) לחטת כתיב רבא אמר כמשפט כתיב ביה","שעיר עבודת כוכבים קודם לשעיר נשיא מ\"ט האי צבור והאי יחיד שעיר נשיא קודם לשעירת יחיד מ\"ט האי מלך והאי הדיוט","שעירת יחיד קודמת לכבשת יחיד והא תניא כבשת יחיד קודמת לשעירת יחיד אמר אביי תנאי היא מר סבר שעירה עדיפא שכן נתרבתה אצל עבודת כוכבים ביחיד ומר סבר כבשה עדיפא שכן נתרבתה באליה","עומר קודם לכבש הבא עמו שתי הלחם קודמים לכבשים הבאים עמהם זה הכלל דבר הבא בגין ליום קודם לדבר הבא בגין לחם:","\u0001מתני׳\u0002 האיש קודם לאשה להחיות ולהשב אבדה והאשה קודמת לאיש לכסות ולהוציא מבית השבי בזמן ששניהם עומדים בקלקלה האיש קודם לאשה:","\u0001גמ׳\u0002 ת\"ר היה הוא ואביו ורבו בשבי הוא קודם לרבו ורבו קודם לאביו אמו קודמת לכולם","חכם קודם למלך ישראל חכם שמת אין לנו כיוצא בו מלך ישראל שמת כל ישראל ראוים למלכות","מלך קודם לכהן גדול שנאמר (מלכים א א, לג) ויאמר המלך (אליהם) [להם] קחו עמכם (או מעבדי) [את עבדי] אדוניכם וגו'","כהן גדול קודם לנביא שנאמר (מלכים א א, לד) ומשח אותו שם צדוק הכהן ונתן הנביא הקדים צדוק לנתן ואומר (זכריה ג, ח) שמע נא יהושע הכהן הגדול אתה ורעיך וגו' יכול הדיוטות היו ת\"ל (זכריה ג, ח) כי אנשי מופת המה ואין מופת אלא נביא שנאמר (דברים יג, ב) ונתן אליך אות או מופת","משוח בשמן המשחה קודם למרובה בגדים מרובה בגדים קודם למשיח שעבר מחמת קריו משיח שעבר מחמת קריו קודם לעבר מחמת מומו עבר מחמת מומו קודם למשוח מלחמה משוח מלחמה קודם לסגן","סגן קודם לאמרכל מאי אמרכל אמר רב חסדא אמר כולא אמרכל קודם לגזבר גזבר קודם לראש משמר ראש משמר קודם לראש בית אב ראש בית אב קודם לכהן הדיוט","איבעיא להו לענין טומאה סגן ומשוח מלחמה איזה מהם קודם","אמר מר זוטרא בריה דרב נחמן ת\"ש דתניא סגן ומשוח מלחמה שהיו מהלכים בדרך ופגע בהם מת מצוה מוטב שיטמא משוח מלחמה ואל יטמא סגן שאם יארע בו פסול בכהן גדול נכנס הסגן ומשמש תחתיו והתניא משוח מלחמה קודם לסגן אמר רבינא כי תניא ההיא להחיותו:","\u0001מתני׳\u0002 כהן קודם ללוי לוי לישראל ישראל לממזר וממזר לנתין ונתין לגר וגר לעבד משוחרר אימתי בזמן שכולם שוים אבל אם היה ממזר תלמיד חכם וכהן גדול עם הארץ ממזר תלמיד חכם קודם לכהן גדול עם הארץ:","\u0001גמ׳\u0002 כהן קודם ללוי שנאמר (דברי הימים א כג, יג) (ובני) [בני] עמרם אהרן ומשה ויבדל אהרן (להקריב) [להקדישו] קדש (הקדשים) [קדשים] לוי קודם לישראל שנאמר (דברים י, ח) בעת ההיא הבדיל ה' את שבט הלוי (מתוך) וגו'","ישראל קודם לממזר שזה מיוחס וזה אינו מיוחס ממזר קודם לנתין זה בא מטפה כשרה וזה בא מטפה פסולה נתין קודם לגר זה גדל עמנו בקדושה וזה לא גדל עמנו בקדושה גר קודם לעבד משוחרר זה היה בכלל ארור וזה לא היה בכלל ארור:","אימתי בזמן שכולן שוין כו': מה\"מ א\"ר אחא ברבי חנינא דאמר קרא (משלי ג, טו) יקרה היא מפנינים מכהן גדול שנכנס לפני ולפנים","תניא רשב\"י אומר בדין הוא שיקדים עבד משוחרר לגר שזה גדל עמנו בקדושה וזה לא גדל עמנו בקדושה אלא זה היה בכלל ארור וזה לא היה בכלל ארור","שאלו תלמידיו את רבי אלעזר ברבי צדוק מפני מה הכל רצין לישא גיורת ואין הכל רצין לישא משוחררת אמר להם זו היתה בכלל ארור וזו לא היתה בכלל ארור דבר אחר זו היתה בחזקת שמור וזו לא היתה בחזקת שמור","שאלו תלמידיו את רבי אלעזר מפני מה הכלב מכיר את קונו וחתול אינו מכיר את קונו אמר להם ומה האוכל ממה שעכבר אוכל משכח האוכל עכבר עצמו עאכ\"ו","שאלו תלמידיו את ר\"א מפני מה הכל מושלים בעכברים מפני שסורן רע מאי היא רבא אמר אפילו גלימי גייצי"],[[0,"","פרשת פר כהן משיח כתיבא ברישא והדר כתיבא פר העלם דבר של צבור ועשה לפר כאשר עשה לפר החטאת דהיינו לפר כהן משיח למה ליה למיהדר וכתב כאשר שרף את הפר הראשון:"],[1,"וכפר בעדו","והדר ובעד ביתו ובעד כל קהל ישראל:"],[2,"","פר דעבודת כוכבים הוי עולה:"],[3,"חסירא אל\"ף","למימרא דעולה קדמה:"],[3,"כמשפט כתיב ביה","בפר דעבודת כוכבים דבתר כתיבה אזלינן ועולה ברישא כתיבא:"],[5,"שעיר יחיד קודם לכבשת יחיד","כגון שהיו שנים זה הביא כשבה וזה הביא שעירה:"],[5,"שכן נתרבתה באליה","דעז אינה טעונה אליה:"],[6,"בגין יום","בגלל יום כבש גלל עומר וכבשים בגלל שתי הלחם:"],[7,"מתני' עומדים בקלקלה","האיש למשכב זכור:"],[8,"גמ' אמו קודמת לכולם","דאית לה זילותא טפי:"],[9,"[חכם קודם למלך ישראל","שאין כל ישראל ראוין לחכמה אבל מלך כל ישראל ראוין למלכות]:"],[10,"מלך קודם לכהן גדול","מדאמר מלך לכהן גדול קחו עמכם מעבדי אדוניכם [וע\"כ אנפשיה קאמר] אלמא מלך עדיף:"],[13,"אמרכלא","שממונה על כולם ואין משיבין על דבריו:"],[13,"גזבר","הממונה על האוצרות שבמקדש:"],[14,"איבעיא להו לענין טומאה","ליטמא למת מצוה סגן ומשוח מלחמה אי זה מהם קודם:"],[15,"להחיותו","הוא קודם לסגן משום דצבור צריכים לו למשוח מלחמה לצורך מלחמה טפי מסגן:"],[17,"דכתיב ויבדל אהרן","אלמא כהן עדיף מלוי:"],[18,"[בכלל ארור","כנען לא מצא נח קללה לכנען גדולה מזו שיהא עבד לאחיו מכאן שכל עבד הרי הוא בכלל ארור]:"],[21,"הכל רוצין לישא גיורת","שמתרצין לישא גיורת מלישא משוחררת:"],[21,"משוחררת לא היתה בחזקת שמור","דסתם שפחה מופקרת לשון אחר גיורת בעיא לאיגיורי ומשמרת עצמה לפי שבדעתה להתגייר אבל שפחה אין בידה לשחרר עצמה ואינה משמרת עצמה:"],[23,"מפני מה הכל מושלין בעכברים","כלומר מפני מה נתנה מפלה יתירה לעכברים שנרדפין תדיר תדיר:"],[23,"אמר להם מפני שסורן רע","שיצר לבם רע הוא יותר מדאי סורו שר שלהם כדאמר (ב\"מ דף נט:) בגר שסורו רע דהיינו יצר הרע ששר שלו רע הוא:"],[23,"מאי היא","היכי הוי סורן רע:"],[23,"אמר רבא אפילו גלימי","דלאו מאכל ולית בהו הנאה אפי' הכי גייצי להו:"],[23,"גייצי","נושכין:"]],[]],[["רב פפא אמר אפילו שופתא מרא גייצי","ת\"ר חמשה דברים משכחים את הלימוד האוכל ממה שאוכל עכבר וממה שאוכל חתול והאוכל לב של בהמה והרגיל בזיתים והשותה מים של שיורי רחיצה והרוחץ רגליו זו על גבי זו ויש אומרים אף המניח כליו תחת מראשותיו חמשה דברים משיבים את הלימוד פת פחמין וכל שכן פחמין עצמן והאוכל ביצה מגולגלת בלא מלח והרגיל בשמן זית והרגיל ביין ובשמים והשותה מים של שיורי עיסה ויש אומרים אף הטובל אצבעו במלח ואוכל","הרגיל בשמן זית מסייע ליה לרבי יוחנן דאמר רבי יוחנן כשם שהזית משכח לימוד של שבעים שנה כך שמן זית משיב לימוד של שבעים שנה:","והרגיל ביין ובשמים: מסייע ליה לרבא דאמר רבא חמרא וריחני פקחין:","והטובל אצבעו במלח: אמר ר\"ל ובאחת כתנאי ר' יהודה אומר אחת ולא שתים רבי יוסי אומר שתים ולא שלש וסימניך קמיצה","עשרה דברים קשים ללימוד העובר תחת האפסר [הגמל] וכל שכן תחת גמל [עצמו] והעובר בין שני גמלים והעובר בין שתי נשים והאשה העוברת בין שני אנשים והעובר מתחת ריח רע של נבילה והעובר תחת הגשר שלא עברו תחתיו מים מ' יום והאוכל פת שלא בשל כל צרכו והאוכל בשר מזוהמא ליסטרון והשותה מאמת המים העוברת בבית הקברות והמסתכל בפני המת ויש אומרים אף הקורא כתב שעל גבי הקבר","ת\"ר כשהנשיא נכנס כל העם עומדים ואין יושבים עד שאומר להם שבו כשאב ב\"ד נכנס עושים לו שורה אחת מכאן ושורה אחת מכאן עד שישב במקומו כשחכם נכנס אחד עומד ואחד יושב עד שישב במקומו בני חכמים ותלמידי חכמים בזמן שרבים צריכים להם מפסיעין על ראשי העם יצא לצורך יכנס וישב במקומו","בני ת\"ח שממונים אביהם פרנס על הצבור בזמן שיש להם דעת לשמוע נכנסים ויושבים לפני אביהם ואחוריהם כלפי העם בזמן שאין להם דעת לשמוע נכנסים ויושבים לפני אביהם ופניהם כלפי העם רבי אלעזר בר ר' [צדוק] אומר אף בבית המשתה עושים אותם סניפין","[אמר מר] יצא לצורך נכנס ויושב במקומו אמר רב פפא לא אמרו אלא לקטנים אבל לגדולים לא הוה ליה למבדק נפשיה מעיקרא דאמר רב יהודה אמר רב לעולם ילמד אדם עצמו להשכים ולהעריב כדי שלא יתרחק (אמר רבא) האידנא דחלשא עלמא אפילו לגדולים נמי","רבי אלעזר ב\"ר [צדוק] אומר אף בבית המשתה עושים אותם סניפים אמר רבא בחיי אביהם בפני אביהם","א\"ר יוחנן בימי רשב\"ג נישנית משנה זו רבן שמעון בן גמליאל נשיא רבי מאיר חכם רבי נתן אב\"ד כי הוה רשב\"ג התם הוו קיימי כולי עלמא מקמיה כי הוו עיילי רבי מאיר ורבי נתן הוו קיימי כולי עלמא מקמייהו אמר רשב\"ג לא בעו למיהוי היכרא בין דילי לדידהו תקין הא מתניתא","ההוא יומא לא הוו רבי מאיר ורבי נתן התם למחר כי אתו חזו דלא קמו מקמייהו כדרגילא מילתא אמרי מאי האי אמרו להו הכי תקין רשב\"ג","אמר ליה ר\"מ לרבי נתן אנא חכם ואת אב\"ד נתקין מילתא כי לדידן מאי נעביד ליה נימא ליה גלי עוקצים דלית ליה וכיון דלא גמר נימא ליה (תהלים קו, ב) מי ימלל גבורות ה' ישמיע כל תהלתו למי נאה למלל גבורות ה' מי שיכול להשמיע כל תהלותיו נעבריה והוי אנא אב\"ד ואת נשיא","שמעינהו רבי יעקב בן קרשי אמר דלמא חס ושלום אתיא מלתא לידי כיסופא אזל יתיב אחורי עיליתיה דרשב\"ג פשט גרס ותנא גרס ותנא","אמר מאי דקמא דלמא חס ושלום איכא בי מדרשא מידי יהב דעתיה וגרסה למחר אמרו ליה ניתי מר וניתני בעוקצין פתח ואמר בתר דאוקים אמר להו אי לא גמירנא כסיפיתנן","פקיד ואפקינהו מבי מדרשא הוו כתבי קושייתא [בפתקא] ושדו התם דהוה מיפריק מיפריק דלא הוו מיפריק כתבי פירוקי ושדו אמר להו רבי יוסי תורה מבחוץ ואנו מבפנים","אמר להן רבן [שמעון בן] גמליאל ניעיילינהו מיהו ניקנסינהו דלא נימרו שמעתא משמייהו אסיקו לרבי מאיר אחרים ולר' נתן יש אומרים אחוו להו בחלמייהו זילו פייסוהו [לרבן שמעון ב\"ג] רבי נתן אזל רבי מאיר לא אזל אמר דברי חלומות לא מעלין ולא מורידין כי אזל רבי נתן אמר ליה רשב\"ג נהי דאהני לך קמרא דאבוך למהוי אב ב\"ד שויניך נמי נשיא","מתני ליה רבי לרבן שמעון בריה אחרים אומרים אילו היה תמורה"],[[0,"שופתא","ביתד של מרא דעץ הוא גייץ:"],[1,"המניח כליו","מלבושיו:"],[1,"פת פחמין","פת האפוי בגחלים:"],[1,"","האוכל פת ופחמין עצמן כחדא חשיב להו:"],[1,"של שיורי העיסה","שנשתיירה מלישה:"],[2,"משכח למוד של ע' שנה","שסדור בפיו כל ע' שנה:"],[2,"משיב","מחזיר את הלמוד שנשתכח הימנו כבר ע' שנה:"],[4,"וסימנך","לגרסא שלא תטעה שאם לא תדע אם אחד אומר אחד ולא שתים ואחד אומר שתים ולא שלש או שמא אחד אומר שתים ולא שלש ואחד אומר שלש ולא ארבע יהא סימן קמיצה כלומר כפוף הקמיצה ונשתיירו מאותן אצבעות של יד העומדין לבד שתי אצבעות זקופין כסדרן מכאן דהיינו אצבע ואמה מכאן וזרת מכאן דהיינו שתי אצבעות מכאן ואצבע אחד מכאן ובכך תהא זכור שאחד אומר אחת ולא שתים ואחד אומר שתים ולא שלש גודל לא קא חשיב הכא עם שאר אצבעות משום דלא קאי בסדר אצבעות:"],[5,"קשים ללמוד","שהעושה אותן יהא קשה לשמוע:"],[5,"","העובר תחת אפסר גמל כ\"ש תחת גמל עצמו כחדא חשיב להו:"],[5,"העובר תחת ריח של נבילה","כלומר ההולך ומריח ריח נבילה דכל ההולך ומריח הוי עובר תחת אותו ריח שהריח הולך ועולה:"],[5,"זוהמא ליסטרון","אותו כף שבוחשין את הקדרה קרי להו הכי על שם שמעבירין הזוהמא לצדדין [על שני צדיו תרגום על תרין סטרוהי]:"],[6,"כל העם עומדין","כל השורות כולן אפילו הן מאה:"],[6,"","ועושין לו שתי שורות בלבד:"],[7,"עושין אותן","לבני חכמים שממונים אביהם פרנס על הצבור:"],[7,"סניפין","שמושיבין אותן בצד הזקנים מפני כבוד אביהם דהויין סניפין לזקנים כסניף זה שמצניפין לקורה גדולה סני\"ף בלע\"ז:"],[8,"אלא לקטנים","דאנוס הוא אבל יצא לגדולים אינו נכנס ויושב במקומו דפושע הוא משום דהוה ליה למיבדק נפשיה:"],[8,"כדי שלא יתרחק","דהיוצא לפנות ביום צריך שיתרחק מן הדרך כדי שלא יהו אחרים רואים אותו כדאמרינן במסכת ברכות:"],[9,"אמר רבא ובחיי אביהם","הא דעושים סניפין מפני כבוד אביהם:"],[10,"נשנית משנה","הא דתניא לעיל כשהנשיא נכנס וכו':"],[12,"נתקין מילתא כי לדידן","כלומר נעבד ליה כי היכי דעבד הוא לדידן ואית דגרסי נתקין מילתא כי ליתנן כלומר נתקין מילתא דלהוי לזכרון לעולם לדורות אפילו כי אינן בעולם ואית דאמרי נתקין מילתא כי ליתני לומר לו שילמדנו דבר שאינו יודע ללמוד ויתבייש:"],[12,"גלי עוקצים","ידרוש לן מסכת עוקצין:"],[12,"דלית ליה","שאין סדור לו:"],[13,"פשט","פירש:"],[13,"גרס ותנא","גרס ושנה:"],[14,"אמר","רבן שמעון בן גמליאל מאי דקמא דלמא חס ושלום כו':"],[14,"בתר דאוקים","בתר שסיים:"],[15,"ושדו ליה","לפיתקא בי מדרשא:"],[15,"","שאלות דהוה מיפריק מתרץ ומה שלא היה מתרץ כתבו אינהו הפירוקין ושדו בי מדרשא:"],[15,"[תורה מבחוץ כו'","או הם יכנסו לבהמ\"ד או אנו נצא אליהם ונשב עמהם]:"],[16,"נהי דאהני לך קמרא דאבוך","כלומר דאהני לך חשיבותא דאביך דהוית אב ב\"ד אבל למהוי נשיא מי אהני לך דקא בעית למהוי נשיא:"],[16,"קמרא","אבנט מוזהב כדאמרי' במסכת שבת בפ' במה אשה (שבת דף נט:):"],[17,"מתני ליה רבי לרבי שמעון בריה אחרים אומרים אילו (לא) היה תמורה לא היה קרב","דתנן במס' בכורות בפ' בתרא (דף ס.) קרא לתשיעי עשירי ולעשירי תשיעי ולאחד עשר עשירי שלשתן מקודשין התשיעי נאכל במומו והעשירי מעשר והאחד עשר קרב שלמים ועושהו תמורה דברי ר\"מ אמר לו רבי יהודה וכי יש תמורה עושה תמורה והא קיימא לן דאין תמורה עושה תמורה כדתנן במסכת תמורה בפ' קמא (דף ה:) אך בכור שור קדש הן וכו' הן קריבין ואין תמורתן קריבין ומעשר יליף עברה עברה מבכור כתיב הכא כל אשר יעבור תחת השבט וכתיב התם בבכור והעברת כל פטר רחם וגו':"]],[]],[["לא היה קרב אמר לו מי הם הללו שמימיהם אנו שותים ושמותם אין אנו מזכירים אמר ליה בני אדם שבקשו לעקור כבודך וכבוד בית אביך","אמר ליה (קהלת ט, ו) גם אהבתם גם שנאתם גם קנאתם כבר אבדה אמר ליה (תהלים ט, ז) האויב תמו חרבות לנצח אמר ליה הני מלי היכא דאהנו מעשייהו רבנן לא אהנו מעשייהו הדר אתני ליה אמרו משום רבי מאיר אילו היה תמורה לא היה קרב אמר רבא אפילו רבי דענוותנא הוא תנא אמרו משום ר\"מ אמר ר\"מ לא אמר","אמר רבי יוחנן פליגו בה רבן שמעון בן גמליאל ורבנן חד אמר סיני עדיף וחד אמר עוקר הרים עדיף","רב יוסף סיני רבה עוקר הרים שלחו לתמן איזה מהם קודם שלחו להו סיני עדיף דאמר מר הכל צריכין למרי חטיא ואפילו הכי לא קביל רב יוסף עליה מלך רבה עשרין ותרתי שנין והדר מלך רב יוסף וכל שני דמלך רבה רב יוסף אפילו אומנא לביתיה לא חליף","אביי ורבא ורבי זירא ורבה בר מתנה הוו יתבי והוו צריכי רישא אמרי כל דאמר מלתא ולא מפריך להוי רישא דכולהו איפריך דאביי לא איפריך חזייה רבה לאביי דגבה רישא א\"ל נחמני פתח ואימא","איבעיא להו רבי זירא ורבה בר רב מתנה הי מנייהו עדיף רבי זירא חריף ומקשה ורבה בר רב מתנה מתון ומסיק מאי תיקו:","\u0001הדרן עלך כהן משיח וסליקא לה מסכת הוריות\u0002"],[[1,"אמר ליה האויב תמו חרבות לנצח","דמשמע אע\"פ שכבר מתו חרבות לנצח ואין יפה להזכירם:"],[1,"אפי' רבי","דעניו הוה הכא לא נהוג ענותנותא יתירא דאמר משום רבי מאיר ולא רצה לומר בהדיא אמר ר\"מ:"],[2,"סיני עדיף","מי ששנה משנה וברייתא סדורין לו כנתינתן מהר סיני:"],[2,"וחד אמר עוקר הרים","דחריף ומפולפל בתורה אע\"פ שאין משנה וברייתא סדורין לו כל כך:"],[3,"","רב יוסף קרו ליה סיני לפי שהיו משניות וברייתות סדורות לו כנתינתן מהר סיני אבל לא היה מפולפל כרבה:"],[3,"הכל צריכין למרי חטיא","כלומר רב יוסף הוא מרי חטיא שמשנה וברייתא סדורין לו מפי השמועה כנתינתן מהר סיני דמשנה וברייתא אבוהון דהלכתא:"],[3,"אומנא לביתיה לא קרא","שלא רצה לנהוג שררה בעצמו כל אותן השנים שמלך רבה אפילו בהאי שררותא שלא רצה להביא שום אומן בתוך ביתו אלא כשהוא רוצה להקיז דם היה האומן על לביתיה דרבה ושם היה מקיז ואית דגרסי שלא רצה לנהוג שררות בעצמו כל אותן שנים שמלך רבה כלומר שלא היה לו פנאי להקיז עצמו אלא היה עוסק כל שעה בתורה לפני רבה:"],[4,"חזייה לאביי דגבה רישיה","כלומר ראה לו הרמת ראש:"],[4,"נחמני פתח","ואמור דרשא דמשמיא פסקו ליה רבותא אביי קרו ליה נחמני (ואיכא דאמרי דבלשון גנאי קרי ליה נחמני כלומר עדיין אתה תלמידו של רב נחמן):"],[5,"חריף ומקשה","מתוך פלפול יתירא דהוה ליה הוה מקשה ומתרץ אבל רבה בר מתנה לא הוה חריף כל כך אלא מתוך שהוא שוהה ומעיין יפה יפה מסיק אליבא דהלכתא:"]],[]]]};
